window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_029"]={"n":"杨慎","dyn":"明","poems":[{"t":"滇海曲 其十二","f":"七言绝句","c":["海滨龙市趁春畬，江曲鱼村弄晚霞。","孔雀行穿鹦鹉树，锦莺飞啄杜鹃花。"]},{"t":"滇海曲 其一","f":"七言绝句","c":["梁王阁榭水中央，乌鹊双星带五潢。","跨海虹桥三十里，广寒宫殿夜飘香。"]},{"t":"西征夜","f":"五言古诗","c":["寒重旅衾单，默对灯花谢。","乱山荒垒间，独客孤眠夜。","寂寞与谁同，寻思似梦中。","劳劳无止极，去去忘西东。","故乡孟冬别，有约仲冬返。","人愿天不从，长征日以远。","异县多相知，樽酒话心期。","含悲不能语，泪为生别滋。"]},{"t":"拟青青河畔草","f":"五言古诗","c":["河水清且涟，河上多芳草。","春风二月时，千里交河道。","交河汉家营，荒莽少人行。","日暮凄风起，黄沙与云平。","云间有孤雁，附书自乡县。","翩翩欲下来，闻弦却惊散。","草青雁北飞，草枯雁南归。","雁飞有归时，征人无还期。"]},{"t":"双燕曲","f":"五言古诗","c":["有鸟名飞燕，雄雌自相将。","饮君玉池水，巢君文杏梁。","美人当轩坐，恐涴罗衣裳。","请君驱除之，君怜不忍伤。","雏生八九子，娇爱比凤皇。","鸣声何啾啾，闻我庭东厢。","习飞还不远，堕坠双扉旁。","主人戒庐儿，毛羽无摧戕。","不啄五株桃，不啑五亩粱。","秋风从西起，翩翩向南翔。","昔为黄口儿，今为乌衣郎。","辞巢谢主人，华屋恩难忘。","愿主寿千岁，岁岁巢君堂。"]},{"t":"扶南曲 其一","f":"五言古诗","c":["春人辞曲房，罗绮杂花香。","远思河边草，柔情陌上桑。","归来庭下路，羞见紫鸳鸯。"]},{"t":"扶南曲 其三","f":"五言古诗","c":["清歌发皓齿，良夜足欢娱。","誓好同心结，迎祥百子图。","千金当一刻，城上莫啼乌。"]},{"t":"扶南曲 其四","f":"五言古诗","c":["游赏上春时，踟蹰望所思。","花娇初学脸，柳浅未成眉。","问讯沟头水，微波可致辞。"]},{"t":"扶南曲 其五","f":"五言古诗","c":["淇上轻盈侣，巫阳缥缈仙。","晚归因斗草，春困为秋千。","罗帐含双笑，灯昏尚未眠。"]},{"t":"垂柳篇","f":"七言古诗","c":["灵和殿前艳阳时，忘忧馆里光风吹。","千门万户旌旗色，九陌三条雨露滋。","苍凉苑日笼燕甸，缥缈宫云覆京县。","芳树重重归院迷，飘花点点临池见。","临池归院总仙曹，应制分题竞彩毫。","诏乘西第将军马，诗夺东方学士袍。","金明绿暗留烟雾，旧燕新莺换朝暮。","只知眉黛为君颦，肯信腰肢有人妒。","从此沉沦万里身，可怜憔悴四经春。","支离散木甘时弃，攀折荒亭委路尘。","摇落秋空上林远，婆娑生意华年晚。","肠断关山明月楼，一声横笛清霜坂。"]},{"t":"青海引","f":"七言律诗","c":["长白山前呺黑风，桔槔火照甘泉红。","五千貂锦血边草，单于夜帐移湟中。","华林酒艳长庚醉，沉香春浓海棠睡。","金马门如万里遥，那知青海城头事。"]},{"t":"明月篇","f":"五言古诗","c":["桂树生银汉，菱花挂玉台。","山明姑射雪，川静海童埃。","北户烛龙蛰，南枝乌鹊来。","清光殊窈窕，流影自徘徊。","楼上盈盈女，樽前滟滟杯。","孤桐不须荐，锦瑟正相催。"]},{"t":"大堤曲","f":"古风","c":["大堤二三月，垂杨千万把。","上枝堪藏鸦，下根堪系马。","藏鸦系马晚楼边，沉水香焚清酒传。","红霞宛宛歌声外，汉水团团明镜前。","夜饮朝眠欢不足，秋去春来芳草绿。","只知郎橐尽黄金，不道妾颜销白玉。","江有方洲岸有沙，牙樯丝缆各天涯。","钗横花困惊残梦，不信行人不忆家。"]},{"t":"新曲古意","f":"七言古诗","c":["淩波洛浦遇陈王，躧步邯郸缀舞行。","鸾尾凤头争嬿婉，麝脐龙脑斗芬芳。","巫阳台上春先到，汉月楼中夜未央。","结网嬉蛛垂藻井，营巢睇燕宿梅梁。","金仙素掌晞金露，玉女青腰袅玉霜。","翠织屏风交屈戍，红罗斗帐挂香囊。","腻鬟斜坠乌云滑，脂体横陈白雪光。","词赋楚王怜宋玉，画图天老教轩皇。","生憎露鹤催宵急，死恨星鸡促曙忙。","肯信王嫱嫔绝国，红颜清泪泣玄羌。"]},{"t":"养龙坑飞越峰天马歌","f":"古风","c":["高皇御天开大明，龙马出自养龙坑。","房星夜下鹿卢寨，天驷晓来骠骑营。","殿前重瞳回顾盼，奚官仗外争相迎。","鸡鸣牛首试控纵，凤师麟仪无逸惊。","归风绝尘羡迅疾，逮日先影羞翾轻。","四蹄翩然不蹍地，六飞如在空中行。","是时雄酋有奢香，左骖牡骊右牝黄。","贡上金陵一万匹，内厩惟称此马良。","宸游清燕幸鸾坡，学士承旨赞且歌。","饮以兰池之瑶水，秣以芝田之玉禾。","飞越峰名自天锡，骏骨虽朽名不磨。","至今百七十岁时，山头犹有养龙池。","方经地志或遗漏，箐苗洞獠那能知。","吾闻天下有道，飞黄伏皂。","又闻王良策马，车骑满野。","前时吉囊寇大同，烽火直达甘泉宫。","近日莫瀛乱交趾，羽书牙璋偏南中。","安得将星再降傅友德，房宿重孕飞越峰。","一月三捷献俘馘，千旄万旟歌熙雍。","呜呼将相宁有种，龙驵岂无媒。","经途访迹一兴慨，郭隗孙阳安在哉，长歌终曲长风来。"]},{"t":"题夏仲昭竹寄陶良伯","f":"七言古诗","c":["大常胸次潇湘宽，少年爱写生琅玕。","白头蓺苑更入妙，笔法远追王孟端。","两家名藻雄吴下，品题未觉风流亚。","一纸能令百世传，两竿不啻双金价。","人言画竹非画工，草书结构将无同。","谁家高堂名宝绘，徐熙花鸟迷青红。","玉人佳兴松江东，寄图索赋随长风。","遥知把玩清香里，正是相思明月中。"]},{"t":"击壤图","f":"古风","c":["陶唐天子调八风，凤仪兽舞明廷中。","谁知鼓腹行歌者，复有山中击壤翁。","短袖单衣露两肘，野状村容不自丑。","掀髯笑傲肩相随，共道帝力我何有。","柳谷饯日旸谷宾，老翁那记昏与晨。","一作一息有出入，时耕时凿无冬春。","蓂荚开残又朱草，生来未识平阳道。","海隅赤日烧九州，寰中息壤汨洪流。","已见天戈挥丹浦，更闻风伯殪青丘。","老翁其间百不忧，直从红颜到白头。","君不见许由逃尧劳步履，巢父洗耳污清泚。","华封老人费言辞，康衢小儿强解事。","姑射丰姿虽可珍，神仙彷佛信难真。","君看击壤千年后，多少行歌带索人。"]},{"t":"离席行送彭一","f":"七言古诗","c":["昔子从军巴蜀山，横戈千里何间关。","坐使麒麟日月焕，行收鱼鸟风云闲。","文武才名归一姓，兄弟勋华许谁并。","起晚已谢时运倾，当阳再睹乾坤正。","陟冈在原来复返，海水天风岁将晚。","行行白马燕雪深，飞飞黄鹄秦云远。","离堂命酒羽觞疾，毕昂盈轩月东出。","主人留连客离席，慷慨为子歌今夕。"]},{"t":"锦津舟中对酒别刘善充","f":"七言律诗","c":["锦江烟水星桥渡，惜别愁攀江上树。","青青杨柳故乡遥，渺渺征人大荒去。","苏武匈奴十九年，谁传书札上林边。","北风胡马南枝鸟，肠断当筵蜀国弦。"]},{"t":"过驻节桥读东阜刘远夫公碑文怆然有感","f":"古风","c":["溪尾水沄沄，峰头正夕曛。","含栖经驻节，洒泪读遗文。","桥南花如浣花好，桥北油油生碧草。","草色逐年新，花开又一春。","可怜东阜客，今作北邙尘。","忆昨锦江离别处，江边手折垂杨树。","千里还乡不见君，断肠邻笛山阳赋。"]},{"t":"普市","f":"七言律诗","c":["孤城比屋雪封瓦，重露浓岚幂四野。","飘飖风凹巧回鸢，凝涸冰槽工溜马。","倦客落日投主人，冷突无烟炊湿薪。","敢辞白首禦魑魅，眼见木夫尤苦辛。"]},{"t":"宿金沙江","f":"七言律诗","c":["往年曾向嘉陵宿，驿楼东畔阑干曲。","江声彻夜搅离愁，月色中天照幽独。","岂意飘零瘴海头，嘉陵回首转悠悠。","江声月色那堪说，肠断金沙万里楼。"]},{"t":"送余学官归罗江","f":"古风","c":["豆子山，打瓦鼓。","阳坪关，撒白雨。","白雨下，娶龙女。","织得绢，二丈五。","一半属罗江，一半属玄武。","我诵绵州歌，思乡心独苦。","送君归，罗江浦。"]},{"t":"恶氛行","f":"古风","c":["金碧山前恶氛起，虏马来饮滇海水。","城西放火银汉红，炎焰尘头高十里。","两重日晕围白虹，万家仰首呼苍穹。","相顾惨然无颜色，呜呼寄命须臾中。","贼徒浑几个，枕戈临水卧。","我军屯北门，分明不敢过。","土酋胁盟来索官，城上无言骑堞看。","父老仓忙双涕泗，细说去冬寻甸事。","弦急柱促柄倒持，首祸今朝竟何自。","堂堂之阵谁主兵，喁喁公等皆儒生。","贼来不肯令出哨，贼去但解抬空营。","岂无雄武士，奋身思一决。","咫尺辕门不肯前，怒发冲冠气填咽。","况闻千金逐日费，连月公储已倾竭。","土兵抄掠尽村园，升天无梯地无穴。","熙皞闾阎踰百年，太平官府真神仙。","紫薇迢迢华盖远，虚将敲朴威穷边。","边隅一旦纷解瓦，喑呜变作擎拳者。","喑呜擎拳两柰何，君不见建武年中任校尉，又不见开元年中张乾陀。"]},{"t":"三岔驿","f":"古风","c":["三岔驿，十字路，北去南来几朝暮。","朝见扬扬拥盖来，暮看寂寂回车去。","今古销沉名利中，短亭流水长亭树。"]},{"t":"送樊九冈副使归新繁","f":"古风","c":["别君于南云碧鸡之泽，追君于东城金马之坡。","酌君以莲蕊清曲之酒，侑君以竹枝巴渝之歌。","天涯岐路镇长在，故人零落浑无多。","忆昔君为汉阳守，沧浪之清古无有。","拂衣掉头不肯顾，饮冰旧谣在人口。","明诏复起句町行，官突未黔先濯缨。","宦游不博归故里，荣禄何如全令名。","九陇高冈白云野，吾庐世耕在其下。","清泠好结鸥鹭盟，春秋愿醉鸡豚社。","蜃雨蛮烟老玉关，小山丛桂不同攀。","愁心如月何时掇，夜夜随君梦里还。"]},{"t":"燕麦谣","f":"古风","c":["马牙冰，满林白。","损我苦荞伤燕麦。","甲子阴，鸟无食。","山头农，甸心客。","??荒眼双流血。","腊马躜，春牛吼。","癞象来，穷军走。","括金使者空城守。"]},{"t":"衍古谚","f":"五言古诗","c":["天马龙为友，来自渥洼池。","青丝为之络，黄金为之鞿。","圉人新承命，剪拂下瑶墀。","骑出横门外，茸茸春草时。","东城接南陌，观者咸嗟咨。","弄臣矜迅足，长鞭终日施。","汗血忽憔悴，筋力尽驱驰。","未树边隅绩，徒为冶游疲。","始信杀君马，端是路傍儿。"]},{"t":"秋风引","f":"五言律诗","c":["霜凛衔芦急，秋深悬炭轻。","觱篥吹篱响，熠耀傃阶明。","卢女流黄色，班姬捣素声。","谁教《明月引》，翻作《苦寒行》。"]},{"t":"星回之夕梦一美丈夫自称宋玉谓余曰公独无诗赠我乎梦中作一首四句觉后续之","f":"五言律诗","c":["文藻三闾并，幽怀《九辩》知。","云为巫峡赋，雪作郢中词。","茅屋还遗址，兰台异昔时。","鸿裁谁猎艳，空自拾江蓠。"]},{"t":"夕泊江陵","f":"五言律诗","c":["西陵白雪晴，南浦绿波生。","海燕先春至，沙禽恒夜惊。","竹房灯下市，花舫月中筝。","且醉桑郎酒，休伤萍客情。"]},{"t":"梓潼道中","f":"五言律诗","c":["小市孤烟起，平冈落日斜。","素林惊夕鸟，锦石戴寒花。","怅别关河晚，凭高眺望赊。","上亭今夜月，流影梦还家。"]},{"t":"早发解州","f":"五言律诗","c":["旅宿先鸦起，归心与雁争。","冰霜残腊路，花柳上春城。","隐士嘲西笑，骚人感北征。","劳生应物理，奔走愧虚名。"]},{"t":"乙酉元日新添馆中喜晴","f":"五言律诗","c":["白日临元岁，玄云放晓晴。","城窥冰壑迥，楼射雪峰明。","客鲤何时到，宾鸿昨夜惊。","离心似芳草，处处逐春生。"]},{"t":"层台驿","f":"五言律诗","c":["陡坡千百磴，破店两三家。","湿灶薪无焰，硗田饭有沙。","瘦兵宵泣血，猛虎昼磨牙。","行路难如此，羁愁一倍加。"]},{"t":"硖石道","f":"五言律诗","c":["石壕环陕驿，渑水带崤关。","东望封泥谷，南连积甲山。","秦轮无只返，赵璧有双还。","陈迹虚无里，荒台蔓草间。"]},{"t":"青桥","f":"五言律诗","c":["阁道盘云栈，邮亭枕水涯。","猿猱临客路，鸡犬隔仙家。","风起青丘树，春迷玉洞花。","旅怀今日豁，停幰问褒斜。"]},{"t":"九日微冷","f":"五言律诗","c":["巴谚教移火，邠风戒授衣。","病嫌添夜漏，寒觉爱朝晖。","吊月吟蛩苦，迎霜候雁稀。","黄花羞白发，不肯放荆扉。"]},{"t":"感通寺","f":"五言律诗","c":["岳麓苍山半，波涛黑水分。","传灯留圣制，演梵听华云。","壁古仙苔见，泉香瑞草闻。","花宫三十六，一一远人群。"]},{"t":"竹户","f":"五言律诗","c":["竹户少尘埃，浓阴郁不开。","静闻清露坠，凉送好风来。","鸟下弹琼粉，虫行篆紫苔。","无人共欣赏，坐啸独悠哉。"]},{"t":"次张大理文柔别后见寄韵 其二","f":"五言律诗","c":["垂老云南戍，逢君海上州。","桂招非小隐，萍泛是同流。","江汉询幽侧，关山慰阻修。","欲酬平子赠，空有畔牢愁。"]},{"t":"出塞","f":"五言律诗","c":["烽火照甘泉，刁斗出祁连。","锦车冲鸟穴，翠毦度鸡田。","高柳分斜月，长榆合远天。","交河冰正结，心断玉门前。"]},{"t":"春江曲","f":"五言律诗","c":["时女玩春翘，新梅发远条。","风香随步步，云彩艳朝朝。","怅望迷晴浦，音书候晚潮。","玉轮江上水，心断木兰桡。"]},{"t":"折杨柳","f":"五言律诗","c":["白雪新年尽，东风昨夜惊。","芳菲随处满，杨柳最多情。","染作春衣色，吹为玉笛声。","如何千里别，只赠一枝行。"]},{"t":"赠别陆后野","f":"五言律诗","c":["邂逅叶心期，灯花对酒卮。","浮云迁客梦，明月美人诗。","馆曙鸣鸡早，关寒度马迟。","行过宜禄驿，好寄世南碑。"]},{"t":"候朝简王舜卿","f":"五言律诗","c":["文华接武英，凤吹应鸡鸣。","月晃牙牌字，风传玉佩声。","天香飘左掖，宫漏隔西清。","不是班行迥，焉知夙夜情。"]},{"t":"舟晓","f":"五言律诗","c":["羁心厌漏迟，未晓命舟师。","树过如人立，帆开觉岸移。","天梭星落织，霞锦日舒丝。","渐喜渔村近，炊烟出竹篱。"]},{"t":"渡黑龙江时连雨水涨竟日乃济","f":"五言律诗","c":["飞鹢朝暾霁，停骖午漏分。","客心随水急，人语隔江闻。","雨过添清气，风生爱縠纹。","中流归棹稳，跂望有来群。"]},{"t":"沙河县","f":"五言律诗","c":["空碛少人烟，孤城大道边。","平沙盘马路，残雪射雕天。","野日三竿上，河冰百片穿。","条风将变柳，客思感流年。"]},{"t":"十二月朔旦南郊扈从省牲","f":"五言律诗","c":["天仗云门外，宵衣晓漏前。","苍龙旂影动，朱鹭鼓声传。","星烂甘泉烛，霜清泰畤烟。","南郊新警跸，重睹孝皇年。"]},{"t":"初寒拥炉欣而成咏","f":"五言古诗","c":["闭户当严候，围炉似故人。","胡桃无赐炭，榾柮有穷薪。","儿免号寒喜，翁便永夜亲。","焰腾金菡萏，灰聚玉麒麟。","剪烛休论跋，传杯莫记巡。","煎茶浮蟹眼，煨芋皱虬鳞。","一点那容雪，千门预借春。","灞桥何事者，冻缩苦吟身。"]},{"t":"荅彭子冲","f":"五言古诗","c":["异县悲南国，同车感北风。","霜清淮浦阔，木落楚江空。","危坂难回马，炎方少去鸿。","望归天共远，惜别岁将穷。","海曲飞鸣隔，山梁饮啄同。","从军古云乐，况复九夷通。"]},{"t":"送毛东镇往临安","f":"五言律诗","c":["缥缥碧鸡使，萧萧斑马群。","离亭方禁酒，征路正炎氛。","水弩含沙影，天鸢坠火云。","归音期蟋蟀，莫待海花纷。"]},{"t":"送张惟信册封唐邸因归省母","f":"五言律诗","c":["鸣玉遥持节，分圭重剪桐。","骅骝开蜀道，蟋蟀采唐风。","税驾云山外，回船月峡东。","还将《南陔》什，一奏北堂中。"]},{"t":"高峣卧疾喜简西峃至自滇城","f":"五言律诗","c":["隔户闻来屐，移灯坐对床。","澄心披乐雾，点鬓讶吴霜。","便欲开棋局，还思减药囊。","天涯故人少，且愿驻飞航。"]},{"t":"近归有寄","f":"五言律诗","c":["禄品宵征路，堂川暝问津。","凉风吹远思，新月照归人。","未醒鸡边梦，犹惊马上身。","明朝携手地，先醉雪梅春。"]},{"t":"寒夕","f":"五言律诗","c":["东西垂老别，前后苦寒行。","旅鬓年年秃，羁魂夜夜惊。","舂锄胸内贮，石阙口中生。","读书有今日，曷不早躬耕。"]},{"t":"八月二日经筵纪事","f":"五言古诗","c":["经帷当日表，讲殿直天中。","鹓鹭随多士，貂蝉列上公。","墀声分哕哕，棂影辨曈曈。","湛露晞兰省，卿云烂桂宫。","蚁浮仙酒绿，鹤翥锡袍红。","晋昼延三接，尧旻达四聪。","衣香芬玉藻，履迹印璇穹。","观易三阳泰，陈诗万国同。","宠高梁授简，恩迈汉临雍。","奎聚占乾象，研书识帝鸿。","羽陵无蚀蠹，玄阁谢雕虫。","瑩德同金砺，温规借玉攻。","扆瞻休气近，钟叩德音隆。","卷帙叨从事，簪裾俨在躬。","涓尘何补助，海岳自深崇。","敢诧桓荣力，还歌吉甫风。"]},{"t":"咏堠子","f":"五言古诗","c":["鼍记轩辕鼓，龟升夏禹图。","兜零清紫塞，寓望拱皇都。","水隔生烟直，山遮落照孤。","遒人春振铎，亭长晚吹菰。","原树遥分荠，城荒远辨芜。","淋铃蜀栈雨，疲旆楚江舻。","客思虚悲梗，吾生实射弧。","骖騑逵自达，兔鹿径休迂。"]},{"t":"晨雾","f":"五言古诗","c":["玄冥当凛节，白雾翳晨朝。","明月朦胧阁，清霜暧㬣桥。","冰澌工织水，花淞惯封条。","岚市天褰幕，烟坰陆涌潮。","凫亹迷独钓，鹿径滑归樵。","文彩南山豹，威凌北塞貂。","驷星收闪闪，曦景焕昭昭。","梅信悬知近，凭他酒帘招。"]},{"t":"雨夕梦安公石张习之觉而有述因寄","f":"五言古诗","c":["滇越邻天竺，邛崃隔夜郎。","五离殊畛域，一别异炎凉。","窜逐他时并，羁怀此夕长。","欢娱渐迢递，晤语落暝茫。","岚霭炎蒸国，烟波瘴疠乡。","秦关生马角，蜀岭断猿肠。","折坂沉黎壁，悬绳沬若梁。","南盘堆枸酱，西毾缉桄榔。","罗汉标孤桧，观音映远杨。","淜街龙簇市，海货贝投庄。","卉服喧丛薄，雕题列大荒。","逡巡乌爨弄，噭咷白狼章。","霄迥鸢飞站，星低蛊饮光。","堁风氛甚恶，菵露毒仍防。","树偃申家屋，荷凋屈氏裳。","独愁吟暟雪，九辩感清商。","永昼消棋阵，流年付酒狂。","抨弓穿鴶鵴，鼓枻泛螳螂。","康乐吴趋激，钟仪楚奏伤。","盼归频握糈，忆旧几停觞。","夙昔交游日，峥嵘翰墨场。","金兰通气味，桑梓借徽芳。","健笔誇鹦鹉，灵陶戛凤凰。","执鞭从李杜，倾盖许班杨。","贾谊三书切，相如四赋良。","轶尘追騕袅，缺岸倚踦牂。","百斛扛文鼎，千帆掣驶樯。","仙才轻绂冕，公望重圭璋。","蒲席青规地，薇垣紫界墙。","璇闺高曳履，琼涩俨分行。","笏捧绨囊奏，衣飘画省香。","辇花簪矗矗，池草佩锵锵。","儤直承明下，经过韦曲傍。","翠微横半岫，白水溢方塘。","暝宿招提境，云眠荟蔚房。","樵歌搴薜荔，渔影照沧浪。","倏忽嗟岐路，参差散颉颃。","薰华晨逗雨，蓂荚晓凌霜。","拂郁干将剑，联翻戍客装。","峨眉临绝顶，瀼水宛中央。","樾荫江枫赤，庭芜塞叶黄。","闭门非泄柳，畏垒讵庚桑。","纷绪琴心懒，衰颜镜匣藏。","屏居亲猰㺄，坐啸和蛩螀。","张敏情还剧，安期好不忘。","形骸元脱略，身世且徜徉。","蚓壤甘怡槁，鸿冥岂慕梁。","艰虞宁暇问，吾道任苍苍。"]},{"t":"云中十二韵","f":"五言古诗","c":["天子云中狩，将军久未还。","律吹玄兔塞，旗绕白狼山。","风火烧荒急，星辰过队闲。","燕支留马首，苏酪醉龙颜。","清乐千门动，黄金万镒颁。","雪深怀纩絮，月满忆刀镮。","牙鸟严宵仗，宫鸦捲晓班。","奏回青琐闼，捷报紫金关。","膂力休明铠，欢声洽禁阛。","功牌银烁爚，贺障锦斑斓。","日转虞巡外，春流镐宴间。","戢戈行有颂，神武遍人寰。"]},{"t":"寒朝早起即事","f":"古风","c":["篱头筚栗竞发，炉心榾柮通红。","煨香蹲鸱已熟，流澌冻醴方融。","小窗一梳新月，影在梅花树东。"]},{"t":"燉煌乐","f":"古风","c":["角声吹彻梅花，胡云遥接秦霞。","白雁西风紫塞，皂雕落日黄沙。","汉使牧羊旌节，阏氐上马琵琶。","梦里身回云阙，觉来泪满天涯。"]},{"t":"禺山传五岳山人任少海书札兼致问讯因忆","f":"古风","c":["五岳山人相忆，八行书札遥通。","吹箫夜郎月下，采药白帝云中。","尘世英雄易老，浮生踪迹难同。","张衡《四愁》吟断，宋玉《九辩》悲穷。"]},{"t":"长干三台 其一","f":"古风","c":["雁齿红桥仙舫，鸭头绿水人家。","邀郎深夜沽酒，约伴明朝浣沙。","桃叶波横风急，梅根渚远烟斜。"]},{"t":"长干三台 其二","f":"古风","c":["日出秦楼南畔，春深宋玉东家。","帘细眼波易透，窗疏眉语难遮。","莫问河阳消息，不是长安狭邪。"]},{"t":"长干三台 其三","f":"古风","c":["绛树纤腰斗柳，碧玉芳年破瓜。","波上袜罗回雪，风前唾袖生花。","自有石城艇子，不须油壁香车。"]},{"t":"长干三台 其四","f":"古风","c":["二月稍头豆蔻，五更风外杨花。","残香尚留翠被，馀粉犹沾绛纱。","楼上晓钟催起，岸边柔橹咿哑。"]},{"t":"会津门观江涨望小市人家戏作","f":"古风","c":["渺渺波环紫贝，萧萧风起青蘋。","花市宁非海市，美人疑是鲛人。","眉妩春山学翠，脸凝秋水为神。","银汉双星漫渡，石城两桨无津。"]},{"t":"归田四咏为宪副卞苏溪赋 其一 春耕","f":"古风","c":["五风十雨乐岁，东皋西崦人家。","水心鱼浮菖叶，屋角鸠鸣杏花。","饷陇青梅煮酒，访邻绿笋烹茶。","问津宁知沮溺，祠田但祝污邪。"]},{"t":"归田四咏为宪副卞苏溪赋 其二 夏牧","f":"古风","c":["长夏冷风清圳，新晴丹铅绿畴。","山高羊群似蚁，水阔牛背如舟。","半幅生烟幂幂，三腔短笛悠悠。","柴扉归来早掩，斜阳影在檐头。"]},{"t":"归田四咏为宪副卞苏溪赋 其三 秋渔","f":"古风","c":["日出烟消露晞，百丈清江钓矶。","船似天边稳坐，鱼若空行无依。","袄霭歌星独往，婆娑舞月方归。","兆熊不梦渭叟，狎鸥久忘汉机。"]},{"t":"归田四咏为宪副卞苏溪赋 其四 冬樵","f":"古风","c":["城阙软红尘远，林蛮空翠岚深。","丁丁鸟惊斧重，霏霏雪压担沉。","沙明东郭履迹，谷响南华足音。","归去自换村酒，不须解却貂金。"]},{"t":"咏梅九言","f":"古风","c":["昨夜小春十月微阳回，绿萼梅蕊早傍南枝开。","折赠未寄陆凯陇头去，相思忽到卢仝窗下来。","歌残《水调》沉珠明月浦，舞破山香碎玉凌风台。","错恨高楼三弄叫云笛，无柰二十四番花信催。"]},{"t":"寄徐用先程以道","f":"七言律诗","c":["轩辕台畔雪霜寒，阴碛茫茫万里宽。","梦绕卢龙明月易，书随鸿雁朔风难。","天涯好在崔亭伯，海上终还管幼安。","应念瘴乡孤戍者，自将形影吊衰残。"]},{"t":"至前二日朝天宫习仪","f":"七言律诗","c":["绯袍玉佩过长安，紫府珠庭引百官。","一代威仪非汉蕝，三成气象是周坛。","城头暝色笼轻雾，树杪新阳破早寒。","闻道宫衣添一线，恩光请向衮龙看。"]},{"t":"过南溪怀二刘参之承之兄弟","f":"七言律诗","c":["京国交游四十春，刘家兄弟最情亲。","风流云散三生梦，水逝山藏一聚尘。","沙步维舟催解缆，邻村闻笛倍沾巾。","可怜烟草江安树，愁见当年送别津。"]},{"t":"赠永宁白参戎","f":"七言律诗","c":["贵竹新疆古蔺州，分弓上将拥貔貅。","笙歌城郭天无夜，耒耜郊原岁有秋。","界首江清春洗马，海漫山翠晚当楼。","锐头勋业君家事，四十登坛早拜侯。"]},{"t":"春兴 其一","f":"七言律诗","c":["遥岑楼上俯晴川，万里登临绝塞边。","碣石东浮三绛色，秀峰西合点苍烟。","天涯游子悬双泪，海畔孤臣谪九年。","虚拟短衣随李广，汉家无事勒燕然。"]},{"t":"春兴 其二","f":"七言律诗","c":["昆明初日五华台，草长莺啼花乱开。","探禹穴游今巳遂，吊湘累赋未须哀。","巢云独鹤时时下，傍水群鸥日日来。","散地幸容高枕卧，清朝岂乏济川才。"]},{"t":"春兴 其三","f":"七言律诗","c":["诸葛提兵大渡津，河流禹凿迥如新。","彩云城郭那无迹，黑水波涛亦有神。","象马远来铜柱贡，犬羊不动铁桥尘。","灵关在眼平于掌，岁岁蒲桃苜蓿春。"]},{"t":"春兴 其五","f":"七言律诗","c":["帝里朝辞供奉班，客程宵济洞庭湾。","湘灵鼓瑟清泠外，鲛女鸣机缥渺间。","青草波光连梦泽，苍梧云物隔疑山。","故园亦有岷江水，垂老生涯钓艇閒。"]},{"t":"春兴 其六","f":"七言律诗","c":["平沙落日大荒西，独立苍茫意转迷。","蕙畹兰皋愁晚对，竹垣花掖记春栖。","摧颓杜甫歌朱凤，憔悴王褒望碧鸡。","白首艰难随去住，青云容易坠攀跻。"]},{"t":"春兴 其八","f":"七言律诗","c":["天上风云此际多，山中日月竟如何。","争传鸣凤巢阿阁，又见飞鸿出罻罗。","宣室鬼神思贾谊，中原将帅用廉颇。","难教迟暮从招隐，拟把生涯学醉歌。"]},{"t":"听歌","f":"七言律诗","c":["彩云天外驻行杯，明月楼前引上才。","红颊绽时银烛烂，翠眉低处玉山颓。","飘飖侠客游燕市，窈窕仙娥下楚台。","千载王郎风韵在，倩君重唱夕阳开。"]},{"t":"咏雾淞","f":"七言律诗","c":["怪得天鸡误晓光，青腰玉女试银妆。","琼敷缀叶齐如剪，瑞树开花冷不香。","月白讵迷三里雾，云黄先兆万家箱。","贫儿饭瓮歌声好，六出何须贺谢庄。"]},{"t":"六月十四日病中感怀","f":"七言律诗","c":["七十馀生巳白头，明明律例许归休。","归休已作巴江叟，重到翻为滇海囚。","迁谪本非明主意，网罗巧中细人谋。","故园先陇痴儿女，泉下伤心也泪流。"]},{"t":"杨林病榻罗果斋太守远访","f":"七言律诗","c":["荒店晨炊冷灶烟，忽闻五马暂流连。","关山尽是销魂路，樽酒翻为迸泪筵。","遥想生还成幻梦，纵令死去有谁怜。","眼前难缩壶中地，何问灵均楚国天。"]},{"t":"次云楼上公韵五月十九日鱼池雅会","f":"七言律诗","c":["环衢窈窕锦亭东，珍树留春缀糁红。","鸟度屏风青瘴里，鱼窥明镜碧澜中。","宾筵邺下诗篇盛，军次渔阳鼓角雄。","独有白头虚授简，梁园应愧长卿工。"]},{"t":"五丁峡旧传为力士开山之地据史秦用张仪司马错之谋以珍器美女赂蜀侯而取之小说迂怪传疑可也遂赋此诗","f":"七言律诗","c":["峡形千仞立苍颜，开辟从来有此山。","自是美人倾绝国，不缘壮士启重关。","蔡蒙早入梁州贡，庸蜀曾陈牧野间。","谣俗流传难借问，丹青遗迹尚班班。"]},{"t":"郫县子云阁","f":"七言律诗","c":["落景登临县郭西，坐来结构与云齐。","平郊远讶行人小，高阁回看去鸟低。","林表馀花春寂寂，城隅纤草晚萋萋。","酒阑却下危梯去，犹为风烟惜解携。"]},{"t":"中丞白泉汪公生辰值安南款报至","f":"七言律诗","c":["金潾铜柱贡函来，象渚龙编道路开。","上将简书回北极，中丞勋业冠南台。","拟将万舞排家宴，欲取铙歌献寿杯。","节钺可能淹衮舄，明年何地望三台。"]},{"t":"春夕潘园","f":"七言律诗","c":["雨砌风檐堕楝花，虫书鸟字遍晴沙。","春山载酒驰朝马，江阁邀宾起暮鸦。","陶令葛巾从渗漉，管宁纱帽任欹斜。","殊方未觉追随尽，韦曲风流更尔家。"]},{"t":"寄用贞弟","f":"七言律诗","c":["杜陵巴国苦寒行，李白梁园昨夜情。","山叶早梅心万里，雪窗风竹梦三更。","河桥晨别南凫影，江汉春催北雁声。","回首长安当日下，感时怀汝揔难平。"]},{"t":"嘉陵江","f":"七言律诗","c":["嘉陵江水向西流，乱石惊滩夜未休。","嵓畔苍藤悬日月，崖边瑶草记春秋。","板居未变先秦俗，刳木犹疑太古舟。","三十六程知近远，试凭高处望刀州。"]},{"t":"无题","f":"七言律诗","c":["石头城畔莫愁家，十五纤腰学浣沙。","堂下石榴堪系马，门前杨柳可藏鸦。","景阳妆罢金星出，子夜歌残璧月斜。","肯信紫台玄朔夜，玉颜珠泪泣琵琶。"]},{"t":"郑立之中丞平蜀石城夷寨有诗纪事次韵 其二 出关","f":"七言律诗","c":["狼狐芒角正弯环，虎落连营又出关。","汉使征鸿何日至，胡儿牧马几时还。","千重紫塞迷青冢，九曲黄河绕黑山。","飞将殊勋犹下吏，书生乘障敢辞艰。"]},{"t":"与诸弟别乐庵弟约有江阳之会","f":"七言律诗","c":["中宵风雨早来凉，谢草春池别梦长。","绿野开筵联玉树，红亭离思结垂杨。","通波直下无千里，明月何曾是两乡。","白昼看云何限意，佳期良晤在江阳。"]},{"t":"重寄张愈光 其二","f":"七言律诗","c":["海裔江湄独倚楼，瑟居匏系又惊秋。","菊花黄处回青眼，枫叶红时对白头。","少日声名追杜甫，暮途鞿绊脱庄周。","九龙尚有临池兴，一雁能忘远札投。"]},{"t":"泛莲池晚归","f":"古风","c":["桂枻兰?泛碧漪，芰塍莲荡倒芳卮。","十三雁足传情遍，二八蛾眉度曲迟。","玉树风前人散后，金波水上月明时。","良辰胜会应难续，风雨连宵恼别离。"]},{"t":"丁丑九日","f":"七言律诗","c":["燕台九日罢登临，节物萧条入楚吟。","关塞骅骝迷去路，朔风鸿雁滞归音。","仙游御宿山川远，白露清霜日夜深。","云际侧身愁北望，天涯怀抱可能禁。"]},{"t":"中秋禁中对月","f":"七言律诗","c":["汉家台殿号明光，月满秋高夜未央。","银箭金壶催漏水，仙音法曲献《霓裳》。","路车天远鸾声静，宫扇风多雉影凉。","千里可怜同此夕，美人迢递隔西方。"]},{"t":"春夕闻雨坐至晓寄熊南沙","f":"七言律诗","c":["半夜风声似水声，五更春雨遍春城。","被提芳草茸茸暗，镜渚夭花灼灼明。","墙过村醪仍冻蚁，窗临海树已暄莺。","天涯节物催华发，同是怀乡去国情。"]},{"t":"次韵奉酬中丞刘公侍御谢公除夕联句见怀","f":"七言律诗","c":["岁夕遥怜误忆家，月毫联锦灿缸花。","戍楼晓角传清燕，归棹寒江梦断鸦。","彩燕西飞边候改，碧鸡东望蜀云赊。","不知卧病衡天柱，何似穷愁瘴海涯。"]},{"t":"冬甲子晴江亭小集","f":"七言律诗","c":["晴意初从甲子回，江亭更集暖寒杯。","笑看裾带怜芳草，喜向钗梁见早梅。","潘岳不胜金谷罚，嵇康已觉玉山颓。","石苔可践城隅路，细把青溪古句裁。"]},{"t":"风雨","f":"五言绝句","c":["罗甸愁山雨，滇阳怯海风。","可怜风雨夜，长在客途中。"]},{"t":"恩波池别刘润之","f":"五言绝句","c":["酌酒临池水，回船拂芰荷。","匆匆马上去，留兴与烟波。"]},{"t":"荅段德夫水部 其二","f":"五言绝句","c":["天涯戎旅春，一十五回新。","多情花与鸟，岁岁有留人。"]},{"t":"唐僖宗行宫遗础次熊尚弼侍御韵","f":"七言律诗","c":["唐帝行宫有露台，础莲几度换春苔。","军容再向蚕丛狩，王气遥从骆谷来。","万里山川神骏老，五更风雨杜鹃哀。","始知蜀道蒙尘驾，不及胡僧渡海杯。"]},{"t":"宿华亭寺二首 其一","f":"五言绝句","c":["花树高于屋，红霞夜照人。","声声枝上鸟，也似惜余春。"]},{"t":"宿华亭寺花树高于屋红霞夜照人声声枝上鸟也似惜馀春 其一","f":"五言绝句","c":["天风与海水，鸣籁隔山闻。","半夜衣裳湿，清朝树树云。"]},{"t":"青桥夜宿","f":"五言绝句","c":["驿亭临白水，石榻满苍苔。","远客浑无梦，江声枕上来。"]},{"t":"夜行安庆","f":"五言绝句","c":["风顺月仍明，扁舟半夜行。","鸡鸣问前路，巳近九江城。"]},{"t":"青桥驿早发","f":"五言绝句","c":["远客贪晨发，三更梦巳回。","江声如骤雨，吹到枕边来。"]},{"t":"渝江登陆 其一","f":"五言绝句","c":["来往舟如屋，相随一月期。","登途不忍去，翻似别家时。"]},{"t":"春二首 其一","f":"五言绝句","c":["海风吹梅树，十日闭门中。","坐惜繁华过，墙头数落红。"]},{"t":"春二首 其二","f":"五言绝句","c":["行乐三春好，春来转剧愁。","乡心悲远望，莫上最高楼。"]},{"t":"春日过山家","f":"五言绝句","c":["山床压春酒，滴作涧泉声。","与君终日醉，松风吹复醒。"]},{"t":"雨后见月","f":"五言绝句","c":["雨气敛青霭，月华扬彩昙。","戏鱼莲叶北，惊鹊树枝南。"]},{"t":"捣衣杵","f":"五言绝句","c":["戕贼金钴鉧，击贼捣衣杵。","今见赵小钱，昔闻杨悯女。"]},{"t":"出郊","f":"五言绝句","c":["高田如楼梯，平田如棋局。","白鹭忽飞来，点破秧针绿。"]},{"t":"妙湛寺","f":"五言绝句","c":["废刹临官渡，香台夜景澄。","僧言龙火焰，却是打渔灯。"]},{"t":"玉台体 其一","f":"五言古诗","c":["流盼转相怜，含羞不肯前。","绿珠吹笛夜，碧玉破瓜年。","灭烛难藏影，洞房明月悬。"]},{"t":"玉台体 其二","f":"五言古诗","c":["调丝曲房下，援镜绮窗西。","妆罢金星出，歌残璧月低。","留欢夜未足，恨杀汝南鸡。"]},{"t":"绀甲丽人","f":"五言古诗","c":["银甲卸弹筝，花从玉指生。","逡巡捲罗袖，掩抑捧金觥。","莫摘相思子，琼枝最有情。"]},{"t":"楚江曲","f":"五言古诗","c":["巫山花巳红，楚水波新绿。","两两浣沙人，照影斗妆束。","笑问《竹枝词》，何如《采莲曲》。"]},{"t":"于役江乡归经板桥","f":"七言绝句","c":["千里长征不惮遥，解鞍明日问归桡。","真如谢脁宣城路，南浦新林过板桥。"]},{"t":"丘鸿夫苏时霖杨元达联席同宿广心楼枕上口占","f":"七言绝句","c":["六齿琼头饮百瓯，水楼寒榻话绸缪。","只须棋局销长夜，何用埋忧与寄愁。"]},{"t":"谢平江送至广通","f":"七言绝句","c":["明月清风渡两桥，相随百里不辞遥。","共怜话别无长夜，红烛清樽碧玉箫。"]},{"t":"咏史","f":"七言绝句","c":["月仗云门五彩毬，御前争赌最先筹。","须臾赢得西川印，便脱青衣拥碧油。"]},{"t":"青蛉行寄内 其一","f":"七言绝句","c":["青蛉绝塞怨离居，金雁桥头几岁除。","易求海上琼枝树，难得闺中锦字书。"]},{"t":"毛园萃芳亭与沈中白丘月渚同赋 其一","f":"七言绝句","c":["缭垣洞屋锁烟霞，五色离披百种花。","客子看来犹驻马，主人何事不归家。"]},{"t":"四月二日雨中拨闷","f":"七言绝句","c":["零雨崇朝不下楼，开窗烟外见渔舟。","今年四月寒犹在，坐拥红炉送酒筹。"]},{"t":"星回节","f":"七言绝句","c":["忽见庭花析剌桐，故园珍树几然红。","年年六月星回节，长在天涯客路中。"]},{"t":"闻笛","f":"七言绝句","c":["江楼寒笛起春声，蜀客扁舟万里行。","吹尽落梅还折柳，新春残腊正关情。"]},{"t":"赠筝人 其一","f":"七言绝句","c":["绮筵雕俎换新声，博取琼花出玉英。","肯信博陵崔十四，平生愿作乐中筝。"]},{"t":"赠筝人 其二","f":"七言绝句","c":["玄的檀痕画未成，翔鸾屏里斗轻盈。","罗虬若向今宵见，不比红儿比玉英。"]},{"t":"中秋","f":"七言绝句","c":["四壁蛩吟白露团，西园清夜为谁欢。","千家门闭中秋月，只有愁人独自看。"]},{"t":"三阁词 其一","f":"七言绝句","c":["桃根桃叶斗春葩，《水调》河传穆护砂。","无限江南新乐府，君王独赏《后庭花》。"]},{"t":"三阁词 其二","f":"七言绝句","c":["夜签声断灿朝霞，翡翠三千拥丽华。","舞罢前溪明月下，白门杨柳起藏鸦。"]},{"t":"早春","f":"七言绝句","c":["江暖波光映日光，几家同住水云乡。","槿篱茅屋繁花里，也有秋千出短墙。"]},{"t":"滇海曲 其二","f":"七言绝句","c":["碧鸡金马古梁州，铜柱铁桥天际头。","试问平滇功第一，逢人惟说颍川侯。"]},{"t":"滇海曲 其三","f":"七言绝句","c":["化城楼阁壮人寰，泽国封疆镇两关。","云气开成银色界，天工斲出点苍山。"]},{"t":"滇海曲 其五","f":"七言绝句","c":["沙金海贝出西荒，桃竹橦华贡上方。","香象渡河来佛子，白狼槃木拜夷王。"]},{"t":"滇海曲 其六","f":"七言绝句","c":["碉房草阁瞰夷庭，侧岛悬崖控绝陉。","鸡足巳穷章亥步，鹫头空入梵王经。"]},{"t":"滇海曲 其九","f":"七言绝句","c":["湖荡鱼虾晨积场，市桥灯火夜交光。","油窗洞户吴商肆，罗帕封颐僰妇妆。"]},{"t":"滇海曲 其十","f":"七言绝句","c":["蘋香波暖泛云津，渔枻樵歌曲水滨。","天气常如二三月，花枝不断四时春。"]},{"t":"滇海曲 其十一","f":"七言绝句","c":["煮海鹾郎暝漉沙，避风估客夜乘槎。","雪浮粳稻压春酒，霞嚼槟榔呼早茶。"]},{"t":"春望 其一","f":"七言绝句","c":["东风先到海东头，春兴催人独上楼。","最是晚来凝望处，曲堤烟柳似皇州。"]},{"t":"春望 其二","f":"七言绝句","c":["滇海风多不起沙，汀洲新绿遍天涯。","采芳亦有江南意，十里春波远泛花。"]},{"t":"春望 其三","f":"七言绝句","c":["古岸新花金碧丛，昆池三百水烟通。","梁王阁道青芜国，渔父帆樯白鸟风。"]},{"t":"贵竹杂咏 其二","f":"七言绝句","c":["绮缯缠髻作雕题，铁距穿鞋学马蹄。","清晓樵斤探虎穴，黄昏汲瓮下猿梯。"]},{"t":"八月十三日夜梦亡室安人惊泣而窹因思去年丁丑是日在京师安人未明兴告予曰今日趋朝不可如常日之宴盖其日警跸值新狩还也今遇是日感其贤淑又小子周二岁之晬重感赋绝句二首 其一","f":"七言绝句","c":["五更残梦正迷离，窗纸光明烛焰迟。","却忆去年当此日，催人晨起早朝时。"]},{"t":"八月十三日夜梦亡室安人惊泣而窹因思去年丁丑是日在京师安人未明兴告予曰今日趋朝不可如常日之宴盖其日警跸值新狩还也今遇是日感其贤淑又小子周二岁之晬重感赋绝句二首 其二","f":"七言绝句","c":["稚子今朝是两周，新衣戏舞拜前头。","伤心孺慕声声切，母在重泉听得不。"]},{"t":"赠宋文百户石冈舍人","f":"七言绝句","c":["七十从戎鬓已斑，劳君相送出滇关。","过家儿子如相问，为报衰翁二月还。"]},{"t":"征人早行图","f":"七言绝句","c":["杜鹃花下杜鹃啼，乌臼树头乌臼栖。","不待鸣鸡度关去，梦中征马尚闻嘶。"]},{"t":"海估行 其一","f":"七言绝句","c":["海估帆乘锦浪飞，绡宫夜取万珠玑。","翻身惊起蛟龙睡，血污清泠竟不归。"]},{"t":"海估行 其二","f":"七言绝句","c":["偃月堂空罢舞尘，靖安坊冷怨佳人。","芙蓉莲子随他去，不及当年石季伦。"]},{"t":"王子渊祠","f":"七言绝句","c":["玮晔灵芝发秀翘，子渊摛藻掞天朝。","汉皇不赏《贤臣颂》，只教宫人咏洞萧。"]},{"t":"浣溪沙","f":"七言古诗","c":["燕子衔春入画楼。","猧儿撼晓动帘钩。","一场残梦五更头。","彩凤琴中弹别调，锦麟书里诉离愁。","相思相忆几时休。"]},{"t":"滩破浣溪沙","f":"古风","c":["滟滟波光绿似醅。","茸茸草色嫩如苔。","只有轻寒浑不定，晚还来。","落梅村里昏鸦远，摆柳风前候雁回。","明日新晴堪眺望，上春台。"]},{"t":"小秦王 立春","f":"七言绝句","c":["红穗金花落绛台。","画楼银烛晓光催。","钗梁小燕双双颤，春自玉人头上来。"]},{"t":"朝中措","f":"古风","c":["经霜原草未全黄。","绿叶映红芳。","野客争夸稔岁，行人自笑炎方。","却思京国，狐裘貂帽，雪洞毡房。","不识琼楼高处，曝暄谁献吾皇。"]},{"t":"御街行 柳花","f":"古风","c":["城西杨柳千千树。","风起飞花絮。","青楼珠箔斗轻盈，还绕名园幽处。","满地香毬，满天晴雪，卷却春归去。","游人歌吹堤边路。","芳景须珍护。","眠开青眼舞慵腰，无计使风流住。","百啭残莺，一双新燕，九十春光暮。"]},{"t":"清平乐","f":"古风","c":["扁舟解缆。","春满江南岸。","灯火街头月正半。","客里年华又换。","倚遍阑干影斜。","行人回首天涯。","沙市桥南草色，章台寺里梅花。"]},{"t":"雨中花 春寒","f":"古风","c":["寒透水边沙际。","暖在花心叶底。","扫雪楼台，收灯庭院，向晚朱门闭。","丝额画帘低拂地。","舞袖弓鞋浑未试。","指冷金刀，香温翠被，懒剪宜春字。"]},{"t":"西江月","f":"古风","c":["紫塞朝朝烽火，青楼夜夜弦歌。","一朝明月雁声多。","带得边愁无那。","云阙九重阊阖，家山万里岷峨。","独愁乡思满蹉跎。","梁甫狂吟谁和。"]},{"t":"风入松 途中遇雪","f":"古风","c":["梦回灯烬旅衾单。","鸡唱五更寒。","一夜里、雪花飞遍，晓来时、千里漫漫。","野色遥连玉树，清光炯映银鞍。","行人休道路歧难。","酒盏自须宽。","一种风流堪画处，溪桥两两渔竿。","楼上笛声吹起，天涯梅蕊飘残。"]},{"t":"点绛唇","f":"古风","c":["雪暗江郊，小灯孤馆长宵半。","真珠酒艳。","冻作红冰片。","晓梦惊回，画角声初断。","南枝畔。","梅花开遍。","谁见春风面。"]},{"t":"小重山","f":"古风","c":["番马屏风睡燕梁。","更筹何太促、酒杯长。","花明月暗袅余香。","瞢腾里，醉眼怯灯光。","相忆阻横塘，今宵凭伏梦、到伊行。","玉山无赖隔巫阳。","天又晓，蝴蝶为谁狂。"]},{"t":"西江月","f":"古风","c":["寒食清明过了，牡丹芍药开残。","春光晼晚兴阑珊。","寂寂重门独掩。","秉烛谁同夜饮，添衣尚怯春寒。","欲寻芳草向江干。","榆荚杨花满岸。"]},{"t":"南乡子","f":"古风","c":["油壁香车。","来自钱塘苏小家。","行雨行云曾未惯，先誇。","双带同心结不差。","酒泛红霞。","银蜡烧残燕尾斜。","小语低声归去也，啼鸦。","风袅垂杨月隐花。"]},{"t":"如梦令","f":"古风","c":["屏底歌残金缕。","座上花催蜡炬。","春枕酒醒时，又是绿波南浦。","春去。","春去。","帘外潺潺微雨。"]},{"t":"少年游 春暮","f":"古风","c":["红稠绿暗遍天涯。","春色在谁家。","花谢蝶稀，柳浓莺懒，烟景属蜂衙。","日长睡起无情思，帘外夕阳斜。","带眼频移，琴心慵理，多病负年华。"]},{"t":"月中行","f":"古风","c":["月华静夜思悠哉。","夜静灭纷埃。","窥人不待画堂开。","圆影隙中来。","细轩朱缀香尘满，重门掩、露滴金苔。","洞房未晓且徘徊。","清漏不须催。"]},{"t":"卖花声 别金治卿","f":"古风","c":["骤雨打新荷。","绿涨清波。","风蒲猎猎映金沙。","池上玉尊移晚兴，共倚林柯。","莫惜醉颜酡。","听我离歌。","长亭回首碧云多。","千里怀人思命驾，何日重过。"]},{"t":"渔家傲 秋雨","f":"古风","c":["云掩遥山山掩翠。","雨声急战荷声碎。","绿锦离披红锦坠。","花叶背。","波间惊起鸳鸯睡。","潋滟芳尊人共对。","碧筒凉沁初消醉。","湿烟香雾笼归袂。","联玉辔。","南风马上闻蛙吹。"]},{"t":"如梦令","f":"古风","c":["云影月华穿过。","雨意钟声敲破。","洞户卷帘时，飞透流萤一个。","孤坐。","孤坐。","白雪金徽谁和。"]},{"t":"菩萨蛮 西瓜","f":"古风","c":["铅华浮沁凉波湿。","翠盘分处鸾羞涩。","座上水晶寒。","天边玉露团。","琼珠容易碎。","红子纷纷坠。","屈指又西风。","霞藤卧晚丛。"]},{"t":"乌夜啼 梅雨","f":"古风","c":["雨来江涨波浑。","没沙痕。","淹过竹桥莎径、到柴门。","孤烟起。","千树里。","几家村。","牛背一声长笛、报黄昏。"]},{"t":"清平乐","f":"古风","c":["芙蓉秋水。","一阵西风起。","木落波澄如镜里。","楼合参差相倚。","粉痕零乱红芳。","阑干点缀清霜。","掩却团团月扇，平湖昨夜新凉。"]},{"t":"蝶恋花","f":"古风","c":["云雨楚台容易散。","斗转星沈，玉漏迢迢断。","别语未终鸡已唤。","珊瑚枕上铅华淡。","剪剪秋波灯下见。","浅笑轻颦，一似花枝颤。","屈指归期重迭算。","多情翻作春闺怨。"]},{"t":"长相思","f":"古风","c":["十里亭。","五里亭。","长短亭边暮雨零。","离人不忍听。","梦初醒。","酒初醒。","夜半清寒入绮棂，凄凉掩画屏。"]},{"t":"宫中调笑 其一","f":"古风","c":["银烛。","银烛。","锦帐罗帏影独。","离人无语消魂。","细雨斜风掩门。","门掩。","门掩。","数尽寒城漏点。"]},{"t":"宫中调笑 其二","f":"古风","c":["香篆。","香篆。","碧缕青烟不断。","鸳鸯被底寒生。","云母窗前月明。","明月。","明月。","千里音尘愁隔。"]},{"t":"何满子","f":"古风","c":["通燕梅梁寒峭，藏鸦柳岸春阴。","南国东风偏到早，香消昼漏沉沉。","红满试灯庭院，青回斗草园林。","入眼风光堪赏，困人天气难禁。","一枕柔情牵断梦，觉来慵理琴心。","白雪新词易阕，碧云旧约休寻。"]},{"t":"昭君怨","f":"古风","c":["楼外东风到早。","染得柳条黄了。","低拂玉阑干。","怯春寒。","正是困人时候。","午睡浓于中酒。","好梦是谁惊。","一声莺。"]},{"t":"菩萨蛮 回文","f":"古风","c":["远林平望明霞晚。","晴野渡云轻。","夜凉新月挂。","星点数流萤。"]},{"t":"临江仙 其一 寄费子，和张维信","f":"古风","c":["碧水朱桥青柳岸，春风送别瀛州。","关河回首路悠悠。","尘埃如浪涌，亭传似星流。","忽见东园桃李树，还思宛洛遨游。","归期好在桂花秋。","凤箫留一曲，新酒待先驺。"]},{"t":"临江仙 其二 将至家寄所欢","f":"古风","c":["数了归期还又数，今朝才是归期。","独眠孤馆费相思。","梦阑鸡叫早，心急马行迟。","寄语同心双带结，休教瘦损腰肢。","花明月满尽来时。","先凭双喜鹊，报与个侬知。"]},{"t":"水调歌头 灵宝县赏牡丹","f":"古风","c":["春宵微雨后，香径牡丹时。","雕阑十二，金刀谁剪两三枝。","六曲翠屏深掩，一架银筝缓送，且醉碧霞卮。","轻寒香雾重，酒晕上来迟。","席上欢，天涯恨，雨中姿。","向人如诉，粉泪半低垂。","九十春光堪借，万种心情难写，欲将彩笔寄相思。","晓看红湿处，千里梦佳期。"]},{"t":"清平乐","f":"古风","c":["梧桐蟋蟀。","偏助秋萧索。","粉壁红高灯烬落。","月在阑干斜角。","千金一刻心期。","楚云湘梦来时。","不见桃花人面，空吟桃叶新词。"]},{"t":"柳梢青 其一 东桥送客登楼","f":"古风","c":["朝雨轻阴。","拖蓝远水，寸碧遥岑。","南浦怀归，东桥送别，并起乡心。","高楼且共登临。","愁思满、行杯谩斟。","黄菊丹枫，白苹红蓼，何处家林。"]},{"t":"柳梢青 其二 次遥岑楼韵答姜梦宾、杨从龙、张天翼","f":"古风","c":["异国光阴。","登龙忆孟，泛渼陪岑。","一发中原，孤踪万里，折尽丹心。","雪残亚岁将临。","一掬泪、离杯共斟。","红佛桑边，刺桐花底，肠断炎林。"]},{"t":"好女儿 其一","f":"古风","c":["柳似腰肢。","月似蛾眉。","看千娇、百媚堪怜处，有红拂当筵，金莲衬步，玉笋弹棋。","心事一春谁问，同心结，断肠词。","叹双鱼、不见征鸿远，蕉心绿展，樱唇红满，梅子黄肥。"]},{"t":"好女儿 其二","f":"古风","c":["锦帐鸳鸯。","绣被鸾凰。","一种风流千种态，看雪肌双莹，玉箫暗品，鹦舌偷尝。","屏掩灯斜香冷，回娇眼，盼檀郎。","道千金、一刻须怜惜，早漏催银箭，星沈网户，月转回廊。"]},{"t":"蝶恋花","f":"古风","c":["名园雨过晨妆洗。","冶叶倡条，何处闲桃李。","斜日帘栊风满地。","纷纷又逐东流水。","摇荡春心几千里。","欲网韶光，唤取游丝起。","燕懒莺慵春有几。","丁香枝上含新紫。"]},{"t":"青玉案","f":"古风","c":["盈盈春水桃根渡。","问芳信、来何暮。","青翰舟上，锦鸳波底，总是关情处。","合欢新种中庭树。","相思欲寄云南句。","为问佳期何日许。","飞鸿洲渚，流萤院宇。","银汉双星渡。"]},{"t":"行香子","f":"古风","c":["秋色萧萧。","秋气寥寥。","渐江头、露草萋萋，霜枫槭槭，风柳条条。","望水茫茫，舟泛泛，橹摇摇。","虫语要要。","蝶梦飘飘。","问家山、蚕崖渺渺，鱼波寂寂，雁阵嘹嘹。","但月溶溶，烟漠漠，路迢迢。"]},{"t":"临江仙 戍云南，江陵别内","f":"古风","c":["楚塞巴山横渡口，行人莫上江楼。","征骖去棹两悠悠。","相看临远水，独自上孤舟。","却羡多情沙上鸟，双飞双宿河洲。","今宵明月为谁留。","团团清影好，偏照别离愁。"]},{"t":"踏莎行 贵州尾洒驿元夕","f":"古风","c":["罗甸林中，新盘山下。","村灯社鼓元宵夜。","东风卷地瘴云开，月明满野寒星挂。","白雪歌声，青钱酒价。","当年乐事凭谁话。","寂寥孤馆坐愁人，小窗横影梅枝亚。"]},{"t":"雨中花 龙宝寺紫荆","f":"古风","c":["一搦纤腰清瘦。","六幅轻纱红皱。","粉熟香生，态浓妆浅，正是愁时候。","萧萧风雨黄昏后。","云湿仙衣寒透。","正帘悄窗闲，灯昏酒冷，听尽莲花漏。"]},{"t":"鹧鸪天 乙酉九日","f":"古风","c":["早岁辞家赋远游。","东西南北任萍浮。","熟知津路无劳问，惯听阳关不解愁。","临远水，望归舟。","流波落木又惊秋。","多情黄菊休添泪，且向尊前泛玉瓯。"]},{"t":"蓦山溪","f":"古风","c":["送君南浦。","繫马垂杨树。","攀折赠行，忍听道、一声别去。","愁眉泪眼，一步一回头，团山路。","高桥渡。","总是销魄处。","清风明月，好景成虚度。","重会在何时，算只有、梦中相遇。","衾寒枕冷，和梦也难成，思千缕，愁无数。","乱似风中絮。"]},{"t":"江城子 丙戌九日","f":"古风","c":["客中愁见菊花黄。","近重阳。","倍凄凉。","强欲登高，携酒望吾乡。","玉叠青城何处是，山似戟，割愁肠。","寒衣未寄早飞霜。","落霞光。","暮天长。","戍角一声，吹起水茫茫。","关塞多愁人易老，身健在，且疏狂。"]},{"t":"临江仙 寄刘建之","f":"古风","c":["寄语东桥东畔柳，且教留住行人。","与君相见即相亲。","忍看携手把，分作断肠津。","莫唱阑干花雾曲，温泉剩有余春。","明朝关索岭头尘。","相思千里外，回首一沾巾。"]},{"t":"庆春泽 安宁元夕","f":"古风","c":["鱼市笙歌，螳川灯火，又看滇海元宵。","剪剪轻风，绮罗十里香飘。","彩云影罩冰壶地，人家在、月户星桥。","恣经过、一刻千金，玉漏迢迢。","柳金梨雪催春早，叹他乡异节，回首魂销。","今夜相思、玉人何处吹箫。","锦江烟水迷归望，绿琴心愁恨慵调。","梦回时、酒醒灯昏，月转梅梢。"]},{"t":"满江红 梨花","f":"古风","c":["露重风香，韶华浅、玉林无叶。","谁剪碎，遍地琼瑶，满园蝴蝶。","娇泪一枝春带雨，粉英千片光凝雪。","伴秋千、影里月明中。","伤离别。","花在手，肠如结。","人对酒，情难说。","忆故园游赏，清明时节。","今日相逢滇海上，惊看烂熳开正月。","更收灯、庭院峭寒天，啼鹃歇。"]},{"t":"江城子","f":"古风","c":["滇南春似锦江春。","水鱼鳞。","柳蛾颦。","千树梨花，花底草如茵。","晴日暖风浓胜酒，熏媚眼，醉游人。","柔丝弱絮软红尘。","惜芳辰。","倦游身。","啼鸟惊心，何事唤归频。","不是不归归未得，愁望远，泪沾巾。"]},{"t":"浣溪沙","f":"七言古诗","c":["珠树三花惜共攀。","尊前又唱小阳关。","雏莺学语唤春还。","桃叶渡头流恨水，绿杨亭上画眉山。","酒醒人在梦魂间。"]},{"t":"蝶恋花","f":"古风","c":["夭似花枝轻似雾。","香烬灯昏，梦入瑶台路。","枕上眉山重碧聚。","偎人若把离情诉。","乞巧楼中携手处。","夜夜相思，今夕重相遇。","最恨五更留不住。","航帆风送高桥渡。"]},{"t":"南歌子 羁怀","f":"古风","c":["黄鹤蓬莱岛，青凫杜若洲。","愁人寂夜梦仙游。","不信一身流落，向南州。","万里家山路，三更海月楼。","离怀脉脉思悠悠。","何日锦江春水，一扁舟。"]},{"t":"巫山一段云","f":"古风","c":["背壁羞娇影，回灯脱薄妆。","暗中惟觉绣鞋香。","解佩玉丁当。","好梦云将结，幽欢夜正长。","迟迟懒上郁金床。","故意恼檀郎。"]},{"t":"水龙吟 咏梅","f":"古风","c":["汉宫娇额涂黄，风流早露春消息。","铅华莹雪，冰肌照水，盈盈无力。","弄影轻颦，向人微笑，芳心谁识。","对珠帘不掩，绮窗半露，嫣然一笑倾国。","最恨昏黄月黑。","迷花丛、枝南枝北。","寿阳妆减，罗浮梦断，春宵一刻。","皴玉谁温，凝脂自暖，空劳相忆。","正香残漏俏，灯昏酒冷，此情何极。"]},{"t":"山花子 其一 咏软枝条同心山茶花","f":"古风","c":["袅袅同心巧笑分。","粉霞红绶藕丝裙。","软翠柔蓝擎不定，晓妆匀。","醉露屏前双朵朵，舞风庭下一群群。","不肯嫣然回一顾，为思君。"]},{"t":"山花子 其二 咏红边分心小山茶","f":"古风","c":["瑞雪晴林暮霭消。","锦云香坞彩霞飘。","绝代佳人空谷里，路迢迢。","鹤顶研砂添赤髓，猩唇滞酒晕红潮。","小朵分心堪采掇，当琼瑶。"]},{"t":"渔家傲","f":"古风","c":["千里有家归未得。","可怜长作滇南客。","愁见陌头杨柳色。","伤远别。","多年故国曾攀折。","望断乡山音信绝。","那堪烽火连三月。","夜夜相思头欲白。","心似结。","五更梦破闻啼鴂。"]},{"t":"无俗念 游仙二首 其一","f":"古风","c":["十年奔走，向红麈、何处可寻蓬岛。","一枕青瓷惊梦起，幻迹都如扫。","七返还丹，千龄大药，昧者难精讨。","餐霞伴侣，飘然遥在天表。","长生须住仙村，诛茅贺厦，迥出层云抄。","翠水蓝岑浑不夜，紫府丹丘常晓。","玉豉金盐，璚英珠液，种种供难老。","乖龙莫懒，为我先耕瑶草。"]},{"t":"无俗念 游仙二首 其二","f":"古风","c":["匏瓜河上，问津时、半夜朝先归晚。","鹤倦鸾慵行且住，谁遣昌容迎幰。","朝采帘掀，夜光杯举，留醉青霞苑。","玉颜掩樗，笑看泓水清浅。","谪来尘世何年，青精紫倩。","全县侣怀同搴。","灵境壶天飙霭隔，座上玉书尘满。","赤鲤琴高，青鸾阿母，问讯行当反。","五潢似镜，白榆历历秋剪。"]},{"t":"浣溪沙","f":"七言古诗","c":["南国何年桂女笺。","蕊黄金粉斗芳妍。","风流应自锦江传。","佛幌烟煤犹自馥，蛮方文物也堪怜。","为君重染古苔篇。"]},{"t":"沁园春 其一 己丑新正","f":"古风","c":["甚矣吾衰，叹天涯岁月，何苦频催。","奈霜毫种种，三千盈丈，丹心炯炯，一寸成灰。","三径秋荒，五湖天远，儒术于吾何有哉。","君知否，盼行云不住，流水难回。","寂寥谁与徘徊。","好事者、惟输曲秀才。","恁昏花老眼，底须窥牖，支离病脚，最怯登台。","思发花前，人归雁后，百感中来强自裁。","狂歌好，只清风和我，明月休猜。"]},{"t":"沁园春 其二 己丑新正","f":"楚辞体","c":["自寿一杯，休行吟泽畔，兀坐山隈。","笑穷兵独舞，干戈载戢，却胡长啸，铅椠何才。","归去来兮，呜呼老矣，生入玉门何日哉。","新春好，且提壶沽酒，共赏花开。","催花击鼓如雷。","酒色似、蒲桃初发醅。","任天河水泻，流干银汁，月轮桂老，撑破珠胎。","岛上红云，洞中香雪，醉倒花娘锦被堆。","与君约、这醉乡深处，不饮休来。"]},{"t":"沁园春 其三 己丑新正","f":"古风","c":["劝汝一杯，关山迢递，我马崔隤。","想玉堂金马，曾同富贵，竹篱茅舍，也共尘埃。","事过眼前，老来头上，卿不见吾白发哉。","故园好、更彩衣称寿，何日同回。","天涯劝我宽怀。","欠酒债、拔卿金雀钗。","笑孔肩薄首，夫人书法，嵇心羊体，仙子琴才。","道韫家声，黔娄夫婿，此怨休将造化埋。","六如偈，棒打开梦幻，新拜如来。"]},{"t":"沁园春 其四 己丑新正","f":"古风","c":["愁汝休来，且天边高寄，地下深埋。","自戊申吾降，酒星正照，辛壬师授，酒诰蒙开。","若下乌程，兰生桑落，行辈都将兄弟排。","二豪者，便螟蛉蜾蠃，如我何哉。","酒中兴岂无媒。","要月户、风亭白雪阶。","况鸾腔凤调，浮丘按拍，霞浆金醴，王母添杯。","洞里春浓，壶中夜永，童子休将鹤驾催。","玄真侣，烦诸君为我，筑醉仙台。"]},{"t":"瑞龙吟 杏花","f":"古风","c":["东风峭。","谁猜水剪余霞，日烘残照。","妆成窥宋东墙，倾城倾国，嫣然一笑。","轻笼罩。","叶底烟开冉冉，枝头春闹。","燕泥香里，斜阳酒旗映水，天涯一棹。","消息繁华谁报。","记曲江池上，长安古道。","愁落愁开，雨横风暴。","沈吟无语，时把朱阑靠。","知谁伴、单衫露冷，醉红簪帽。","倚醉狂歌浩。","悠悠尽是伤离调。","花艳为谁好。","春又晚、可惜年华空老。","关山迢递，故人难到。"]},{"t":"捣练子","f":"古风","c":["春梦浅，夜筹添。","懒唱新翻阿鹊盐。","黛角歌眉颦翠滴，绣尖绒舌唾红甜。"]},{"t":"生查子 其一 款残红","f":"五言律诗","c":["花径款残红，风沼萦新皱。","有意惜余春，无计消长昼。","香醪泻玉洼，瑞脑喷金兽。","谁与共温存，寂寞黄昏后。"]},{"t":"生查子 其二 款残红","f":"五言律诗","c":["频移带眼空，只恁恹恹瘦。","不见又思量，见了还依旧。","为问频相见，何似长相守。","天生并头莲，好结同心藕。"]},{"t":"西江月","f":"古风","c":["客里家家美酒，人生处处扬州。","娇歌聒帐醒扶头。","年少风流还有。","世事今成白首。","归心已付东流。","替人憔悴替人愁。","笑杀长亭古柳。"]},{"t":"天仙子","f":"古风","c":["忆共当年游冶乐。","小小池塘深院落。","相亲相近不相离，花下约。","柳下约。","一曲当筵金落索。","回首欢娱成寂寞。","惊散鸳鸯风浪恶。","思量不合怨旁人，他也错。","我也错。","好段因缘生误却。"]},{"t":"人月圆 泛大理海子","f":"古风","c":["好风雨日相迎送，渺渺碧波平。","玉几云凭，金梭烟织，宝刹霞明。","邀散神仙，寻闲洲岛，上小蓬瀛。","海流东逝，海天南望，海月西生。"]},{"t":"误佳期 壬辰元夕","f":"古风","c":["今夜风光堪爱。","可惜那人不在。","临行多是不曾留，故意将人怪。","双木架秋千，两下深深拜。","条香烧尽纸成灰，莫把心儿坏。"]},{"t":"浣溪沙 集句","f":"七言古诗","c":["洞里仙人碧玉箫。","一渠春水赤栏桥。","绿窗虚度可怜宵。","沈麝不烧金鸭冷，障泥未解玉骢骄。","长亭回首短亭遥。"]},{"t":"天仙子 梦作","f":"古风","c":["莲叶为舟丝作索。","渡口梅风歌扇薄。","一声留得满城春，金凿落。","银凿落。","醉里不知离绪恶。","别后那回华表鹤。","一点芳心无处着。","云中谁寄锦书来，春寂寞。","人寂寞。","绿遍汀洲生杜若。"]},{"t":"蝶恋花 足范文正公遗句","f":"古风","c":["香颈垂云眉倒晕。","珠翠丛中，没个他风韵。","浪蝶狂蜂遍有分。","为谁偷把红销印。","锦字花笺难问讯。","一寸相思，只与黄昏近。","薄倖负人终不忿。","何时枕上分明问。"]},{"t":"满庭芳 感通寺赠承道玄、杨伯清","f":"古风","c":["环海烟霞，冠山楼阁，天涯万里凭阑。","瑶台高处，携手蹑飞鸾。","病起带围宽尽，朱颜改、青镜羞看。","风情减，停歌罢笑，愁对酒杯宽。","清欢。","听牛背，一声牧笛，云散漫漫。","问玄谷冰壶，禅伯仙官。","庭下丁香树子，花开后、又见花残。","从吾好，玉毫光里，一粒现金丹。"]},{"t":"风入松 马上喜晴","f":"古风","c":["刺桐花里咽新蝉。","方响落寒泉。","远山凝黛修蛾敛，谁妆点、淡粉浓胭。","嫩水靴文蹙浪，娇云卯色烘天。","碧池荷叶又田田。","藕在阿谁边。","莲子擘开须见意，香丝到底相牵。","留取团团宝月，西楼共醉婵娟。"]},{"t":"柳稍青 李菊亭将军席上","f":"古风","c":["雨歇仙家。","香尘随马，晚霭迎车。","玉树歌春，金屏笑夜，银烛烘霞。","流年两鬌霜华。","且烂醉、东篱菊花。","不学江州，青衫司马，泪满天涯。"]},{"t":"满江红","f":"古风","c":["覆雨翻云，纷纷轻薄何须说。","眼见儿曹富贵，灰消烟灭。","百事有隆还有替，一毫无玷原无缺。","把浊醪、粗饭任吾年，看豪杰。","也莫羡，炎如热。","也莫笑，凉如雪。","自扫雀罗门巷，世情都隔。","借问东华尘与土，何如南浦风和月。","报山涛、不用问嵇康，交情绝。"]},{"t":"满庭芳 效东坡作","f":"楚辞体","c":["归去来兮，半生歧路，天涯南北西东。","弋人何慕，造化任冥鸿。","曾是先朝执戟，今衰矣、白首扬雄。","休点检，并游英俊，五相一渔翁。","丹衷。","举头望，长安万里，一朵云红。","把致君尧舜，付与诸公。","赢得老身强健，尽驱使、明月清风。","浣溪畔，先生醉也，拍手笑儿童。"]},{"t":"浣溪沙","f":"七言古诗","c":["楚峡云娇宋玉愁。","汀花海藻繫兰丹。","晕灯荧泪五更头。","桃叶桃根双姊妹，江南江北两风流。","佳期好在月明楼。"]},{"t":"天仙子","f":"古风","c":["浪飐桃花风滚絮。","春色可能留得住。","四眸相顾两埋冤，金齿路。","金马路。","总是销魂离别处。","红雀蜻蜓难共树。","紫燕伯劳相背去。","一番新恨又从头，他也误。","我也误。","孤馆乱山愁日暮。"]},{"t":"菩萨蛮 大理普宁寺中秋","f":"古风","c":["花宫露下秋如水。","月明千里人千里。","莫上最高楼。","天际添别愁。","一时今夕会。","且共尊前醉。","踪迹似飘蓬。","明年何处逢。"]},{"t":"浣溪沙","f":"七言古诗","c":["何处春娇晚晕多。","分梢新月浅檀蛾。","千金一斛带青螺。","情泪乱抛红瑟瑟，梦云深锁碧蛾蛾。","细腰肠断掌中歌。"]},{"t":"玉蝴蝶 梁生镇园亭有兰名玉瑚蝶，即席赋一首","f":"古风","c":["蝴蝶不随春去，玉英瑶蕊，犹自娟娟。","潇洒水边林下，洗净朱铅。","嫦娥来、梁园月下，青女降、楚畹霜前。","更山阴、婆娑一老，觞咏群贤。","当年。","紫茎绿叶，纫华杂佩，故事陈篇。","何似今宵，长歌石磴泻红泉。","醉归去、香携满袖，似相逢、解佩江仙。","散尘缘、猗猗一曲，琼轸冰弦。"]},{"t":"沁园春 自寿兼谢钝庵","f":"古风","c":["初度今年，遥集句东，丹壶洞天。","记京国俊游，筑金台上，乡亭旧话，濯锦城边。","两地萍蓬，十年烟月，欲往从之如绊然。","今何夕，又满堂花醉，重对华筵。","新杨窈窕春妍。","正绿萼、梅花开最先。","况凤侣潘杨，兆呈琼齿，龙媒秦晋，应在冰泉。","画里萧郎，瓮中毕叟，绛帐风流群桂仙。","上云乐，倾壶箫管，白发重玄。"]},{"t":"临江仙","f":"古风","c":["玉蕊娟娟花灼灼，银釭背解明珰。","澹云轻雨拂高唐。","不言惟有笑，多媚总无妆。","却怪汝南鸡唱早，行踪不辨回廊。","青苔幽径落红香。","宝钗寒挂月，罗袜冷侵霜。"]},{"t":"南歌子八首 其一","f":"古风","c":["红叶随流水，青梅出短墙。","雅意属檀郎。","可怜人二八，好风光。"]},{"t":"南歌子八首 其二","f":"古风","c":["粉泪盈纤手，春愁占两眉。","细雨阻佳期。","昨宵当此际，恰来时。"]},{"t":"南歌子八首 其三","f":"古风","c":["窗面秋千月，墙头蓓蕾风。","春事转头空。","酒醒人散后，拾残红。"]},{"t":"南歌子八首 其四","f":"古风","c":["青鸟飞相逐，乌龙卧不惊。","镜约与钗盟。","月沈星欲堕，奈何情。"]},{"t":"南歌子八首 其五","f":"古风","c":["月是巫娥伴，花为宋玉邻。","远似隔星津。","早知离恨苦，莫相亲。"]},{"t":"南歌子八首 其六","f":"古风","c":["灯下蠲红纸，花间擘彩笺。","肠断写新篇。","画粱新燕子，倩他传。"]},{"t":"南歌子八首 其七","f":"古风","c":["丝品娟娟玉，钗梁灼灼花。","妙语似雏鸦。","有心来恼我，莫应他。"]},{"t":"南歌子八首 其八","f":"古风","c":["片玉连城价，千金一刻宵。","仙梦隔蓝挢。","意中人不见，为谁娇。"]},{"t":"长相思","f":"古风","c":["雨声声。","夜更更。","窗外萧萧滴到明。","梦儿怎么成。","望盈盈。","盼卿卿。","鬼病恹恹太瘦生。","见时他也惊。"]},{"t":"虞美人","f":"古风","c":["檀槽凤尾龙香拨。","一串骊珠落。","风流傅粉媚何郎。","解唱春风一曲杜韦娘。","溶溶阴锁梨花院。","宋玉愁空断。","虚无只少对潇湘。","却似满城风雨近重阳。"]},{"t":"浣溪沙","f":"七言古诗","c":["巫峡行云洛浦风。","秦楼西畔宋家东。","滴春娇泪雨濛濛。","龟甲歌屏朝掩翠，蛾眉妆镜晚窥红。","寂寥门闭杏花丛。"]},{"t":"木兰花","f":"七言律诗","c":["弓鞋一掬凌波迥。","冉冉盈盈羞顾影。","擎茶步缓扎花凝，斗草归迟苔露冷。","雪皱云松倩郎整。","罗帐灯昏莲瓣瞑。","掌中无力搦琼枝，渴思半消残酒醒。"]},{"t":"薄倖","f":"古风","c":["碧鸡催晓。","正话别、匆匆未了。","又咫尺、销魂桥上，南浦绿波芳草。","记昨宵、醉褶罗襟，玉山拚为金樽倒。","爱皎皎当窗，盈盈隔水，那个人儿窈窕。","自油壁香车去后，路远西陵月悄。","恨同心带缓，露兰啼歇，多情却被无情恼。","最萦怀抱。","把双双骰子，重重喝采占佳兆。","桃花有意，前度刘郎未老。"]},{"t":"滇春好 寄李南夫、钱节夫、毛东镇","f":"古风","c":["滇春好，韶景媚游人。","拾翠东郊风袅袅，采芳南浦水鳞鳞。","能不忆滇春。","滇春好，百卉让山茶。","海上千株光照水，城西十里煖烘霞。","能不忆滇花。","滇春好，翠袖拂云和。","雅淡梳妆堪入画，等闲言语胜听歌。","能不忆滇娥。","滇春好，最忆海边楼。","渔火夜星明北渚，酒旗风影荡东流。","早晚复同游。"]},{"t":"浣溪沙 欧园离席，与刘珥江同赋","f":"七言古诗","c":["雾鬓风鬟晚雨收。","石城艇子似新秋。","弯弯月出挂城头。","桃叶桃根牵别恨，垂杨垂柳绾离愁。","丽词都付雪儿讴。"]},{"t":"鹧鸪天 其一 杜鹍花","f":"古风","c":["水蝶岩蜂总不知。","艳红凝露万千枝。","石家锦帐遮金谷，王母霞幢照羽旗。","香雨歇，彩云移。","煖风晴日醉胭脂。","山深春晚无人赏，又是啼鹃叫落时。"]},{"t":"鹧鸪天 其二 雨中留杨戣琴士饮","f":"古风","c":["高阁遥岑送远青。","倚阑高咏有人听。","子弦乍咽新双调，卯醉难消软半瓶。","烟漠漠，雨泠泠。","留君且住会心亭。","谢公棋墅思同乐，渔父江潭笑独醒。"]},{"t":"六州歌头 吊诸葛","f":"古风","c":["伏龙高卧，三顾起隆中。","割宇宙，分星宿，借江东。","祝东风。","端坐舌战徂公。","激公瑾，连子敬，呼翼德，挥白羽，楚江红。","乌韵惊飞，虎踞蚕丛地，炎焰重融。","吞吴遗恨在，受诏永安宫。","尽悴苍穹。","鉴孤忠。","念行营草出师表，心匪石，气凌虹。","岁去志，年驰意，早成翁。","目断咸潼。","出五丈，屯千井，旗正正，鼓冬冬。","天亡汉，将星陨，卯金终。","巾帼食槽司马，生魄走、死垒遗弓。","遣行人到此，千古气填胸。","多少英雄。"]},{"t":"鹧鸪天","f":"古风","c":["锦地香霏织雨丝。","蟠桃腻叶染春姿。","薛涛红粉临妆怯，周昉丹青点笔迟。","同醉处，旧游时。","卷中似欠海棠词。","酒徒云散佳人远。","孤馆残灯恼梦思。"]},{"t":"江月晃重山 四阕 其一 壬寅立春","f":"古风","c":["腊尾金杯滟滟，春头彩胜翩翩。","裁红晕碧动嫣然。","风日好，偷眼艳阳天。","一曲玉箫明月，几弦锦瑟华年。","故乡迢递水云连。","归未得，思发在花前。"]},{"t":"江月晃重山 四阕 其二 壬寅立春","f":"古风","c":["金马九重恩谴，碧鸡二十春风。","江花江草每年同。","君不见，憔悴已成翁。","白发带花休笑，紫髯说剑犹雄。","欲笺心事向天公。","赊美酒，长醉玉壶中。"]},{"t":"江月晃重山 四阕 其三 壬寅立春","f":"古风","c":["屏翳烘云靺鞨，羲和敲日玻瓈。","韶风丽景画桥西。","春色早，南国且黄鹂。","潇洒蕙楼菌阁，繁华杏坞桃溪。","多情杨柳露新荑。","堪一醉，骑马欲鸡栖。"]},{"t":"江月晃重山 四阕 其四 壬寅立春","f":"古风","c":["龙马山前草长，螳螂川上花开。","霜天晓角报春回。","传菜手，先进荡寒杯。","金线丝丝染柳，玉英片片熏梅。","流光容易把人催。","吾老矣，何日赋归来。"]},{"t":"菩萨蛮 楚雄春归","f":"古风","c":["来来去去无千里。","屏风万叠青山里。","流水赛流霞。","桃花夹杏花。","芜平芳草短。","一望春如剪。","回磴是回程。","莺声报一声。"]},{"t":"个侬 艳情","f":"古风","c":["恨个侬无赖，娇卖眼、春心偷掷。","苍苔落花，一双先印下。","月样春迹。","闻气不知名，似仙树御香，水边韩国。","罗襦襟解闻香泽，雌蝶雄蜂，东城南陌。","何人轻怜痛惜。","窥宋玉邻墙，巫山宁隔。","寻寻觅觅。","又暮云凝碧。","良夜千金，繁华一息。","楚宫盼睐留客。","爱长袖风流，钟情何极。","唱道是、凤帏深处附素足。","颤袅周旋恶。","怜伊尽倾侧。","叫檀郎枉春夕。","恐佳期别后青天样，何由再得。"]},{"t":"瑞鹧鸪 咏柳","f":"七言律诗","c":["垂杨垂柳管芳年。","飞絮飞花媚远天。","金茧抱春寒食后，玉蛾翻雪暖风前。","别离江上还河上，抛掷桥边与路边。","游子魂销青塞月，美人肠断翠楼烟。"]},{"t":"柳梢青","f":"古风","c":["酥雨才收。","猩红谢馆，蛾经秦楼。","忙杀东君，牡丹缠脚，芍药梳头。","藏鸦杨柳风流。","正好系、班骓紫骝。","窈窕洲边，温柔乡里，莫负歌喉。"]},{"t":"巫山一段云","f":"古风","c":["星的妆金靥，云梳挽宝鬘。","长蛾新月斗弯环。","风度佩珊珊。","小玉香煤烬，飞琼扇影闲，鳞霞练霭锦班班。","画出晚来山。"]},{"t":"鹧鸪天 其一 棋姬","f":"古风","c":["红袖乌丝罢写诗。","翠娥银烛笑谭棋。","雁行布阵穿花垒，虎穴临冲拔绣旗。","烽火劫，羽书持。","东山樽俎卷淮淝，紫囊儿辈元能办，况有婵娟出六奇。"]},{"t":"鹧鸪天 其二","f":"古风","c":["篱下黄花早已彫。","镜中华发不相饶。","清霜白露烟光晚，去雁来鸿客路遥。","香篆冷，烛花消。","佳宾同醉可怜宵。","都将璧月琼枝句，付与樽前薛小桃。"]},{"t":"鹧鸪天 其三 重游东岩寺，壁间见韩飞霞题字","f":"古风","c":["仙梵潮音水月堂。","昙花犹映墨花香。","旧围红袖题诗处，曾指银瓶索酒尝。","追幻梦，忆疏狂。","春风宿草满平冈。","浮山夜壑藏舟夜，槛外长江自渺茫。"]},{"t":"太平时 溯流纳溪舟，宿玉林寺。忆昔刘参之与弟承之、梁腾实相送至此，参之、腾实墓已宿草，感怆赋","f":"古风","c":["回首徂征出塞前。","甲申年。","故人相送蜀江边。","共留连。","廿载旧游非旧雨。","销魂处。","晨星朝露各风烟。","泪潸然。"]},{"t":"灼灼花","f":"古风","c":["谁把纤纤月。","掩在湘裙褶。","凤翠花明，猩红珠莹，蝉纱雪叠。","颤巍巍一对、玉弓儿，把芳心生拽。","掌上呈娇怯。","痛惜还轻捻。","戏蕊含莲，齿痕斜印，凌波罗袜。","踏青回露湿、怕春寒，倩檀郎温热。"]},{"t":"清平乐 其一","f":"古风","c":["君王未起。","玉漏穿花底。","永巷脱簪妆黛洗。","衣湿露华如水。","六宫鸾凤鸳鸯。","九重罗绮笙簧。","但愿君恩似日，从教妾鬓如霜。"]},{"t":"清平乐 其二","f":"古风","c":["倾城艳质。","本自神仙匹。","二八承恩初选入。","身是三千第一。","月明花落黄昏。","人间天上销魂。","且共题诗团扇，笑他买赋长门。"]},{"t":"于中好 元宵后独酌","f":"古风","c":["千点寒梅哓角中。","一番春信画楼东。","收灯庭院迟迟月，落索秋千剪剪风。","鱼雁杳，水云重。","异乡节序恨匆匆。","当歌幸有金陵子，翠斝清尊莫放空。"]},{"t":"塞垣瑞鹧鸪 檃括唐诗以补唐曲","f":"七言律诗","c":["秦时明月玉弓悬。","汉塞黄河锦带连。","都护羽书飞瀚海，单于猎火照甘泉。","莺闺燕阁年三五，马邑龙堆路十千。","谁起东山安石卧，为君谭笑静烽烟。"]},{"t":"浣溪沙","f":"七言古诗","c":["风里桃花一阵红。","一年春色又成空。","可怜光景闭门中。","绝塞不知登览兴，故乡惟与梦魂通。","倚楼病眼送归鸿。"]},{"t":"渔家傲 其一 夏日晓起","f":"古风","c":["鸡唱未圆天已旭。","伯劳杜宇声相续。","残月笼花风袅竹。","眠未足。","千金难买临明宿。","叶上露华纷缀玉。","青松雨后如膏沐。","思爽神清来往独。","幽径躅。","休教踏破苔钱绿。"]},{"t":"渔家傲 其二 寄李中溪仁夫","f":"古风","c":["春色已随银树去。","点苍千里行云暮。","四颗明珠行复聚。","歌舞处。","鹤桥便是秋娘渡。","青镜红颜容易去。","老年芳景须珍护。","服食求仙多错误。","君记取。","九州大错休教铸。"]},{"t":"折桂令","f":"古风","c":["枕高冈、坐占鸥沙。","看晓渡帆樯，晚市鱼虾。","红叶园林，黄花篱落，白水蒹葭。","望东寺、双浮佛塔。","指高峣、一片人家。","隐趁归槎。","低岸乌纱。","满酌春醪，闲话桑麻。"]},{"t":"翠楼吟 代送大理蔡太守","f":"古风","c":["月晃苍山，风清黑水，花满原鳞城雉。","燧松明夜火，歌来暮似城都市。","五华楼合，看五马迎恩，双鸿送喜。","迟迟晷行春金碧，照春金紫。","此邦宜有循良，拥玉麟铜虎，旖旎叶榆难借寇，望登仙香尘遥起。","攀轩处、正红颊窥帘，华颠卧轨。","画图外、甘棠阴里，心驰千里。"]},{"t":"临江仙 寄简西峃","f":"古风","c":["西峃襟怀元洒落，近来踪迹何疏。","高峣一水不斯须。","应同渔父饮，醒眼看三闾。","侍立小僮清似玉，少陵诗兴何如。","遥岑远目几踟蹰。","碧云停杳霭，明月几盈虚。"]},{"t":"浣溪沙 其一 丙午十二月，碧鸡关路旁梅","f":"七言古诗","c":["为访寒梅过野塘。","一枝斜出宋家墙。","团情团思媚韶光。","游女弄珠临汉水，画师绰绛学吴妆。","新词休咏旧昏黄。"]},{"t":"浣溪沙 其二 简西峃楼饮","f":"七言古诗","c":["琼稷金盘六齿红。","玉人美酒赛新丰。","凭陵大叫小楼中。","临岸梅花惊照水，隔江桃叶唱回风。","明朝重醉宋家东。"]},{"t":"西江月 唐宫守岁图","f":"古风","c":["五柞宫中腊尽，万年枝上霜清。","沈香火底坐吹笙。","玄圃楼台不瞑。","蕊女金钗剪烛，花奴玉导挑灯。","红儿酒渴嚼春冰。","忽报景阳钟应。"]},{"t":"临江仙 丁未新正寄简西峃","f":"古风","c":["元日晴明人日接，韶光淑气相仍。","梅钿柳带似相矜。","花游谁与共，绮语老犹能。","一水盈盈遥望处，团团宝月初升。","山阴剡曲兴须乘。","十千沽绿酒，三五醉红灯。"]},{"t":"柳梢青 杏花","f":"古风","c":["晕雪融霞。","若烟非雾，何处人家。","宋玉墙东，文君垆下，占断韶华。","梅梢已罢横斜。","柳条犹未藏鸦。","锦树烘春，琼枝枭月，留醉仙娃。"]},{"t":"忆王孙 其一 重宿禄品","f":"古风","c":["落梅风里王鳞皴。","牛背寒鸦过别村。","樵笛声中暮霭昏。","掩重门。","翠被香寒酒正温。"]},{"t":"忆王孙 其二 大理九日","f":"古风","c":["满城开遍粉西施。","节近重阳客未知。","袅袅凉风搅鬓丝。","倚楼时。","长笛声声莫遣吹。"]},{"t":"浣溪沙 高峣雨中喜简西峃至","f":"七言古诗","c":["短短轩窗小小斋。","行吟坐啸独悠哉。","爱闲能有几人来。","佳客新从云里至，好花多向雨中开。","隔篱呼取尽余杯。"]},{"t":"西江月 观蜀史梼杌王宗衍事","f":"古风","c":["舞影金波月浸，歌声玉叶云留。","益州风物似扬州。","卓女烧春绿酹。","琼树何如锦树，缯楼却赛迷楼。","露桃花下不知秋。","正是酒悲时候。"]},{"t":"赛天香 妓宴","f":"古风","c":["芙蓉屏外，倒金尊、满座艳歌凝咽。","半面新妆香透幌，环佩珊珊步怯。","接黛垂鬟，低声小语，问采香仙妾。","柳袅花停，莺莺燕燕标格。","媚眼射注檀郎，双鸳全露，裙底凌波袜。","万斛胭脂倾在水，染就银河一色。","天作红墙，山为翠幕，生把伊侬隔。","离魂牵梦回，南浦凉月。"]},{"t":"沁园春 送卞苏溪归叙州","f":"楚辞体","c":["归去来兮，羡公高致，栗里堪齐。","记绣斧行边，风生贵竹，青油开府，月朗雕题。","黑发功名，丹心事业，卿棘公槐行可跻。","问何事，急流勇退，力挽难稽。","公言某岂栖栖。","奔走红尘早岁迷。","况夜鹤帐中，滇云直北，春鹃花底，蜀日平西。","布袜青鞋，水边林下，寻壑经丘一杖藜。","喜吾乡，散仙多侣，胜日招携。"]},{"t":"锦鹧鸪 三更一笛一联，胡仲父落梅之句也。词人所称，予惜不见其全篇，遂为足之","f":"古风","c":["梦断罗浮绰约丛。","玉龙鳞甲缀帘栊。","自孤花底三更月，却怨楼头一笛风。","寒料峭，晓葱珑。","劝君莫放酒杯空。","雪儿清唱山香舞，要把霜毛晕醉红。"]},{"t":"鹧鸪天 其一 魏南山将军别墅蜡梅","f":"古风","c":["融蜡融栀褪粉光。","晕眉晕脸学蛾妆。","惊回花底三更梦，别是风前一种香。","桃杏妒，艾兰防。","几番孤负月昏黄。","枝头要见青青子，且放银灯伴海棠。"]},{"t":"鹧鸪天 其二 与叶桐冈东城醉归口占","f":"古风","c":["窄窄红渠艳袜罗，盈盈一笑满黎涡。","小槽春滴金华酒，纤月风林玉树歌。","香掩冉，影婆娑。","载花归路似东坡。","相逢不尽疏狂兴，其奈星星白发何。"]},{"t":"浣溪沙 其一 高峣晚晴招简西峃","f":"七言古诗","c":["云露山尖水见沙。","生烟漠漠树横斜。","晚来晴景属诗家。","天碧远粘千里草，霞红低缀一丛花。","谪仙桥上望仙槎。"]},{"t":"浣溪沙 其二 杨双泉寄画扇","f":"七言古诗","c":["玉斧修成宝月团。","月中仍有女乘鸾。","钗横鬓乱不胜寒。","白兔楼头风露迥，碧鸡祠下水云宽。","相思两地共凭阑。"]},{"t":"鹧鸪天 其一 巧夕咏剪红罗","f":"古风","c":["玉露金风撼翠柯。","园芳开到剪红罗。","灿如天女琼花树，丽夺仙郎瑞锦窠。","秋已透，夜如何。","穿针楼上巧云多。","七襄共爱天机好，其奈流年一掷梭。"]},{"t":"鹧鸪天 其二 丁香花","f":"古风","c":["一片红云簇帐天。","翠绡双卷出婵娟。","露凝狐塞燕支紫，日炙鸿门楚锦嫣。","香馥郁，影联翩。","金风璧月斗明蠲。","散花天女同心结，莫恼维摩丈室禅。"]},{"t":"浣溪沙 高峣带雨","f":"七言古诗","c":["满目风光户不关。","李成骤雨郭熙山。","吾卢宛在画图间。","修竹墙头过绿醑，丁香棚底醉红颜。","晚来一笑破天悭。"]},{"t":"忆王孙 九月八日邀客赏菊","f":"古风","c":["西风庭院咽玄蝉。","薄雾浓雰采菊天。","老去悲秋强自宽。","假婵娟。","且向樽前醉管弦。"]},{"t":"浣溪沙 落梅","f":"七言古诗","c":["径转梅桥燕尾分。","疏枝冷蕊照江濆。","玉龙鳞甲点波纹。","谢女黄昏吟作雪，襄王清夜梦为云。","余香留与醉红裙。"]},{"t":"于中好 己酉新春试笔","f":"古风","c":["早岁登龙气吐虹。","花砖红采映青葱。","西昆纶綍都经手，东壁图书尽在胸。","惊退鹢，悔雕虫。","烟波万里一丝风。","桃夭杏艳村醪嫩，方丈蓬莱是此中。"]},{"t":"落灯风 正月十七日留简西峃","f":"古风","c":["柳外落灯风乍起。","杏靥梅钿纷堕蕊。","彩架阁秋千，红绳紧、香尘满地。","春一分休矣。","银塘初煖湔裙水。","催莫愁、兰舟遥舣。","沽酒趁梨花，听双歌、温柔乡里。","且住为佳耳。"]},{"t":"忆王孙 落花集句","f":"古风","c":["绣葩红蒂堕残芳。","蝶醉蜂痴一簇香。","卢家少妇郁金堂。","对斜阳。","云雨巫山枉断肠。"]},{"t":"满江红 檃括潜夫词，忆李中溪种玉园梅","f":"古风","c":["角寂钟沈，清梦到、罗浮翠麓。","种玉园中同醉处，暗香犹扑。","月落参横增怅望，天寒日暮悲幽独。","讶陇头、不寄一枝来，萦心曲。","茅屋稳，辞金屋。","藜烛焰，羞银烛。","叹出尘风韵，背时妆束。","争羡东邻姬傅粉，岂知空谷人如玉。","问扬州、何逊有新诗，谁堪续。"]},{"t":"喜迁莺 寄胡在轩且约高峣之会","f":"古风","c":["东风如剪。","早见芍药努牙，牡丹生卵。","雕楹深笼，芳屏曲护，珍重春工犹浅。","回首上林，何处金蕊，玉房心懒。","吟笔健，认香山白傅，徘徊华馆。","看花君具眼。","击钵诗成，刻烛无妨短。","目送孤鸿，手提双鲤，一水盈盈未远。","何日棠舟，兰棹飞下，云涛千转。","日暮也。","望昆明天外，碧云初卷。"]},{"t":"莺啼序 高峣海庄十二景圃","f":"古风","c":["碧鸡唱晓霞散绮，重关征画。","环村步、几族生烟，空翠幻作仙界。","茭草荡湾环洲渚，轻风送幅蒲帆快。","看舞鸥、飞鹭联翩，向狖寥外。","晴兆须臾，雨信顷刻，问水椿山带。","树羽飐风展青帘，駮云销睨日晒。","浪花平、洛神衬袜，红妆涌出青罗盖。","浮修眉，约略黛螺，映盘鸦髻。","海花汀藻，文石锦沙，纶组迎船絓。","渔火焰、涟漪倒影，归棹穿方罫。","蒲牢昏吼，栖鸦结阵，八村九寺鸣萧籁。","提筠蓝、金线穿鱼卖。","松灯点点互月彩。","卧玉塔浮澜，素娥窈窕千态。","翠岩深霭，禅室僧归，杖锡微径隘。","月黑白林明处，香软寒轻薏苡，缸中梨梦萦呗。","南蛮老松，遥看晴雪，似银龙下斟玉瀣，洗尘襟、着得乾坤大。","辋川何似吾庐，海变春醪，偿风月债。"]},{"t":"木兰花慢 春日闲居，寄简西峃","f":"古风","c":["重三今日是，寒食过，又清明。","念故国关心，归期难卜，望远愁生。","天留烟霞胜处，汇平湖、列岫碧纵横。","花里笔床茶灶，松间渔影樵声。","可人咫尺喜逢迎，来往片云轻。","看柳埧长绡，交塘归棹，双塔高城。","长安水边不记，想绿朱碧玉、事堪惊。","笑弄豚儿犬子，饱餐燕麦鱼羹。"]},{"t":"满江红 咏菊，效稼轩词论体","f":"古风","c":["唤醒灵均，为问餐、秋菊落英消息。","秋英元不落，妙筌谁识。","要悟灵均言外意，此花珍重殊难得。","待英蕤、零落始供餐，休轻摘。","九月律，当无射。","黄落尽，无颜色。","惟兹独秀，冷露寒霜侧。","不肯悠悠随宿莽，只将凛凛争松柏。","把九章橘颂，试同观，方奇特。"]},{"t":"醉蓬莱 代寿黔国上公","f":"古风","c":["看金波遥映，玉镜高飞，昆明池沼。","近天上中秋，人间蓬岛。","建节堂深，筹边楼迥，正雨晴风袅。","青鸟喉歌，红鸾掌舞，仙音缭绕。","白鹤南来，锦书为报。","云动三山，星飞五老。","汉节唐符拜，重华天表。","玉尘谈诗，金钗压鬓，向琼枝齐祷。","愿岁岁长春，年年此日，恩波难老。"]},{"t":"西江月 画观音寿意","f":"古风","c":["金粟如来神影，青莲居士新词。","普陀岩瞑八功池。","宛与昆明相似。","瑞霭锦云团盖，祥光宝月圆规。","醍醐乳酒注军持。","听取长生莂记。"]},{"t":"一七令 舟中阅唐诗纪事王起李绅张籍令孤楚于白乐天席上各赋一字至七字诗以题为韵遂效其体为花风月雪四首宋人名 其一","f":"古风","c":["花。","摛锦，铺霞。","邀蝶队，聚蜂衙。","珠璎姹女，宝髻宫娃。","风前香掩冉，月底影交加。","绿水名园几蔟，青楼大道千家。","谢傅金屏成坐笑，陈朝琼树不须誇。"]},{"t":"一七令 舟中阅唐诗纪事王起李绅张籍令孤楚于白乐天席上各赋一字至七字诗以题为韵遂效其体为花风月雪四首宋人名 其二","f":"古风","c":["风。","偃草，飘蓬。","过竹院，拂兰丛。","柳提摇绿，花径飞红。","青缸残燄灭，碧幌嫩凉通。","漆园篇中竽籁，兰台赋里雌雄。","无影迥随仙客御，有情还与故人同。"]},{"t":"一七令 舟中阅唐诗纪事王起李绅张籍令孤楚于白乐天席上各赋一字至七字诗以题为韵遂效其体为花风月雪四首宋人名 其三","f":"古风","c":["月。","霜凝，冰洁。","三五圆，二八缺。","玉作乾坤，银为宫阙。","如镜复如钩，似环仍似玦。","兰闺少妇添愁，榆塞征人怨别。","汉家今夕影娥池，穆穆金波歌未阕。"]},{"t":"一七令 舟中阅唐诗纪事王起李绅张籍令孤楚于白乐天席上各赋一字至七字诗以题为韵遂效其体为花风月雪四首宋人名 其四","f":"古风","c":["雪。","凝明，澄彻。","飞玉尘，布琼屑。","苍云暮同，岩风晓别。","深山樵径封，远水渔舟绝。","南枝忽报梅开，北户俄惊竹折。","万树有花春不红，九天无月夜长白。"]},{"t":"鹧鸪天 其一 雨中凉甚独酌","f":"古风","c":["为喜新凉入酒杯。","自斟自劝自徘徊。","暑才溽处云先合，诗欲成时雨早催。","吟草阁，赴兰台。","江山金碧画图开。","天教一片滇南景，逐我多情万里来。"]},{"t":"鹧鸪天 其二 以茉莉沙坪茶送少岷","f":"古风","c":["灌口沙坪摘小春。","素馨茉莉荐香尘。","要知贮月金波味，只有餐霞玉洞人。","云叶嫩，乳花新。","冰瓯雪瓯却杯巡。","清风两腋诗千首，舌有悬河笔有神。"]},{"t":"河传 咏隋堤","f":"古风","c":["东楚。","南浦。","隋堤游处。","龙脑飞霙，明珠溅雨。","彩女殿脚三千。","青娥吴绛仙。","梅黄雨细枫香老。","江都好。","忘却长安道。","不堪回首，芳魂已断迷楼。","怨扬州。"]},{"t":"酒泉子 避暑江山平远亭，招简西峃不至","f":"古风","c":["西峃不来。","负却红墙垂手。","懒当歌，慵对酒。","倦登台。","石城艇子又空回。","溪?一双惊散。","藕花汀，桃叶岸。","独徘徊。"]},{"t":"西江月 泸州发船，王云巢携翠容相送","f":"古风","c":["莫道留春无计，君来有计留春。","翠容烟黛隔花颦。","隐隐遥山远映。","载酒春江画舫，题诗红泪罗襟。","江头离别一何频。","醉倒柳昏花瞑。"]},{"t":"花犯念奴","f":"古风","c":["云軿不辗地，仙居多丽谯。","湖海念年龙卧，锦涟清霅苕。","甫里笔床茶灶，山阴楸枰方罫，香籀记昏朝。","醉乡无畔岸，北斗挹天瓢。","楼中人，谁是伴，有松乔。","灵文绿帙，齐物与逍遥。","肯念草玄寂寞，暂遣喜公缩地，风御蓦琅霄。","阑干凭到景，共和晓仙谣。"]},{"t":"鹧鸪天 其一 戊申初度","f":"古风","c":["宦海风波记昔年。","天涯青镜感华颠。","过堂未悟钟将衅，睨柱谁知壁偶全。","周卦气，卜先天。","日斜鼓缶月明前。","笑看太白成三影，便是维摩不二禅。"]},{"t":"鹧鸪天 其二 寿张月坞","f":"古风","c":["绿粉名园暑燕开。","池红水碧两徘徊。","竹西仙叟藏春坞，莲北诗人半月台。","三凤兆，八龙才。","不论燕桂与王槐。","丹霞夹月华星出，长照金樽映宝罍。"]},{"t":"满江红 十一月六日，鲁泉董太守过宿高峣","f":"古风","c":["王子回船，还只是、戴公无兴。","试思之、雪中林壑，琼辉玉映。","佳客冲寒来半夜，主人扫雪开三径。","便拥炉、命酒炙车螯，才相称。","前古事，休重咏。","翻旧案，行新令。","唤官奴秉烛，肉屏围定。","画角吹梅天未晓，金钗剪烛人初静。","更新词、一曲满江红，君须听。"]},{"t":"鹧鸪天 落叶","f":"古风","c":["袅袅西风锦树新。","一年芳景属流尘。","莫辞雨滴寒鸣夜，曾抱花枝煖过春。","蒲柳岸，柙枫津。","琅玕摧折感离人。","天津休问题红怨，香阁回文翠黛颦。"]},{"t":"昼夜乐 中秋董太守席上","f":"古风","c":["螳螂川上清秋节。","爽襟怀、消烦热。","香醪桂馥兰熏，官妓舞琼歌雪。","五马风流华筵设，金屏燕颃莺颉。","软语劝飞觞，有如花连舌。","座中豪兴称三绝。","高阳并，斜川埒。","且偕仙侣逍遥，肯叹群儿圆缺。","未害广平心似铁。","看霜鬓、半成耄耋。","倩横玉叫云、把寥天吹彻。"]},{"t":"汉宫春 菊席","f":"古风","c":["采采黄花，向龙山高处，浅泛金卮。","秋容老圃堪赏，插鬓参差。","杨妃沈醉，苎罗更比西施。","可笑群儿，凡目品题，污却高姿。","千古陶家清兴，有何人提著，冷落东篱。","炎皇曾书，本草寿域仙蕤。","明堂月令，挺孤芳、四字标奇。","歌一阕，悠然自适，无弦琴是心知。"]},{"t":"鹧鸪天 其一 莲池","f":"古风","c":["红玉花开绿锦池。","碧筒金醴泻芳卮。","十三餍足传情遍，二八蛾眉度曲迟。","云散后，月明时。","接䍦颠倒袂参差。","良辰佳会应难续，风雨连宵恼别离。"]},{"t":"鹧鸪天 其二 易门小饮","f":"古风","c":["翠斝青樽旅思消。","酒楼斜映绿杨桥。","瓮头霞色如妆面，帘脚风流似舞腰。","同醉处，可怜宵。","障泥未解玉骢骄。","青衫不湿江州泪，已许狂歌托圣朝。"]},{"t":"鹧鸪天 其三 月下水边梅影","f":"古风","c":["断角残钟半掩门。","谁招雪魄与冰魂。","罗浮梦里更三点，花信风前第一番。","溪绿净，月黄昏。","留连檀板共金樽。","袜尘波底香难赛，轸粟灯前玉易皴。"]},{"t":"临江仙 题春夜宴桃李园图","f":"古风","c":["桃李名园开夜宴，樽前烛影摇红。","璚枝碧月锦帘栊。","香寒心字篆，花煖肉屏风。","百岁光阴真过客，千金一刻难逢。","高谈幽赏兴何穷。","玉箫歌一曲，金谷酒千钟。"]},{"t":"鹧鸪天 其一 壬子元夕前，高峣海庄，与王云岩、丘鸿夫、张子中、李继培小饮","f":"古风","c":["淼淼春波碧海边。","淹留佳客夜开筵。","未临元夕灯先试，虽是贫家月也圆。","歌宛转，舞蹁跹。","劝郎行乐驻华年。","白头未定西归计，愁听箜篌蜀国弦。"]},{"t":"鹧鸪天 其二 北岩寺酒阑书感","f":"古风","c":["戎旅今年四处家。","故乡咫尺是天涯。","寻巢未定身如燕，览镜曾经鬓似鸦。","愁对酒，懒看花。","青衫老泪感琵琶。","侧身天地无刘表，徙倚阑干日又斜。"]},{"t":"江城梅花引 夕宿江门","f":"古风","c":["漏声沈。","雨声沈。","滴滴空阶碎客心。","拥单衾。","拥单衾。","病骨寒侵。","争教不断魂。","静闻枥上嘶羸马。","巴童熟睡荒鸡哑。","旅游难。","白首衰残。","何日歇征鞍。"]},{"t":"一剪梅 戏简西峃宿杏花楼","f":"古风","c":["宋玉墙头杏子花。","香也堪夸。","艳也堪夸。","东风鸟外一枝斜。","问是谁家。","江上人家。","肯信流年鬓有华。","诗咏红霞。","酒泛流霞。","低声昵语似雏鸦。","人在天涯。","忘却天涯。"]},{"t":"浣溪沙 永宁病起将归","f":"七言古诗","c":["听彻晨鸡又暮鸦。","病来帘外即天涯。","明朝才得问归槎。","客路纵遥终会到，他乡须好不如家。","江门春水照江花。"]},{"t":"浪淘沙 富顺县罗汉洞诸公相送","f":"古风","c":["良会阻天涯。","水渺云赊。","归途喜见腊梅花。","又醉当时罗汉洞，一曲琵琶。","浮客似浮槎。","到处为家。","鲁峰高兴更南沙。","有约肯来无宿诺，细酌流霞。"]},{"t":"天净沙 题画 其一 惜花春早起","f":"古风","c":["霜天晓角声残。","霞绡雪缕衣单。","依约宫黄画浅。","小梅开遍。","咏花人倚阑干。"]},{"t":"天净沙 其二 爱月夜眠迟","f":"古风","c":["良宵一刻千金。","水晶宫里沉沉。","月姊休教妒影。","离情别恨。","人间天上同心。"]},{"t":"天净沙 其三 掬水月在手","f":"古风","c":["桂花影里金波。","瑶池倒映银河。","玉臂清辉无那。","纤纤摊破。","分明掌上嫦娥。"]},{"t":"天净沙 其四 弄花香满衣","f":"古风","c":["晓风香露楼台。","长红小白齐开。","笑整鲛绡双带。","拈来慵戴。","满怀蜂蝶争来。"]},{"t":"西江月 欧海蟾楼上","f":"古风","c":["夜合庭前月照，夕佳楼上春宵。","青灯的的夜迢迢。","欹枕荒鸡未晓。","杜曲愁浓酒恼，沈园梦断香消。","倚门红袖不须招。","不见卢郎年少。"]},{"t":"鹧鸪天 刘岷川母寿词","f":"古风","c":["王母西来青鸟迎。","瑶池翠水浅还清。","何如萱草庭前茂，又见猗兰砌下生。","罗甸国，锦官城。","望云就日两关情。","锦江化作长春酒，笑对东风北斗倾。"]},{"t":"瑞鹧鸪 集句 咏巫山高","f":"七言律诗","c":["望中孤鸟入销沈。","宿处津亭枫树林。","江草江花岂终极，巫山巫峡气萧森。","为云为雨襄王梦，愁水愁风商妇心。","客去客来天地老，无朝无暮有猿吟。"]},{"t":"浣溪沙 雪中，萧东淳自安宁至，二姬自滇来，小饮成醉","f":"七言古诗","c":["雪里佳人特地来。","红裙翠袖小弓鞋。","杨花飞处牡丹开。","佛氏解为银世界，仙家幻作玉楼台。","王猷访戴棹休回。"]},{"t":"鹧鸪天 高峣岸梅，句用鸟兽字","f":"古风","c":["鱼尾红霞海影摇。","碧鸡腊信上梅梢。","涂黄巧学蜂腰细，匀粉俄惊蝶翅飘。","龙竹瘦，鹤松翘。","相和兰麝绮香销。","龟城春色添乡梦，想见枝头绿凤么。"]},{"t":"临江仙 四会柬亩","f":"古风","c":["高宴诸侯张乐地，锦堂华烛蟠烟。","当筵歌舞假婵娟。","病吟终少味，老醉不成颠。","高隐无言应念我，白头奔走山川。","熏梅染柳又催年。","人归落雁后，思发在花前。"]},{"t":"定风波 沾益冬至","f":"古风","c":["客中冬至夜偏长。","寒炉坐拥待晨光。","心似死灰飞不起。","愁里。","路迷心折望吾乡。","玉几由来天北极。","曾直。","五更三点入鹓行。","何事白头犹道路。","谁诉。","天高难问只苍苍。"]},{"t":"鹧鸪天 斗山陂遇雪","f":"古风","c":["去岁渝州赏雪时。","桂舟兰楫泛清漪。","握松旧令传琼腕，冠柳新词侑锦卮。","香遍满，夜何其。","三更醉舞赛西施。","岂知饥走荒山道，百结鹑衣履冻澌。"]},{"t":"南乡子","f":"古风","c":["晴虺索春饶。","垂柳长亭学舞腰。","昨夜惊鸿还入梦，妖娆。","已隔扬州念四桥。","濯锦露花朝。","曾泛兰舟拾翠翘。","云散风流何处觅，难描。","浅黛遥山雪半消。"]},{"t":"阙调名 中秋夜小酌即席示二弟小词二首 其一","f":"古风","c":["江树无烟。","清辉寒影在中天。","谢池家宴，休教辜负今夜十分圆。","一樽相对静娟娟。","分得金波漾酒船。","更阑酒尽不成眠。","一枝仙桂，好事说明年。"]},{"t":"阙调名 中秋夜小酌即席示二弟小词二首 其二","f":"古风","c":["月照三更。","鹊绕南枝雁亦惊。","庾楼高兴，休教辜负今夜十分明。","凄清何处管弦声。","彷佛燕台紫陌行。","便从今夕话离情。","明年此景，又隔凤凰城。"]},{"t":"浣溪沙","f":"七言古诗","c":["远道明朝万壑冰。","华堂今夕九枝灯。","娇歌姹管醉难胜。","幻玉风流南北院，飞琼仙梦短长亭。","青楼回首十三层。"]},{"t":"黑漆弩 其一 谢曾少岷题扇","f":"古风","c":["梁尘飞绕停教住。","有哲匠坐上原父。","早梅时、新月弯弓，喜见遥天收雨。","尉迟杯、满酌休辞，半臂急催忙去。","写蒲葵，一字千金，付阿买、珍藏好处。"]},{"t":"黑漆弩 其二 谢熊南沙跋帖","f":"古风","c":["月仪蠹简留君住。","索靖是右军师父。","笑藏真、酗酒狂僧，说甚龙蛇风雨。","戏鱼堂、响榻重镌，莫道影留形去。","熊朋来，鼎韵钟铭，鉴赏到、西台妙处。"]},{"t":"唐多令 中秋与夺客泛舟","f":"古风","c":["飞镜露云头。","金波水面浮。","水晶宫、今夜中秋。","唤取官奴吹玉笛，香雾湿，锦云留。","二客亦风流。","螂川泛小舟。","问何如、赤壁黄州。","坡老有灵应鼓掌，天地寄浮蝣。"]},{"t":"蝶恋花 二阕 其一","f":"古风","c":["璧月琼枝风韵在。","皎皎盈盈，自拗梅花带。","一笑倾城迷下蔡。","暗香疏影春难赛。","年纪无多情性快。","翠袖金杯，满劝深深拜。","禅室散花元不碍。","道人还了鸳鸯债。"]},{"t":"蝶恋花 二阕 其二","f":"古风","c":["月白珠玄成一派。","灼灼红灯，光映猩猩菜。","天女从来银色界。","肌肤冰雪牵人爱。","护粉羞黄如有待。","镜约钗盟，只恐旁人怪。","弦上分明传意态。","何时许解香罗带。"]},{"t":"金字经 二首 其一 江上晚归","f":"古风","c":["璧月寒生晕，银河冻欲冰。","稳坐蓝舆酒半醒。","登。","渔舟红蓼汀。","樵楼暝。","冬冬初起更。"]},{"t":"金字经 二首 其二 江上晚归","f":"古风","c":["窗纸风偏透，衾裯冷不胜。","欹枕挑灯诗又成。","听。","更鼓最无凭。","同云暝。","檐花滴到明。"]},{"t":"减字木兰花","f":"古风","c":["乌衣椎髻。","龙女改妆歌薜荔。","立近梅花。","弄粉团香衬脸霞。","真真唤醒。","便出墨池登雪岭。","醉写乌丝。","齐唱东风第一枝。"]},{"t":"锦缠带","f":"古风","c":["谁家红袖倚江楼。","手卷珠帘上玉钩。","眼波娇溜满眶秋。","笑抬头。","头上花枝颤未休。"]},{"t":"折桂令 昭君出塞图","f":"古风","c":["乱纷纷，玉蕊冰花。","气结愁云，泪湿腮霞。","高阙千寻，停骖一顾，漠漠黄沙。","只见三队五队，槊旌旗，舞风番马。","千点万点，绕穹庐，成阵寒鸦。","一曲琵琶。","几拍胡笳。","目断飞鸿，恨满天涯。"]},{"t":"鹧鸪天","f":"古风","c":["恰喜高秋爽气新。","却愁秋月解伤神。","酒阑二十年前事，梦醒三千里外身。","枫叶岸，菊花津。","且须勤买阿宁春。","帐头傀儡元来假，枕上邯郸岂是真。"]},{"t":"临江仙","f":"古风","c":["水上生尘罗袜，风前束素纤腰。","陈王瞥见已魂消。","妒云开翠幄，笑电闪红绡。","此去但留今夕，重来定约何朝。","西陵南浦路迢迢。","徘徊花上月，空度可怜宵。"]},{"t":"西江月","f":"古风","c":["漫道革囊盛血，休言炭帚污人。","禅机仙术两成尘。","输与花门柳阵。","被欲生棱夜永，带翻成结灯昏。","东园桃李片时春。","不是少年风韵。"]},{"t":"巫山一段云 绍途遇雪","f":"古风","c":["梅柳春相近，关山雪正飞。","寒光朔气冷侵衣。","玉塞隔金微。","久戍人将老，长征马不肥。","帛书欲寄雁声稀。","秃节几时归。"]},{"t":"临江仙 送刘珥江洎杨许二子","f":"古风","c":["官柳野梅西郭路，昆桥直接丰桥。","相思百里不辞遥。","春山同载酒，月地共联鏕。","南去北来人自老，怜予心旆摇摇。","短亭暂别亦魂销。","生烟寒漠漠，飞霭晚潇潇。"]},{"t":"千秋岁 壬寅新正二日寿内","f":"古风","c":["瑶池阿母。","本是神仙侣。","谪向人间官府。","住摄提，贞孟月，中子逢初度。","琅霄宴，春回北斗斟云醑。","麟笔春秋谱。","彤管毛诗语。","女洙泗，闺邹鲁。","五福中天聚。","百秩从今数。","最难得，芝兰庭下斑彩舞。"]},{"t":"好事近 煮茶进，和蔡松年韵","f":"古风","c":["彩线利如刀，解破团圆明月。","兰薪桂火筠炉，听松风翻雪。","唤取眠云跂石人，赛十洲三绝。","焚香朗诵黄庭，把肺肝清彻。"]},{"t":"霓裳中序第一 雨中刘珥江送鸡头","f":"古风","c":["青霞裁雾縠。","正锦潋瑶潘碧澳。","水底鲛人织女。","当翠房深处，新妆乍沐。","尘消罗袜，冶步盈盈出鳞屋。","向何许，满身璎珞，云辙转风毂。","皎镜全澄独漉。","相掩映、荷裳芰服。","昨夜龙宫失晓也，养天鸡、启明传旭。","啄粮无半菽。","算只有明珠满腹。","江妃把、金针穿玩，递与素娥掬。"]},{"t":"鹊桥仙 七夕","f":"古风","c":["冰盘荐巧，珠帘堆莹，半卷生绡光致。","嫦娥妒眼便西沈，又早倩、羲和催辔。","多情瑞鹊，填桥度我，何不晓来回避。","但教三万六千年，也不若、人间百岁。"]},{"t":"滇海竹枝词 其一","f":"七言绝句","c":["罗汉孤峰祇树林，梁王辇道海中心。","海垠青青堪牧马，海眼只今无处寻。"]},{"t":"滇海竹枝词 其二","f":"七言绝句","c":["东浦彩虹悬水椿，西山白雨点寒江。","烟中艇子摇两桨，空里鹭鸶飞一双。"]},{"t":"蜀中竹枝词 其一","f":"七言绝句","c":["夔州府城白帝西，家家楼阁层层梯。","冬雪下来不到地，春水生时与树齐。"]},{"t":"蜀中竹枝词 其二","f":"七言绝句","c":["日照峰头紫雾开，雪消江面绿波来。","鱼腹浦边晒网去，麝香山上打柴回。"]},{"t":"蜀中竹枝词 其三","f":"七言绝句","c":["江头秋色换春风，江上枫林青又红。","下水上风来往惯，一年长在马船中。"]},{"t":"蜀中竹枝词 其四","f":"七言绝句","c":["最高峰顶有人家，冬种蔓菁春采茶。","长笑江头来往客，冷风寒雨宿天涯。"]},{"t":"蜀中竹枝词 其五","f":"七言绝句","c":["青江白石女郎神，门外往来祈赛频。","风飐青旗香雨歇，山桂花开瑶草春。"]},{"t":"蜀中竹枝词 其六","f":"七言绝句","c":["红妆女伴碧江濆，蓪草花簪茜草裙。","西舍东邻同夜烛，吹笙打鼓赛朝云。"]},{"t":"蜀中竹枝词 其七","f":"古风","c":["神女峰前江水深，襄王此地几沉吟。","?花温玉朝朝态，翠壁丹枫夜夜心。"]},{"t":"蜀中竹枝词 其八","f":"七言绝句","c":["上峡舟航风浪多，送郎行去为郎歌。","白盐红锦多多载，危石高滩稳稳过。"]},{"t":"蜀中竹枝词 其九","f":"七言绝句","c":["无义滩头风浪收，黄云开处见黄牛。","白波一道青峰里，听尽猿声是峡州。"]},{"t":"杨柳枝词 其一","f":"七言绝句","c":["汉东门外柳新栽，拂晓长堤露眼开。","野老攀条相向语，去年曾被贼烧来。"]},{"t":"杨柳枝词 其二","f":"七言绝句","c":["临水临风漾碧漪，含烟含雾一枝枝。","战尘收后无离别，又见长条到地时。"]},{"t":"西江月 廿一史弹词第一段总说开场下场词二首 其一","f":"古风","c":["天上乌飞兔走，人间古往今来。","沉吟屈指数英才。","多少是非成败。","富贵歌楼舞榭，凄凉废冢荒台。","万般回首化尘埃。","只有青山不改。"]},{"t":"西江月 廿一史弹词第一段总说开场下场词二首 其二","f":"古风","c":["滚滚龙争虎斗，匆匆兔走乌飞。","席间花影坐闲移。","百岁光阴有几。","说古谈今话本，图王定霸兵机。","要知成败是和非。","都在渔樵话里。"]},{"t":"南乡子 廿一史弹词第二段说三代开场词","f":"古风","c":["携酒上吟亭。","满目江山列画屏。","赚得英雄头似雪，功名。","虎啸龙吟几战争。","一枕梦魂惊。","落叶西风别换声。","谁弱谁强多罢手，伤情。","打入渔樵话里听。"]},{"t":"西江月 廿一史弹词第二段说三代下场词","f":"古风","c":["阅尽残编断简，细详千古英雄。","功名富贵笑谈中。","回首一场春梦。","昨日香车宝马，今朝禾黍秋风。","谁强谁弱总成空。","傀儡棚中搬弄。"]},{"t":"临江仙 廿一史弹词第三段说秦汉开场词","f":"古风","c":["滚滚长江东逝水，浪花淘尽英雄。","是非成败转头空。","青山依旧在，几度夕阳红。","白发渔樵江渚上，惯看秋月春风。","一壶浊酒喜相逢。","古今多少事，都付笑谈中。"]},{"t":"西江月 其一 廿一史弹词第三段说秦汉下场词","f":"古风","c":["落日西飞滚滚，大江东去滔滔。","夜来今日又明朝。","蓦地青春过了。","千古风流人物，一时多少英豪。","龙争虎斗漫劬劳。","落得一场谈笑。"]},{"t":"西江月 廿一史弹词第四段说三分两晋开场下场词二首 其二","f":"古风","c":["道德三皇五帝，功名夏后商周。","英雄五霸斗春秋。","秦汉兴亡过手。","青史几行名姓，北邙无数荒丘。","前人田地后人收。","说甚龙争虎斗。"]},{"t":"西江月 廿一史弹词第四段说三分两晋开场下场词二首 其三","f":"古风","c":["豪杰千年往事，渔樵一曲高歌。","乌飞兔走疾如梭。","眨眼风惊雨过。","妙算龙韬虎略，英雄铁马金戈。","争名夺利竟如何。","必有收因结果。"]},{"t":"清平乐 廿一史弹词第五段说南北朝开场词","f":"古风","c":["闲行闲坐。","不必争人我。","百岁光阴弹指过。","成得甚么功果。","昨日羯鼓催花。","今朝疏柳啼鸦。","王谢堂前燕子，不知飞入谁家。"]},{"t":"西江月 廿一史弹词第五段说南北朝下场词","f":"古风","c":["飒飒西风渭水，萧萧落叶长安。","英雄回首北邙山。","虎斗龙争过眼。","闲看灞桥杨柳，凄凉露冷风寒。","断蝉声里凭阑干。","不觉斜阳又晚。"]},{"t":"点绛唇 廿一史弹词第六段说十六国开场词","f":"古风","c":["暮鼓晨钟，春花秋月何时了。","七颠八倒。","往事知多少。","昨日今朝，镜里容颜老。","千年调。","一场谈笑。","几个人知道。"]},{"t":"西江月 廿一史弹词第六段说十六国下场词","f":"古风","c":["六代瓜分世界，五胡云扰中原。","纵横三百有余年。","几度交锋索战。","马过生灵齑粉，血流河洛腥膻。","耳闻犹自不堪言。","有眼休教看见。"]},{"t":"临江仙 廿一史弹词第七段说隋唐开场词","f":"古风","c":["一片残山并剩水，年年虎斗龙争。","秦宫汉苑晋家茔。","川原流恨血，毛发凛威灵。","白首诗人闲驻马，感时怀古伤情。","战场田地好宽平。","前人将不去，留与后人耕。"]},{"t":"西江月 廿一史弹词第七段说隋唐下场词","f":"古风","c":["追想千年往事，六朝踪迹茫然。","隋唐相继统中原。","世态几回云变。","杨柳凄迷汴水，丹青惨淡凌烟。","乐游原上草连天。","飞起寒鸦一片。"]},{"t":"定风波 廿一史弹词第八段说五代十国开场词","f":"古风","c":["雨淋漓滩赴选场。","秀才落得甚干忙。","白发渔樵诸事懒。","萧散。","闲谈今古论兴亡。","虞夏商周秦楚汉，三分南北至隋唐。","看到史官褒贬处。","得趣。","不摇纨扇自然凉。"]},{"t":"西江月 廿一史弹词第八段说五代十国下场词","f":"古风","c":["千古伤心旧事，一场谈笑春风。","残编断简记英雄。","总为功名引动。","个个轰轰烈烈，人人扰扰匆匆。","荣华富贵转头空。","恰似南柯一梦。"]},{"t":"蝶恋花 廿一史弹词第九段说宋辽金夏开场词","f":"古风","c":["检尽残编并断简。","细数兴亡，总是英雄汉。","物有无常人有限。","到头落得空长叹。","富贵荣华春过眼。","汉主长陵，霸主乌江岸。","早悟夜筵终有散。","当初赌甚英雄汉。"]},{"t":"西江月 其一 廿一史弹词第九段说宋辽金夏下场词","f":"古风","c":["三百余年宋史，辽金西夏纵横。","争强赌胜弄刀兵。","谁解倒悬民命。","富贵草梢垂露，英雄水上浮萍。","是非成败总虚名。","一枕南柯梦醒。"]},{"t":"西江月 廿一史弹词第十段说元朝开场下场词二首 其二","f":"古风","c":["山色消磨今古，水声流尽年光。","翻云覆雨数兴亡。","回首一般模样。","清景好天良夜，赏心春暖花香。","百年身世细思量。","不及尊前席上。"]},{"t":"西江月 廿一史弹词第十段说元朝开场下场词二首 其三","f":"古风","c":["细想三皇五帝，一般锦绣江山。","风调雨顺万民安。","不见许多公案。","后世依他样子，齐家治国何难。","流芳百世在人间。","万古称扬赞叹。"]},{"t":"浪淘沙","f":"古风","c":["春梦似杨花。","绕遍天涯。","黄莺啼过绿窗纱。","惊散香云飞不去，篆缕烟斜。","油壁小香车。","水渺云赊。","青楼珠箔那人家。","旧日罗巾今日泪，湿尽韶华。"]},{"t":"鹧鸪天 西庄","f":"古风","c":["秋水澄清胜酒醅。","野烟笼榭似楼台。","弹声林鸟山和尚，写字寒虫水秀才。","乘兴去，兴阑回。","夕阳影里记徘徊。","正思修禊明年约，无奈鸣驺得得催。"]},{"t":"凤栖梧 送薛治曲泉之镇雄勘夷手卷","f":"古风","c":["借寇歌廉春有脚。","皂盖朱幡，辉映江阳郭。","一喢清泉斟且酌。","候人无事闲铃阁。","瘴域岚方劳锁钥。","静柝沉锋，虎凶成鸾鹤。","风飐归旌诗满橐。","休迟竹马儿童约。"]},{"t":"青玉案 昆明邝尹升万州守歌","f":"古风","c":["昆明春水盈盈渡。","咫尺又、销魂路。","金马碧鸡遗爱处。","卧辙攀辕，留綦解佩，望望仙尘去。","鹏海鲸波天一柱。","紞紞鼓声催欲曙。","金紫重来还肯许。","帝加三锡，民歌五裤，早沛清时雨。"]},{"t":"喜迁莺 贺薛曲泉抚台旌奖","f":"古风","c":["青阳有脚。","喜五马重临，江阳城郭。","南定云开，西岷波静，帘卷风清幕。","旱魃化为甘雨露，祷不须泥鹤。","兆万宝，咏千箱四野，丰年如约。","斟酌。","曾见说，老手剧郡，利器无盘错。","犬吠花村，鱼游春水，桴鼓长闲却。","伫闻考绩薇垣，复报荐名荷橐。","计晨夕，莺迁燕贺，金明紫渥。"]},{"t":"归朝欢 亨衢陟明歌","f":"古风","c":["秋尽汀洲苹未歇。","掩映荻花相向折。","一枝好赠朝天人，还如鳷鹊楼前雪。","琼凹连玉凸。","五城边银为宫阙。","墀声寒，非烟丛里，卿蔼瑞云缬。","五马骄嘶虬漏彻。","鞘静佩鸣鹓簉列。","朱衣引队奏彤帏，天言清问尧阶切。","俞音传衮鷩。","赐金增秩干旄孑。","把勋名，昭回青简，身许稷和契。"]},{"t":"百字令 病中起登楼填词一首","f":"古风","c":["遥峰青染，见天外树杪，余霞红闪。","小榭轻埃喜屏翳，层阴才收有渰。","钟鼓新晴，楼台暮景，快听渔阳掺。","酒市旗亭，何处青帘飞飐。","惆怅枕病凋年，棐几尘生，荆扉昼掩。","药里关心诗总废，谁问东皋西崦。","过却重阳，篱边都不见，玉镶金锬。","峭寒无寐，沉沉细数更点。"]},{"t":"酹江月 和坡仙韵，赠陈广文致政归","f":"古风","c":["阳关休唱，且须尽、陶令杯中之物。","宦海无津喜君归，仙叟紫房青壁。","泉石新盟，烟霞旧梦，怀抱皆冰雪。","清风堪挹，斜川栗里争杰。","缅想松菊门庭，田园幽事，兴头先发。","情话琴书消遣处，笑看浮沤生灭。","棋局酒樽，桑榆境相对，朱颜玄发。","行歌坐啸，一任抹风批月。"]},{"t":"归朝欢 叙南李将军园海棠","f":"古风","c":["鶗鴂声中春已尽。","蜀国海棠犹有韵。","已将淡粉换龙涎，渐看绣缬成香晕。","脸霞红半隐。","紫锦经雨胭脂润。","正清欢，云歌柳舞，聊解朱炎愠。","十二金钗花作阵。","不怕周郎回顾问。","薛涛临镜意先慵，黄荃渲笔愁难近。","绿樽倾翠酝。","青蘋风起波文粼。","望高城不见，遥寄香霏阁信。"]},{"t":"浪淘沙 芝山以其慧中所提团扇赠行，侑以蜀锦一幅，词以寄谢","f":"古风","c":["李愿本诗仙。","列屋争妍。","肯分团扇翠帷边。","想见清香凝燕寝，秋水明蠲。","丝繂系兰船。","回首江天。","浣花春水腻鱼笺。","何以报之青玉案，锦字遥传。"]},{"t":"满庭芳","f":"古风","c":["天地侧身，风尘回首，何年梦落南荒。","家山千里，烟月记微茫。","萍水蓬风无定，随处倘佯。","葛藤话、浮生半日，且卧老僧房。","门前来往路，叹迷踪羁旅，混迹渔商。","看海波渺渺，曲似回肠。","玉关外、多愁易老，算不如沉醉为乡。","旗亭下，千金斗酒，一掷买春芳。"]},{"t":"浣溪沙","f":"七言古诗","c":["首夏偏宜淡薄妆。","铜青衫子紫香囊。","清歌一曲送霞觞。","罗袜凌波回洛浦，淡云轻雨拂高唐。","纱厨今夜贺新凉。"]},{"t":"临江仙 其一","f":"古风","c":["红尘鞍马红亭路，天涯一望无穷。","长安日下楚云东。","鸣鞭杨柳陌，分袂杏花丛。","离拍易终人易散，佳人玉箸啼红。","今宵明月与君同。","愁心闻唳鹤，倦寝听归鸿。"]},{"t":"临江仙 其二","f":"古风","c":["池北池南新绿，树头树底残红。","多情休怨雨和风。","东君元是客，归去自匆匆。","怅望鸳鸯别浦，萧条翡翠芳丛。","梦回香冷酒微中。","杜鹍声不断，帘外月朦胧。"]},{"t":"鹧鸪天 其一","f":"古风","c":["宝树林中碧玉凉。","西风又送木犀黄。","开成金粟枝枝重，插上乌云朵朵香。","依绣阁，傍银塘。","广寒宫里白云乡。","迥砧横笛声初断，坠露流风夜正长。"]},{"t":"鹧鸪天 其二","f":"古风","c":["曲阁飘萧一夜风。","名花零落五铢红。","卜欢有信占今夕，买赋多情出后宫。","朝暮朵，浅深丛。","翠帏丝障锦帘栊。","汉江游女愁多露，春在昭阳日影中。"]},{"t":"南乡子 其一 荆州元夕","f":"古风","c":["玉笛送残梅。","片片随风入镜台。","台下新妆传玩处，徘徊。","腊尾春头恨几回。"]},{"t":"南乡子 其二 荆州元夕","f":"古风","c":["丝雨湿香街。","禁住花灯不放开。","闷上紫姑香火会，遥猜。","红豆音书甚日来。"]},{"t":"南乡子 其三 荆州元夕","f":"古风","c":["官柳动新枝。","万缕黄金万缕丝。","折赠行人千里去，回期。","莫待清霜落叶时。"]},{"t":"南乡子 其四 荆州元夕","f":"古风","c":["细雨妒芳姿。","禁住莺翁与燕儿。","待得晴明好天气，迟迟。","花絮飞残水满池。"]},{"t":"南乡子 其五 荆州元夕","f":"古风","c":["芳草被金堤。","野烧红余绿正齐。","恰翠踏青新雨后，萋萋。","裙拂秋千彩架底。"]},{"t":"南乡子 其六 荆州元夕","f":"古风","c":["枉渚与回蹊。","楚雾秦烟望转迷。","相伴王孙千里去，东西。","蝴蝶成团杜宇啼。"]},{"t":"转应曲 其一","f":"古风","c":["双燕。","双燕。","金屋往来长见。","珠帘半卷风斜。","何处衔来落花。","花落。","花落。","日莫长门寂寞。"]},{"t":"转应曲 其二","f":"古风","c":["黄鸟。","黄鸟。","飞过花枝袅袅。","绿阴青子初新。","流水斜阳晚春。","春晚。","春晚。","望断东城上苑。"]},{"t":"转应曲 其三","f":"古风","c":["促织。","促织。","声近银床转急。","熏残百合衣香。","消尽兰膏夜长。","长夜。","长夜。","露冷芙蓉花谢。"]},{"t":"转应曲 其四","f":"古风","c":["青鸟。","青鸟。","来自十洲三岛。","树头梅蕊春催。","枕上残妆梦回。","回梦。","回梦。","城角晓闻三弄。"]},{"t":"渔家傲 其一","f":"古风","c":["水日闲亭谁与共。","吸残寒露冰壶冻。","倒影云峰潭影空。","湘箔动。","荼蘼架底清香送。","篆缕熏残衣雾重。","黄梅润透红绡缝。","枕上醒回池上梦。","开雪洞。","瑶琴一曲江南弄。"]},{"t":"渔家傲 其二","f":"古风","c":["水晶帘外炎歒永。","纱厨斗帐神仙洞。","酪粉蔗浆分碧瓮。","琼斝奉。","玲珑弦上传啰唝。","歌罢酒阑行雨送。","银盆沐水煎金凤。","懒髻䰒松云乱拥。","凉意动。","暗惊团扇生秋梦。"]},{"t":"临江仙 其一","f":"古风","c":["江国梅花千万朵，白云乡里温柔。","笛声几度怨梁州。","梦中云满树，醒后月当楼。","正是相思春信早，桑禽啼破香愁。","一枝难寄陇西头。","燕姬钗上见，应是更风流。"]},{"t":"临江仙 其二","f":"古风","c":["玉水堤旁千树柳，仙宫还在人天。","是谁驴背耸诗肩。","不如来饮酒，倾倒醉吟边。","鸟踏画檐时点缀，珠帘向晚风穿。","依稀竹上尽婵娟。","黄昏图画出，云尽月重圆。"]},{"t":"望江南 其一","f":"古风","c":["梅蕊好，冰玉出烟尘。","袅袅孤芳尘外色，盈盈一朵掌中春。","只少似花人。"]},{"t":"望江南 其二","f":"古风","c":["明月好，流影浸亭台。","金界三千随望远，雕阑十二逐人来。","只是欠传杯。"]},{"t":"望江南 其三","f":"古风","c":["晴雪好，万瓦玉鳞浮。","照夜不随青女去，羞明应为素娥留。","只欠剡溪舟。"]},{"t":"清平乐 其一","f":"古风","c":["灯红酒绿。","山掩围屏曲。","何处萧萧风动竹。","好梦惊回难续。","月华冷浸霜华。","寒林惊起寒鸦。","道是天明尚早，小窗横影花花。"]},{"t":"清平乐 其二","f":"古风","c":["金炉尘满。","绣被熏香懒。","此恨破除须酒盏。","争奈愁深酒浅。","多时弦断瑶琴。","空余孤凤悲吟。","谩道鸾胶能续，续来不是前音。"]},{"t":"荷叶杯 其一","f":"古风","c":["枕上一声鸡唱。","天亮。","好梦忽惊残。","锦帐香消翠被单。","寒么寒。","寒么寒。"]},{"t":"荷叶杯 其二","f":"古风","c":["远寄音书一纸。","千里。","一字一徘徊。","泪眼愁眉不忍开。","来么来。","来么来。"]},{"t":"蝶恋花 其一","f":"古风","c":["玉貌合教金屋贮。","天上仙姿，谪在人间住。","九霞山下曾相遇。","瓠犀笑破樱桃注。","别来青鸟如何处。","岂有仙踪，好寄相思句。","海月团团生碧树。","梦随惊鹊南飞去。"]},{"t":"蝶恋花 其二","f":"古风","c":["好梦难成云易散。","玳瑁筵前，当日亲曾见。","金杯满捧香醪劝。","朱唇半吐樱桃绽。","别后佳期天样远。","夜夜相思，寸寸柔肠断。","徙倚画楼千万遍。","落梅庭院飘银霰。"]},{"t":"浪淘沙 其一","f":"古风","c":["灵鹊噪重檐。","几度虚占。","锦江春水隔鹣鹣。","怕见雕梁双燕子，常下珠帘。","离恨恼江淹。","彩笔慵拈。","碧云离合暮山尖。","伴我归心和别梦，只有银蟾。"]},{"t":"浪淘沙 其二","f":"古风","c":["去燕又来鸿。","节序匆匆。","秋声半夜搅梧桐。","惊起南窗千里梦，满地西风。","欹枕听寒蛩。","离思无穷。","归期又误菊花丛。","遥想玉人肠断处，屈遍春葱。"]},{"t":"浪淘沙 其三","f":"古风","c":["鸦晚又鸡晨。","最恼离人。","添花补柳为谁春。","飞鹊镜中妆态减，窗锁朱尘。","璧月几回新。","惯照眉颦。","青山隐隐水粼粼。","万水千山经岁别，远似星津。"]},{"t":"浪淘沙 其四","f":"古风","c":["归思满琴心。","幽恨难禁。","月儿楼下海棠阴。","想见纤纤弦上手，羽咽高沈。","青鸟寄归音。","一字千金。","离鸾别凤谩沈吟。","花发月圆须寄取，好在春深。"]},{"t":"何满子 其一","f":"古风","c":["玄灞长松繫马，青门高树藏鸦。","红雨秋千香径软，乐游原上谁家。","客里心情缭乱，愁看风外杨花。"]},{"t":"何满子 其二","f":"古风","c":["夜夜遥钟促漏，朝朝急莞清笳。","行见月圆还月缺，乡关犹隔三巴。","客里形容憔悴，愁看匣里菱花。"]},{"t":"何满子 其三","f":"古风","c":["欹枕梦回春晚，倚阑人在天涯。","迢递关山千万里，佳期水渺云赊。","记得罗巾别泪，愁看带雨梨花。"]},{"t":"何满子 其四","f":"古风","c":["韪鴂催成绿雨，鹧鸪啼破红霞。","马上韶华真似梦，恼人春思交加。","记得晓妆临镜，愁看映水桃花。"]},{"t":"望江南 其一","f":"古风","c":["故园好，最忆世耕亭。","樵斧丁丁惊鹳雀，钓丝袅袅立蜻蜓。","百曲建长瓴。"]},{"t":"望江南 其二","f":"古风","c":["来往惯，蓬户不教扃。","山屐过时穿嫩藓，野航移处破浮萍。","炬火晚荧荧。"]},{"t":"望江南 其三","f":"古风","c":["故园好，最忆力耕亭。","径路喜逢樵叟话，蹊田一任牧童经。","浑不限畦町。"]},{"t":"望江南 其四","f":"古风","c":["螺涧底，呜玉漱清泠。","千里清风来曲几，一方明月挂疏棂。","欹枕酒初醒。"]},{"t":"望江南 其五","f":"古风","c":["故园好，最忆约耕亭。","曲水流觞穿竹细，奇峰侧岛泛花馨。","唤作小沧溟。"]},{"t":"望江南 其六","f":"古风","c":["长夏日，独往亦消停。","仙酝一壶倾绿醑，蛮笺十样写黄庭。","落魄尽忘形。"]},{"t":"望江南 其七","f":"古风","c":["故园好，最忆阅耕亭。","流水两地分丽泽，好山四面列围屏。","修竹绕青青。"]},{"t":"望江南 其八","f":"古风","c":["松槛外，鹭渚与凫汀。","茅屋不愁经夜雨，草堂还喜带春星。","歌咏满林坰。"]},{"t":"望江南 其九","f":"古风","c":["故园好，最忆是恩波。","月映涟漪天映水，霞翻菡萏露翻荷。","风景占偏多。"]},{"t":"望江南 其十","f":"古风","c":["茅屋小，斜枕碧山阿。","蕙冷松寒闻夜鹤，藻香萍煖下天鹅。","不羡懒云窝。"]},{"t":"望江南 其十一","f":"古风","c":["故园好，最忆是毗江。","夹路青萝藏古寺，半林红叶照清淙。","烟社枕云杠。"]},{"t":"望江南 其十二","f":"古风","c":["霜景霁，何处远钟撞。","扣月渔榔寒轧轧，祈年社鼓夜逢逢。","幽梦起山窗。"]},{"t":"望江南 其十三","f":"古风","c":["故园好，最忆是龙门。","洞底渔舟藏夜壑，山头佛刹挂朝暾。","暧暧远人村。"]},{"t":"望江南 其十四","f":"古风","c":["登顿处，萝磴几回扪。","檐葡林中消永日，松篁影里荫芳尊。","归路已黄昏。"]},{"t":"望江南 其十五","f":"古风","c":["故园好，最忆是中洲。","宛在中央浑绝俗，登兹四望可销忧。","丘壑擅风流。"]},{"t":"望江南 其十六","f":"古风","c":["凉吹满，六月早知秋。","仙侣泛花曾共醉，野人刻竹记同游。","何日问归舟。"]},{"t":"生查子 其一","f":"五言律诗","c":["金匮失玄参，无约何时会。","争道破揪枰，心为佳期碎。","杨柳困三眠，终日常如醉。","露泣缠枝花，满眼娇情泪。"]},{"t":"生查子 其二","f":"五言律诗","c":["两朵活莲花，一对相思卦。","裙底耍鸳鸯，巧笔难描画。","春困步苍苔，背立秋千下。","心事倩谁传，花落西厢夜。"]},{"t":"转应曲 其一","f":"古风","c":["江水。","江水。","昨夜风惊浪起。","眼看估客归舟。","肠断征人泪流。","流泪。","流泪。","离恨江沙共碎。"]},{"t":"转应曲 其二","f":"古风","c":["归路。","归路。","遥隔铁桥铜柱。","楼头秋霁无尘。","陌上愁看去人。","人去。","人去。","心头千山碧树。"]},{"t":"转应曲 其三","f":"古风","c":["采菊。","采菊。","且醉尊前醽醁。","百分觥棹船空。","万虑销沈酒中。","中酒。","中酒。","又度客边重九。"]},{"t":"捣练子 集句 其一 伤乱","f":"古风","c":["花亚朵，柳垂丝。","楼上风和玉漏迟。","春困苦多无处卖，日长惟与睡相宜。"]},{"t":"捣练子 集句 其二 伤乱","f":"古风","c":["风料峭，月栊明。","滴破春愁压酒声。","犹有夸张年少处，醉闻花气睡闻莺。"]},{"t":"捣练子 集句 其三 伤乱","f":"古风","c":["长寂寞，独徘徊。","抱病起登江上台。","万户千门春色闭，谁家桃李乱中开。"]},{"t":"捣练子 集句 其四 伤乱","f":"古风","c":["销午梦，减春愁。","上尽重楼更上楼。","日暮乡关何处是，寒鸦飞去水悠悠。"]},{"t":"捣练子 集句 其五 伤乱","f":"古风","c":["金碧岸，锦春丛。","红白花开烟雨中。","今日乱离俱是梦，六街尘起鼓冬冬。"]},{"t":"捣练子 集句 其六 伤乱","f":"古风","c":["愁对酒，懒看花。","病入新年感物华。","万里寂寥音信断，山楼粉蝶隐悲笳。"]},{"t":"浣溪沙 其一 游感通寺赠冰壶","f":"七言古诗","c":["病起思乡太剧愁。","荒城无地可登楼。","仙人要我感通游。","绿水似环萦岛屿，白云如带绕林丘。","凉风先借一分秋。"]},{"t":"浣溪沙 其二 游感通寺赠冰壶","f":"七言古诗","c":["柳绿槐黄放晓晴。","天公知我欲山行。","峰峦相顾亦多情。","玉树临风无奈爽，冰壶见底有余清。","长生仙客话无生。"]},{"t":"西江月 其一","f":"古风","c":["酝造一场烦恼，只因些子恩情。","阳台春梦不曾成。","枉度雨云朝暝。","燕子那知我意，莺儿似唤他名。","消除只有话无生。","除却心头重省。"]},{"t":"西江月 其二","f":"古风","c":["倚醉深关朱户，娇羞怕捧金觥。","背人弹泪绕花行，唱尽新词懒听。","总是为郎调护，当初枉道无情。","英雄摩勒肯重生。","赎取佳人薄命。"]},{"t":"西江月 其三","f":"古风","c":["自有嫩枝柔叶，何须补柳添花。","低声昵语似雏鸦。","肠断东桥月下。","香雾清辉何处，春风今夜谁家。","五花骢马七香车。","趁取小乔未嫁。"]},{"t":"西江月 其四","f":"古风","c":["玉指管生弦涩，朱唇语颤声羞。","动人一味是温柔。","为甚两眉长皴。","不惯秋娘渡口，乍离阿母池头。","临邛太守最风流。","肯许凤求皇否。"]},{"t":"木兰花 其一","f":"七言律诗","c":["遥钟促漏难成寝。","残月疏灯寒凛凛。","镜添华发似愁潘，带减腰肢如病沈。","玉箫尘琐无心品。","故国经年书断锦。","欲寻石上一柯棋，共醉山中千日饮。"]},{"t":"木兰花 其二","f":"七言律诗","c":["枝头百舌塞犹噤。","病起心情无赖甚。","乍看南浦月名娟，记得东园花姓沈。","枕肱不枕鸳鸯枕。","倚醉偎人偏越恁。","如今憔悴背花眠，只有余香留燕寝。"]},{"t":"木兰花 其三","f":"七言律诗","c":["晓寒倦倚相思枕。","丝雨织愁愁欲稔。","绿杨桥畔觅谁家，油壁香车迎阿沈。","莫教错送回文锦。","密地重将青鸟审。","流萤庭户嫩凉天，月许再圆花再品。"]},{"t":"踏莎行 其一 甲午新春书感","f":"古风","c":["异国光阴，暮冬羁旅。","鬓丝禅榻今如许。","羞将白发对青铜，慵把流霞烘绿醑。","旧侣雕零，新欢间阻。","东风杨柳萦愁绪。","天寒独立咏苍茫，销魂正在斜阳处。"]},{"t":"踏莎行 其二 甲午新春书感","f":"古风","c":["白雪墙头，红云水面。","匆匆花事看看半。","去年花对断肠人，今日有肠无处断。","萧寺双文，巫山一段。","旧游回首空长叹。","晓屏灯烬峭寒天，梦为远别啼难唤。"]},{"t":"风入松 其一","f":"古风","c":["喷香瑞兽小妆台。","咫尺天台。","芭蕉不展丁香结，闭春心、眉锁难开。","银蜡烧灯过后，金钗斗草归来。","徘徊花月可怜宵。","天近人遥。","有情芍药含春泪，梦回时、一枕无聊。","王母池边翠水，云英家住蓝桥。"]},{"t":"风入松 其二","f":"古风","c":["月窗花院好风光。","谢女檀郎。","朝朝暮暮遥相望，殢人娇、罗带留香。","青鸟解传消息，银河不隔红墙。","绣罗红嫩抹酥胸。","此夕重逢。","妒云恨雨腰肢袅，晕眉心、獭髓分红。","蜡烛寒笼翡翠，麝香煖度芙蓉。"]},{"t":"浣溪沙 其一","f":"七言古诗","c":["小岁新阳好物华。","句东春信到梅花。","断钟残角又天涯。","酒面浮金添嫩蚁，钗头屈玉艳雏鸦。","暗香疏影认林家。"]},{"t":"浣溪沙 其二","f":"七言古诗","c":["滇海明珠照永昌。","纤罗豆蔻减浓香。","蚁穿红线结盘囊。","已信春金仍应玉，不愁转紫复回黄。","星横洞户月侵廊。"]},{"t":"殿前欢 其一 感通寺赠承冰壶炼帅、董西羽徵君","f":"古风","c":["问冰壶。","洞天还似此中无。","留春长在和春住。","月冷山孤。","愿指瑶台路。","好把朱颜住。","不续玄都赋。","吾今忘我，我亦忘吾。"]},{"t":"殿前欢 其二 感通寺赠承冰壶炼帅、董西羽徵君","f":"古风","c":["枕西阿。","仙洲玉几对金梭。","苍山九点空中堕。","影蘸烟波。","避暑云端卧。","爱月天边坐。","沽酒墙头过。","狂歌谁和，谁和狂歌。"]},{"t":"渔家傲 其一 滇南月节","f":"古风","c":["正月滇南春色早。","山茶树树齐开了。","艳李夭桃都压倒。","妆点好。","园林处处红云岛。","彩架秋千骑巷笊。","冰丝宝料星毬小。","误马随车天欲晓。","灯月皎。","碧鸡三唱星回卯。"]},{"t":"渔家傲 其二 滇南月节","f":"古风","c":["二月滇南春嬿婉。","美人来去春江煖。","碧玉泉头无近远。","香径软。","游丝摇拽杨花转。","沽酒宝钗银钏满。","寻芳争占新亭馆。","枣下艳词歌纂纂。","春日短。","温柔乡里归来晚。"]},{"t":"渔家傲 其三 滇南月节","f":"古风","c":["三月滇南游赏竞。","牡丹芍药晨妆亲。","太华华亭芳草径。","花饾饤。","罗天锦地歌声应。","陌上柳昏花未瞑。","青楼十里灯相映。","絮妥尘香风已定。","沈醉醒。","提壶又唤明朝兴。"]},{"t":"渔家傲 其四 滇南月节","f":"古风","c":["四月滇南春迤逦。","盈盈楼上新梳洗。","八节常如三月里。","花似绮。","钗头无日无花蕊。","杏子单衫鸦色髻。","共倾浴佛金盆水。","拜愿灵山催早起。","争乞嗣。","蛛丝先报钗梁喜。"]},{"t":"渔家傲 其五 滇南月节","f":"古风","c":["五月滇南烟景别。","清凉国里无烦热。","双鹤桥边人卖雪。","冰碗啜。","调梅点蜜和琼屑。","十里湖光晴泛蝶。","江鱼海菜鸾刀切。","船尾浪花风卷叶。","凉意惬。","游仙梦绕蓬莱阙。"]},{"t":"渔家傲 其六 滇南月节","f":"古风","c":["六月滇南波漾渚。","水云乡里无烦暑。","东寺云生西寺雨。","奇峰吐。","水椿断处余霞补。","松炬荧荧宵作午。","星回令节传今古。","玉伞鸡㙡初荐俎。","荷芰浦。","兰舟桂楫喧箫鼓。"]},{"t":"渔家傲 其七 滇南月节","f":"古风","c":["七月滇南秋已透。","碧鸡金马山新瘦。","摆渡村西南坝口。","船放溜。","松花水发黄昏后。","七夕人家衣襮绣。","巧云新月佳期又。","院院烧灯如白昼。","风弄袖。","刺桐花底仙裙皱。"]},{"t":"渔家傲 其八 滇南月节","f":"古风","c":["八月滇南秋可爱。","红芳碧树花仍在。","园圃全无摇落态。","春莫赛。","玫瑰彩缕金针繲。","屈指中秋餐沆瀣。","遥岑远目天澄派。","七宝合成银世界。","添爽快。","凉砧敲月胜竿籁。"]},{"t":"渔家傲 其九 滇南月节","f":"古风","c":["九月滇南篱菊秀。","银霜玉露香盈手。","百种千名殊未有。","摇落后。","橙黄菊绿为三友。","摘得金英来泛酒。","西山爽气当窗牖。","鬓插茱萸歌献寿。","君醉否。","水晶宫里过重九。"]},{"t":"渔家傲 其十 滇南月节","f":"古风","c":["十月滇南栖煖屋。","明窗巧钉迎东旭。","速鲁麻香春瓮熟。","歌一曲。","酥花乳线浮杯绿。","蜀锦吴绫熏夜馥。","洞房窈窕悬灯宿。","扫雪烹茶人似玉。","风动竹。","霜天晓角肌生粟。"]},{"t":"渔家傲 其十一 滇南月节","f":"古风","c":["十一月滇南云幕野。","漕溪寺里梅开也。","绿萼黄须香趁马。","携翠斝。","墙头沽酒桥头泻。","江上明蟾初冻夜。","渔蓑句好真堪画。","青女素娥纷欲下。","银霰洒。","玉鳞皴遍鸳鸯瓦。"]},{"t":"渔家傲 其十二 滇南月节","f":"古风","c":["十二月滇南娱岁晏。","家家玉饵雕盘荐。","安息生香朱火焰。","槟榔串。","红潮醉颊樱桃绽。","苔翠氍毹开夜宴。","百夷枕粲文衾烂。","醉写宜春情兴懒。","妆阁畔。","屠苏已识春风面。"]},{"t":"菩萨蛮 其一","f":"古风","c":["袅袅腰肢浑似柳。","碧花茗椀劳纤手。","清昼小横陈。","阳台梦未真。","一声鶗鴂暮。","两浆催人去。","新月曲如眉。","黄昏怅望时。"]},{"t":"菩萨蛮 其二","f":"古风","c":["梦云溶曳巫阳夜。","兰台风起春寒乍。","花鸟莫深愁。","笙歌聊写忧。","蛾眉梳堕马。","象口熏残麝。","浓睡带余酲，翠窗啼晓莺。"]},{"t":"临江仙 其一 可渡桥喜晴","f":"古风","c":["可渡新晴韶景媚，不愁寒透征衣。","滇阳渐近雪霜微。","旧游如梦寐，旅思欲纷蜚。","时序惊心催候雁，嗈嗈鸣向朝晖。","多情何事帛书稀。","明年春色里，领取一行归。"]},{"t":"临江仙 其二 可渡桥喜晴","f":"古风","c":["万里云南可渡，七旬老叟华颠。","金羁翠眊杏花鞯。","还家剑锋画，出塞马蹄穿。","旧店主人争羡，升翁真是神仙。","东征西走几多年。","风霜知自保，穷达任皇天。"]},{"t":"浣溪沙 其一","f":"七言古诗","c":["步彻香尘倚画阑。","丛头合凤尾交鸾。","金莲并蒂月双弯。","宋玉东邻芳草软，江淹南浦落花干。","抱云勾雪近灯看。"]},{"t":"浣溪沙 其二","f":"七言古诗","c":["解唱隋家昔昔盐。","离亭别宴柳毵毵。","远山颦映翠眉尖。","霅上恰嫌苕子小，江都还笑宝儿憨。","断肠春色在江南。"]},{"t":"浣溪沙 其三","f":"七言古诗","c":["脚上鞋儿血色罗。","掌上无力斗弯靴。","月牙新样不争多。","芍药栏边穿窈窕，柘枝筵下舞婆娑。","芙蓉帐里奈君何。"]},{"t":"沅江曲 其一","f":"古风","c":["绿萝山豁午烟开，野贩山樵竞野回。","叠浪高潭浑不畏，?艚船上唱歌来。"]},{"t":"沅江曲 其二","f":"七言绝句","c":["碧天霜冷月明多，平澧风交湘水波。","夜夜枫林惊客棹，村村铜鼓和蛮歌。"]},{"t":"罗甸曲贵州道中 其一","f":"五言绝句","c":["百里驰驱倦，三更梦魂归。","不辞昼夜苦，但使逢春晖。"]},{"t":"罗甸曲贵州道中 其二","f":"五言绝句","c":["山围罗甸国，水绕的澄桥。","桥下东流水，可惜无兰桡。"]},{"t":"罗甸曲贵州道中 其三","f":"五言绝句","c":["寒灯閟孤馆，阴云锁重城。","长夜恒思晓，久雨恒思晴。"]},{"t":"罗甸曲贵州道中 其四","f":"五言绝句","c":["登山千寻梯，下阪九仞井。","雨润衣珠融，风吹鬓毛冷。"]},{"t":"罗甸曲贵州道中 其五","f":"五言绝句","c":["蛮树不凋叶，蛮云不放晴。","长亭望不见，何处是渣城。"]},{"t":"罗甸曲贵州道中 其六","f":"五言绝句","c":["林间山胡鸟，声声啼我前。","何似故园里，花亭闻杜鹃。"]},{"t":"关岭曲贵州 其一","f":"五言绝句","c":["倦枕愁鸡鸣，问郎今日程。","中路不可宿，长途须早行。"]},{"t":"关岭曲贵州 其二","f":"五言绝句","c":["北登鸡公背，南望象鼻岏。","相逢试相问，往来定谁难。"]},{"t":"关岭曲贵州 其三","f":"古风","c":["关索岭，四十三盘高。","前有安龙菁，行人莫辞劳。"]},{"t":"关岭曲贵州 其四","f":"古风","c":["老鸦关，仰树间。","灵卜西去何当还。"]},{"t":"蜻蛉谣","f":"古风","c":["蜻蛉川，硪碌野。","铁菁穷崖，飞鸟不下。","魋结成群行，白日腥风洒。","系我氂牛驱笮马，金鸡庙前无行者。","使君坐紫城，枹鼓卧不鸣。","苍山平，洱水清。","守犬无夜惊，行商达天明。","白羽蠹，青苗生，南山踏歌北山耕。","愿留使君住，只愁使君去。","畏途前番君不闻：高车驷马亦使君，劫商毋下殷车轮。"]},{"t":"新春始泛歌 其一","f":"七言绝句","c":["螳螂川水青如苔，漕溪寺花红满台。","韶光满眼莫惜醉，几个扁舟乘兴来。"]},{"t":"新春始泛歌 其二","f":"七言绝句","c":["白沙渡口几人家，红粉当垆青旆斜。","梁上新巢早留燕，门前垂柳暗藏鸦。"]},{"t":"悲酸行","f":"五言古诗","c":["少日多欢悰，老境足悲酸。","悲酸一何易，欢悰一何难。","游子久不归，憔悴羁南冠。","亲庭隔千里，梦中路漫漫。","年来转漂泊，居处无恒安。","征马常苦瘦，旅席常苦寒。","有客过我门，劝我强加餐。","春阳正发育，覆载本自宽。","穷途谢好音，白意于青翰。"]},{"t":"蒙鸠篇","f":"古风","c":["辞家乡，去亲爱。","远从军，万里外。","日暮旷野，霜风冻我。","有夫行恻，营巢寄所。","蒙鸠语老鸱，摘巢抨去之。","老鸱言：此鸟是凤凰，抨之恐不祥。","但可嚇去之，不令在我傍。","凰止凤飞，羽毛摧颓。","五里一返顾，十里一徘徊。","山川嵯峨，嵚岑隐阿。","且饮晨露，飧朝霞。","祸无常门，福无常家。","咄嗟呼，伤哉谓之何。"]},{"t":"青蛉行寄内 其二","f":"七言绝句","c":["燕子伯劳相寺眠，牵牛织女别经年。","珊瑚宝树生海底，明星白石在天边。"]},{"t":"遥夜吟","f":"五言古诗","c":["明发叶榆城，瞑逗兰津渡。","超忽类飞翰，往来如织路。","仆痡马亦黄，簪短带复长。","天高行谁问，日暮坐自伤。","鸿飞畏逢罗，虎饥正出柙。","寒流泚玄冠，凉风吹白帢。","子有负俗累，予乃投荒人。","暌形而比影，异习仍同尘。","晤言能几朝，契阔还叠夕。","浪迹苦难并，嘉会良易掷。","翻忆在滇海，翻思在连然。","嬥歌花馆醉，清梵云房眠。","丹荧耿遥夜，乌臼聒五晓。","相望不可晨，咫尺限云杪。"]},{"t":"舞姬脱鞋歌题画","f":"古风","c":["潘妃睡起冷金沙，弓鞋半脱双鸾斜。","越罗袜衬齐纨素，彩霞摇裔香生步。","旱路金蕖白日娥，芝田洛浦凌微波。","曳霜回雪下平地，琉璃滑泽春云腻。","花松玉软娇无力，天公一笑生春色。","宝兰困倚殢?跚，小玉双成扶不得。","起来翘翠踏方尘，妆台搦镜重梳匀。","人间绝世谁相并，月钩下斗缃钩新。"]},{"t":"南中晓寒曲","f":"古风","c":["南中异节候，北陆戒裘炉。","夜冻玉朴遫，朝寒金毕逋。","可念无衣客，谁徵褰与?。"]},{"t":"龙编行荅禺山","f":"七言古诗","c":["北极军书一羽过，南交氛祲九真多。","金潾铜柱天王地，象渚龙编瘴海波。","渭曲屯田愁葛亮，关中馈饷急萧何。","岚开比景鸢低水，风度鸣沙马喷陀。","自许将军回白日，谁凭壮士挽银河。","腾峰浴铁朝乘陡，下濑楼船夜戢戈。","翡翠越裳近消息，麒麟汉阁远嵯峨。","婆婆横吹惊杨柳，晔晔商声响薜萝。","隐豹文韬须雾泽，荒鸡舞困且渔蓑。","欣闻幕府收才彦，伫立衡门听凯歌。"]},{"t":"莋马行","f":"五言律诗","c":["莋马出滇西，青金护凿蹄。","朝骖过归雁，夕驾轶昆鸡。","蹀雪工升甗，陵云欲舞梯。","流星迸石齿，讶道火龙飞。"]},{"t":"葵镜吟赠右溪","f":"五言律诗","c":["蜀葵与唐镜，同节复争鲜。","蜀葵终向日，唐镜每羞天。","卉木异情性，造化均陶甄。","安得指佞早，重植尧阶前。"]},{"t":"烟丸歌赠制墨毛道士羽周","f":"七言古诗","c":["鸡足烟丸古松心，龙眠惜之如惜金。","玄霜遥分玉兔窟，碧髓近挺青蛉岑。","茅犀截角光自照，柏麝却脐香太侵。","鸿崖羽人故多幻，鹤驭明朝那可寻。","莫辞为我涴霞襟。"]},{"t":"后缓声歌","f":"古风","c":["泽藏之山，必有陆沉之波。","物或反其常，君将柰之何。","雌骁难为雄，斧小不胜柯。","心之忧矣歌且讹。","复思入淮之爵，必有飞海之鳐。","披枝且害心，繁实多陨条。","吐珠谁不含，曼䎼能无招。","心之忧矣歌且谣。"]},{"t":"罗甸吟","f":"古风","c":["苴兰方号鬼，贵竹甸名罗。","牛涔枉称海，骏坂犹题坡。","林馀楚筚辂，?识汉牂牁。","久戍劳行恻，天高柰若何。"]},{"t":"笠泽弄三解为潘参藩父寿 其一","f":"古风","c":["蜀城东望笠泽云。","轮囷摇曳青氤氲。","万里从龙持献君。","将献君，先过里。","攒凤笙，歌燕喜。"]},{"t":"笠泽弄三解为潘参藩父寿 其二","f":"古风","c":["五津东下仙舟轻。","三泖凉波秋水平。","景丁南极中宵明。","中宵明，玄景焕。","展国容，拜家宴。"]},{"t":"笠泽弄三解为潘参藩父寿 其三","f":"古风","c":["莺湖小雪梅照天。","鲈?莼豉酒如泉。","锦袍起舞白华篇。","白华篇，丹桂曲。","祝千龄，绥百禄。"]},{"t":"鹙郎行","f":"七言律诗","c":["茈泽鹙郎唼雏鸭，惊飞鸳鸯逐鸭鵊。","翠袖啼春幽凤奁，红丝穿露空鸾柙。","碧眼胡儿乱驰鸨，三五红颜片时老。","今日盈盈滇海花，明旦萧萧陆凉草。"]},{"t":"田家喜晴谣","f":"七言律诗","c":["玉女投壶玉皇侧，海童拖霖海天黑。","风花闪日日笑云，云气烘为雀头色。","须臾变作楼梯天，黄绵袄出晒破砖。","茅檐夜望黎星没，芦絮飞残水生骨。"]},{"t":"古怨","f":"五言律诗","c":["游树正丰茸，清防深几重。","金星长乐漏，璧月景阳钟。","扫粉赵飞燕，捲衣秦祖龙。","妆成独不见，倾国为谁容。"]},{"t":"补皋鱼风木吟为黄月坡政使赋","f":"楚辞体","c":["晨风摇摇，有鸟朝嘲。","不息终朝，予心孔劳。","夕风习习，有鸟夜㖡。","不息终夕，予心孔棘。","树欲静兮，风则起矣。","子欲养兮，亲则巳矣。","枯鱼衔索兮，蠹何泣矣。","养之不逮兮，祭何及矣。"]},{"t":"楚竹吟","f":"五言古诗","c":["便娟之脩竹，寄生乎江潭。","葳蕤上防露，泠泠下来风。","那知竹与柏，虚塞两异心。","蓬矢射犀草，箘落委荒林。","夏首西浮远，涔阳南望深。","大招自抽怨，小歌徒悲吟。","天高何傩问，斯情匪斯今。"]},{"t":"游女行","f":"五言律诗","c":["东风春正韶，南浦美人娇。","下蔡君休问，上官谁敢邀。","折花斜宝珥，映水正金翘。","娉婷惜未嫁，应待逐文箫。"]},{"t":"湖艳曲","f":"五言绝句","c":["素足踏金沙，波摇半臂霞。","东风湖滟好，疑是孟珠家。"]},{"t":"江艳曲","f":"古风","c":["交甫江皋见，刘晨洞里逢。","可怜?踏雁，不用髻盘龙。"]},{"t":"思远道","f":"五言律诗","c":["章丹请辍舞，秦青且罢歌。","佳人上宫出，俪婺复倾娥。","夜月光如练，春江纹似罗。","所思在远道，朱颜谁为配。"]},{"t":"竹浪词为刘珥江赋 其一","f":"七言绝句","c":["新结茅斋近少城，清流映带更多情。","幽怀似怪王维少，柳浪何如竹浪清。"]},{"t":"竹浪词为刘珥江赋 其二","f":"七言绝句","c":["青岚帚扫紫筠烟，垂露珠零绿粉天。","最美仙郎能缩地，筼筜谷在锦江边。"]},{"t":"竹浪词为刘珥江赋 其三","f":"七言绝句","c":["一部清商竹啸风，三霄碧纛舞晴空。","披襟巳在珠宫上，宋玉兰台赋漫雄。"]},{"t":"竹浪词为刘珥江赋 其四","f":"七言绝句","c":["锦箨花绷护笋根，龙孙蛇祖启风门。","对青好续涪翁赋，滴露研朱挂月村。"]},{"t":"竹浪词为刘珥江赋 其五","f":"七言绝句","c":["众窍为嘘万窍号，调调未定见刁刁。","画风雄笔君须继，北海南溟捲紫毫。"]},{"t":"竹浪词为刘珥江赋 其六","f":"七言绝句","c":["鸾暮笼烟还漏月，凤晨防露更来风。","宽闲不似城中地，水碧金膏五百弓。"]},{"t":"竹浪词为刘珥江赋 其七","f":"七言绝句","c":["一节为船碧海通，十洲三岛访仙翁。","乘风破浪非坐事，好在垂天万里蓬。"]},{"t":"吴楚行","f":"五言律诗","c":["神女巫山上，西施越网中。","朝云迷楚国，夕露满吴宫。","舞榭青枫树，歌台绿蕙丛。","伍员魂巳断，宋玉赋休工。"]},{"t":"涉江采芙蓉","f":"五言古诗","c":["沉沉秋江水，灼灼芙蓉花。","叶叶凌清霜，枝枝明朝霞。","娟娟东邻子，采采惜芳华。","昔时赠同心，今日悲天涯。","欲寄苦无因，向风长叹嗟。"]},{"t":"代古日出行","f":"五言古诗","c":["晨登石峦望，浮云何相羊。","飘风自东来，若木回其光。","景曜薄万里，下界犹养凉。","曾崖自郁郁，芳茝含春霜。","草虫一何微，感物鸣其傍。","天池有黄鹄，一举知圜方。"]},{"t":"灵菊篇效陆平原","f":"五言古诗","c":["灵菊植幽崖，擢颖凌寒飙。","春露不染色，秋霜不改条。","三泉漱玄根，九阳晞素苗。","衡星散光晶，香气何飘飘。","东林生玉树，西畹生兰翘。","懿此葳蕤茂，感彼芸黄凋。","采为仙人食，千载通一朝。","金童酌霞醴，神女弹云璈。","顾视西王母，翠发如陵苕。"]},{"t":"扶南曲 其二","f":"五言古诗","c":["愁窥绿绮琴，弦涩不成音。","镜里春春貌，窗前夜夜心。","临卬人去远，离梦绕花阴。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["金莲作杵琼瑰砧，蛟龙艳锦鸳鸯衾。","并刀未剪燕霜落，何日征衣到沙漠。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["昼漏迢迢春滟滟，草如柔罽花如焰。","白日红窗恨转多，个侬无计奈春何。"]},{"t":"乌栖曲 其三","f":"七言绝句","c":["汝南鸣鸡乌臼鸟，强颜饶舌催天晓。","残妆相送泪阑干，月帐云屏生晓寒。"]},{"t":"乌栖曲 其四","f":"七言绝句","c":["月华二八星三五，丁丁漏水鼕鼕鼓。","相思相忆阻河桥，可怜人度可怜宵。"]},{"t":"宛转歌","f":"七言古诗","c":["明河拂愰月栖檐，惊乌号林萤入帘。","美人遥夜歌宛转，罗衣不襞宫黄浅。","愁听更漏转分明，紞紞楼头五鼓声。"]},{"t":"梁白纻舞歌 其一","f":"七言古诗","c":["仙人六著帝台棋。","高张洞越吹参差，二八递代三商移。","含娇吝彩閟容仪。","流云不度华星迟。","炉火九微镫九枝。","腾觚飞爵朱颜怡。","传空引满客忘疲。","满堂不语心相知。"]},{"t":"梁白纻舞歌 其二","f":"古风","c":["英英白纻雪色光，机杼出自寒女房。","裁作舞衣双袖长，吴娃魏粲自相将。","宛转顾步双鸳鸯，俨若星月舒其芒。","?如结旌体如翔，秋药被风兰袅香。","回身再拜捧瑶觞，千秋万岁侍君王。"]},{"t":"桂湖曲送胡孝思","f":"五言古诗","c":["君来桂湖上，湖水生清风。","清风如君怀，洒然秋期同。","君去桂湖上，湖水映明月。","明月如怀君，怅然何时辍。","湖风向客清，湖月照人明。","别离俱有忆，风月重含情。","含情重含情，攀留桂之树。","珍重一枝才，留连千里句。","明年桂花开，君在雨花台。","陇禽传语去，江鲤寄书来。"]},{"t":"阻风曲罐子矶作 其一","f":"七言绝句","c":["峭石惊矶横浦口，朔风半夜蛟龙吼。","一枕波涛万里心，江水客愁谁浅深。"]},{"t":"阻风曲罐子矶作 其二","f":"七言绝句","c":["行人夜唱江南曲，巴歈楚㱔遥相续。","声声怨暝复愁更，诉尽离情天未明。"]},{"t":"阻风曲罐子矶作 其三","f":"七言绝句","c":["啼猿峡口江流远，回雁峰前沙碛晚。","水驿梅花开未开，缄情千里寄阳台。"]},{"t":"幡幡中林叶别内兄黄峻卿","f":"五言古诗","c":["幡幡中林叶，迢迢语离别。","离别不可亲，相思隔南津。","南津首北路，莽莽入烟雾。","夙昔欣芝兰，痾体成欢颜。","只恋携手好，岂知行路难。","前有一樽酒，弦歌清商曲。","行子唱骊驹，主人弹别鹄。","别鹄影悠悠，寄音下西州。","一言展契阔，再言申绸缪。"]},{"t":"江干行答禺山","f":"七言古诗","c":["吴娃江干采芙蓉，陈王洛浦赋游龙。","忽惊绣带香风起，渐觉罗裳珠露浓。","不绿织女星边见，定是嫦娥月下逢。","逢君荐枕对襄王，别君解佩悲交甫。","青云窈窕曼声歌，绿水回环垂手舞。","鸾歌凤舞无双人，燕岁莺年二八春。","百末兰生延夕漏，九华采灯烂晴昼。","金屏花里活秦宫，宝帐香中隐韩寿。","回黄转紫返复间，得新捐旧须臾后。","旧人颜色昔曾新，新人恩爱行当旧。","旧人红袖泣前鱼，新人翠羽缀燕裾。","阿娇怨赋金难买，苏蕙回文锦不如。","浊水清尘坐长叹，空留可怜谁相于。"]},{"t":"华烛引","f":"七言古诗","c":["六螭税驾眠虞渊，三爵行栖珠树烟。","云毋疏窗花作地，茱萸绣帐锦为天。","铜芝抱蒂复缠柯，金藕相萦共吐荷。","虹贯彩翚迎雨歇，蜜催香焰送风过。","桂华漏促频销麝，兰烬天寒不畏蛾。","徐吾东壁机丝少，郢相南方书误多。","菖蒲传酒座欲阑，碧玉舞罢罗裳单。","留云影射荆王枕，泫一光摇汉帝盘。","揽带盈盈君不见，脱缨脉脉两相看。"]},{"t":"又别拟制一篇","f":"七言古诗","c":["紫霞西没白日阴，兰膏明烛洞房深。","蛾飞迥向莲台度，萤爝平临桂炷沉。","鹤露雁霜惊早寒，寸心斗酒奉君欢。","火齐蟠烟全的皪，铜荷垂烬半阑干。","座中碧玉好名倡，清曥曼㫽烂齐光。","烛花剪作双胡蝶，蜡泪融成两凤皇。","便面障眉扫蛾绿，搔头坠鬓渲鸦黄。","绮结交窗窗拂曙，金鉔销香香满絮。","星翻汉回柰若何，顾影徘徊送君去。"]},{"t":"关山月","f":"七言律诗","c":["迢迢贱妾隔湘川，杳杳征人戌朔边。","分弓营对珠龟缺，挂镜台临玉兔圆。","紫塞风烟白登接，黄河波浪黑山连。","何时空外婵娟影，来照楼前歌舞筵。"]},{"t":"足唐人句效古塞下曲","f":"七言律诗","c":["长榆塞上接龟沙，碎叶城边建虎牙。","夜夜月为青冢镜，年年雪作黑山花。","苏武白头持汉节，文姬红泪泣胡笳。","可怜苜蓿迷征马，谁见蒲桃入内家。"]},{"t":"燕歌行柬程以道","f":"七言古诗","c":["玄羌白狄起边埃，翠眊朱綅选将才。","玉弩惊天连马邑，金精埽旦过龙堆。","甘泉宫里兜零举，疏勒城边汲绠摧。","射虎瞑中闻暗吼，落雕云外坠清哀。","五千深入冲寒雪，十万横行殷霁雷。","杨柳先春旗叶展，芙蓉不夜剑花开。","锦车持节夫人至，贝带韬弓骄子回。","逐北朝移行幕府，受降秋上古轮台。","青楼月对庚方出，紫塞风从丑角耒。","拟缚名王歌杕杜，肯思中妇咏条枚。"]},{"t":"题唐人闺秀慰帛图","f":"七言古诗","c":["碧梧叶落红闺晚，玫砧敲月催金剪。","重重海帘银蒜垂，曲曲山屏皂罗展。","广储悬月月初临，缇幕染霜霜已深。","禁㾕铢衣围夜玉，嵯峨宝髻辟寒金。","云毋箱开同心锁，钴鉧香浮九微火。","秦篝齐缕斗纷华，蜀锦吴绫分婀娜。","熨帛由缯忆远行，遥遥夜夜不胜情。","百层妾住垂花坞，万里君居碎叶城。","垂花碎叶音尘隔，春去秋耒感行迹。","深闺心断结蚕书，绝塞眼穿无雁帛。","明烛兰膏照独眠，蛾眉曼㫽为谁妍。","试看裴羽相思夕，何似徐吾共绩年。"]},{"t":"休洗红","f":"古风","c":["休洗红，红颜薄命恨难穷。","蛾眉倾国谁家女，十五纤腰媒未通。","金屋盈盈娇白日，锦窗的的玩春风。","戎马一朝生冀北，黄巾万骑满山东。","金缯贱弃如泥土，绝色争擒献镝锋。","火烧野田飞墅鸭，云映东方生螮蝀。","飘零自分身如叶，憔悴谁甘首似蓬。","当时不识门前路，今日能弯马上弓。","妇女何能坚节操，丈夫本自不英雄。"]},{"t":"古艳曲 其一","f":"五言古诗","c":["皎皎复盈盈，倾国更倾城。","珊瑚丝结网，苕华玉篆名。","宫女多相妒，非关君薄情。"]},{"t":"古艳曲 其二","f":"五言古诗","c":["掩颦来玉塞，顾影恋金门。","翠烛劳光彩，银屏役梦魂。","罗衣香未歇，犹是汉宫恩。"]},{"t":"邯郸才人嫁为厮卒妇","f":"古风","c":["团团桂花树，生在邯郸宫。","翩翩翡翠鸟，结巢丹桂丛。","花红何灼灼，翡翠何雍雍。","宫中有才人，颜色如花红。","青云为双髻，明月为双瞳。","十三阿母侧，十四深宫中。","真心比筠竹，荣华如茂松。","左手抱齐瑟，右手挥吴桐。","紫绮为绸缪，纨素为裁缝。","獭髓明点䵠，龙涎薰褶?。","楚蕖华跗荐，燕支唇朱融。","扬子江心镜，百鍊照胆铜。","复帷镇文犀，列钱衔壁缸。","被绣共命鸟，席坐同心狨。","蜻蛉啑凤子，鸡翘濯凫翁。","春禖燕乙乙，晓寝虫??。","芳池七十二，宝帐三千重。","名用琓琰刻，臂用绛纱封。","昔似河中鸯，今从云中龙。","云龙不可系，河鸯那得从。","君王好游猎，将军射飞鸿。","青楼临大道，层城俯雕甍。","燕兵北方来，阵马如蠛蠓。","恶氛起广陌，襄国迷旌幢。","悠悠俄转毂，去去成飘蓬。","暮看月出西，朝看日出东。","君王不可见，日月光瞳昽。","湛卢失吴剑，乌号亡楚弓。","左将名飞虎，右将名飞熊。","前军千人俊，后军万人雄。","中军张与陈，耳心馀腹同。","前使叩燕壁，后使蹑前踪。","去节何扬扬，归魂杳茕茕。","后军戒前覆，咫尺不敢通。","王宫悬赏格，赏格厚且隆。","侯印方斗大，金帛嵩丘崇。","不爱印悬斗，不爱金堆嵩。","宫中有才人，颜色如花红。","青云头上髻，明月眼中瞳。","十三阿母侧，十四深宫中。","逝将脱薪槱，归来取华容。","将军问何人，灶下厮养童。","军中骇且异，骇异交讥讽。","尔厮一何蚩，尔养一何惷。","尔去何当还，无吉祗有凶。","左将名飞虎，右将名飞熊。","前军千人俊，后军万入雄。","往往不生还，累累形影空。","??虎良吻，嗟嗟么么虫。","养卒含笑言，君岂知我衷。","君亦勿贱贱，君亦勿庸庸。","君亦勿少少，君亦勿穷穷。","勿以江海流，弃捐沟与潨。","勿以芝兰芳，弃捐菲与葑。","勿以椒欓贵，弃捐薤与葱。","君道如践棘，我道如折葼。","君道如探汤，我道如拨䵄。","我去车摇摇，我来鼓鼕鼕。","朝发赵北际，暮望燕南冲。","沐露转磨笄，戴斗但崆峒。","行行日已夕，停舟易水阴。","当门报燕将，言有赵使临。","使者问燕将，试言探臣胸。","燕将语赵使，尔欲得尔王。","赵使笑不止，尔语瞆且霿。","燕为唇齿国，赵为辅车邦。","张耳与陈馀，饥鹰待劲风。","交游如父子，遁秦联翼翪。","一朝仗马箠，下赵数十城。","各有南面志，机会不巧逢。","势屈武臣下，立王持赵心。","赵地今已定，赵王为燕擒。","耳馀握赵柄，武臣受燕笼。","王归二人臣，王囚二人公。","肯迎生王辇，惟逆死王輁。","死王良实愿，求王但虚名。","王魂化燕氛，二人喜无忡。","内举全赵势，外折弱燕锋。","问罪始有名，仗义不待攻。","王今兵在颈，行见雉离罿。","臣来吊燕祸，不求归赵功。","燕将色如土，燕王胸如春。","乞尔赵玉归，急归在匆匆。","出门不复顾，仰天荷高穹。","养卒御王归，喜气如渴虹。","前歌扬金镳，后舞踏锦幪。","荆卿羞督亢，陈驰惭迁共。","惠公返曲沃，勾践复吴淞。","山川再清朗，天地重昭明。","智靡秦樗里，勇冠夏逢门。","铜斗笑剌客，玳簪恧谈朋。","三军咸啧啧，众口交喁喁。","升为堂上宾，永脱灶下烘。","张筵列樽俎，烹羔宰肥豵。","累累系印绶，瑟瑟穿玲珑。","阳阿七槃舞，中山酒千钟。","厚赏陈前墀，养卒辞未终。","宫中有才人，颜色如花红。","可怜桃李子，降作糟覈供。","始笑周尾生，抱柱流寒淙。","复笑苏季子，愚妇不下緵。","陈馀娶公乘，张耳婚外黄。","持将比才人，才人姣无双。","宫妆扬嫭都，野态减妖秾。","殷勤语才人，才人莫心忪。","好去偕新郎，新郎非蚩氓。","繁华少佳实，丽色几欢悰。","请看古美人，命薄恨常浓。","骊姬死晋市，西施沉吴江。","黄鹄悲陶婴，蝴蝶怨韩冯。","沩汭两皇英，南望九疑峰。","斑竹泪点点，潇湘波汹汹。","章华贮巧笑，细腰如黄蜂。","峡梦啼阴猿，江眺伤青枫。","阿房三十六，烈燄惊丰茸。","娥娥总薄命，呜呜歌懊憹。","相逢恨靡芜，相思苓芙蓉。","尔名播乐府，尔芳辉管彤。","寄谢东邻子，学步休言工。"]},{"t":"赠沐锦衣","f":"五言古诗","c":["仙山名五华，迢迢上烟霞。","道逢两仙童，驻鹤问仙家。","仙家住仙村，木门苍琅根。","英英众公子，楚楚诸王孙。","舍后有碧梧，凤皇将九雏。","鸣声何喈喈，闻我蓬莱壶。","兄弟八九人，中子执金吾。","木公酌醴泉，金母斟云腴。","埙虒吟何曲，历历种白榆。","大妇七襄女，中妇重输姝。","小妇无名字，彷佛秦罗敷。","丈人且安坐，日出东南隅。"]},{"t":"月团茶歌","f":"古风","c":["腻鼎腥瓯芳醑兰，粉枪末旗香杵残。","秦女绿鬟云扰扰，班姬宝扇月团团。","兰膏点缀黄金色，花乳清泠白玉澜。","先春北苑移根易，勺水南?别味难。"]},{"t":"珠履曲","f":"七言古诗","c":["渐台织女跂东足，袜罗不染银河绿。","飞下天边三素云，来舞人间八琅曲。","白纻缭绕丰跌光，掌中无力踏春阳。","共命缕缠双躞蹀，同心丝绣五文章。","姌袅轻盈邯郸步，媻跚勃窣汉宫妒。","香裙漏影蝴蝶飞，兰膏明烛翳霄晖。","金杯潋滟浮金影，玉山摧颓偎玉寝。","梦里俄惊月入怀，醒时却讶莲生枕。","雪皱霜皴起夜来，花欹柳弱临高台。","牵牛呼龙种瑶草，不遣仙踪印归道。","笑杀梁家与石家，折腰香尘何足誇。"]},{"t":"飞燕咏","f":"五言古诗","c":["飞燕元倾国，合德更联芳。","歌舞平阳第，膏沐温柔乡。","涏涏宫中去，双双天上翔。","露华百英粉，沉水九回香。","李文明袜练，石花凝袖妆。","金釭星列影，珠帐月齐光。","避风远条馆，沃雪浴兰房。","香汤不沾体，仙飙空引裳。","吹箫庆安世，持履冯无方。","娇爱讵终极，荣华安可常。","祸水一以浸，炎火允不扬。","莫诵伶玄传，徒令樊女伤。"]},{"t":"善哉行","f":"古风","c":["夏夜苦短，冬夜苦长。","日月既逝，春华秋霜。","山川嵯峨，悬日孔多。","岂无车辕，淹留匪他。","兽有朋携，鸟有群飞。","顾瞻中林，旦往夕归。","海色东起，明星晨坠。","美人在远，寝不聊寐。","同心异乡，意遐思长。","思耒何如，弹琴中商。","附书来鸿，翩翩空疾。","愿尔千里，勿遇缯繂。"]},{"t":"梅花落四首 其一","f":"五言绝句","c":["落梅复落梅，千片复万片。","愿借鼓芳风，吹入披香殿。"]},{"t":"梅花落四首 其二","f":"五言绝句","c":["古梅飘古香，新梅缀新妆。","那枝传妾恨，何树近君乡。"]},{"t":"梅花落四首 其三","f":"五言绝句","c":["梅落复梅开，流光似流水。","君心在梅花，妾意怜梅子。"]},{"t":"梅花落四首 其四","f":"五言绝句","c":["团思更团情，依幌且依楹。","朝朝妆靥靥，日日望卿卿。"]},{"t":"合欢咏","f":"五言古诗","c":["可怜合欢树，生我庭东厢。","枝枝相纠结，叶叶复飘扬。","烟交疑覆帐，风散若分香。","戢华践西柳，开艳启东桑。","周诗惊采绿，楚梦感昏黄。","赠君以蠲忿，与妾同芬芳。"]},{"t":"峡东曲","f":"五言律诗","c":["白帝到江陵，一千二百里。","欲试一日程，须待春水起。","布帆一百尺，出自三梭织。","风顺早归来，天际遥相识。"]},{"t":"七夕曲","f":"五言绝句","c":["此夕知何夕，今秋似去秋。","凉风兼远思，并在最高楼。"]},{"t":"盘江行","f":"五言古诗","c":["可怜盘江河，年年瘴疠多。","青草二三月，绿烟生碧波。","行人好经过。"]},{"t":"七盘劳歌 其一","f":"五言绝句","c":["一盘溪谷低，仰首愁攀跻。","蚕崖白云上，鸟道金天西。"]},{"t":"七盘劳歌 其二","f":"五言绝句","c":["二盘行渐难，谷口野风寒。","石磴愁旋马，行人各解鞍。"]},{"t":"七盘劳歌 其三","f":"五言绝句","c":["三盘云雾堆，侧径转迂回。","前旌正延伫，骏骑莫相催。"]},{"t":"七盘劳歌 其四","f":"五言绝句","c":["四盘连翠微，峰日隐晴辉。","石齿啮人足，树枝罥人衣。"]},{"t":"七盘劳歌 其五","f":"五言绝句","c":["五盘势更高，俯见栖鸟巢。","岩峦暂相倚，人马同时劳。"]},{"t":"七盘劳歌 其六","f":"五言绝句","c":["六盘穷攀缘，真似上青天。","下瞰巳峻绝，上望更巍然。"]},{"t":"七盘劳歌 其七","f":"五言绝句","c":["七盘险栈平，眺望倚分明。","西征通蜀道，北望指秦城。"]},{"t":"朝天岭","f":"五言绝句","c":["落日半山坳，掩映栗叶赤。","行客早知休，前溪多虎迹。"]},{"t":"将进酒","f":"古风","c":["清酤如济，浊醪如河。","君子有酒旨且多。","我当起舞君当歌。","歌乌乌，舞傞傞，歌舞未终良夜过。","我首既濡君颜酡，古称贤达日饮何。","人生安乐，孰知其他。","将进酒，杯行迟。","主人且勿喧，君子有所思。","尧置中衢尊，文王法酒旗。","共此融融欢，无愆抑抑仪。","今汝年寿等乔松，名与金石期。","将进酒，酒且终。","乐相乐，乐无穷。"]},{"t":"鹣鹣歌","f":"古风","c":["绀宇流霜豆房冷，华烛蟠烟舞交影。","中有一人字鹣鹣，飞爵腾觚盼斜领。","莲花漏水夜无多，莫将金滴比银河。","愿为楚女巫山之行雨，不愿作甄妃洛浦之凌波。"]},{"t":"楚妃引 其一","f":"七言绝句","c":["金缸衔壁随珠烛，美人如月嬉华屋。","明星烂烂接朝霞，笑杀兰膏誇宋玉。"]},{"t":"楚妃引 其二","f":"七言绝句","c":["宵猎南梦赴长莽，火似云鲵駴雷鼓。","同车独共龙阳君，纤腰美人空楚舞。"]},{"t":"白云岩为谢左溪赋","f":"古风","c":["红云拥帝居，紫云荫仙箓。","白云何悠扬，舒卷岩之曲。","震泽昔从龙，液池曾下鹄。","出岫本无心，悬车返初服。","憬彼入深林，跫然在空谷。","风听弘景松，露采渊明菊。","菊露缀明珠，松风?球玉。","九牧谢两龚，三间谐二陆。","何日和云谣，西池春草绿。"]},{"t":"题交甫解佩图","f":"五言古诗","c":["交甫之楚游，息影依乔木。","道逢两仙姝，逍遥汉皋曲。","星宿缀明珰，云霞装鬾服。","婉娈荡荧魂，花艳惊凡目。","目随袜尘扬，魂与芳风逐。","结梦拟阳台，交辞同阿谷。","荣华橘是柚，贞芳笋成竹。","江永不可方，微波春自绿。"]},{"t":"别陈玉泉","f":"五言古诗","c":["玉人将远别，投赠琼敷篇。","惠而能好我，裴徊病榻边。","感此万里行，曷月重周旋。","秦地四方枢，神皋接英躔。","八水忽横流，九嵏俄震骞。","来旬属大雅，申画寄名贤。","平成绍禹绩，玄圭献尧天。","参井与岷嶓，星土元相连。","应念沧浪叟，好音遰鸿传。"]},{"t":"送张㠠山职方还铜梁","f":"五言古诗","c":["郊扉偃江介，炎天方郁埃。","燕居感离索，蜗庐森蒿莱。","高人千里驾，空谷跫音来。","研精既理窟，抽毫更逸才。","玄韵紫房洞，清吟文昌台。","同声起予和，笑口为君开。","樯乌五两发，兰鹢双橹催。","晤语拟倾盖，永怀盈酌罍。","愿言植嘉树，湛思肄条枝。","三峨迟屐齿，七襄冀琼瑰。"]},{"t":"续东波狂云妒佳月","f":"五言古诗","c":["狂云妒佳月，蜉蝣撼大树。","佳月了不嗔，大树何曾拒。","轻薄哂王杨，群儿谤李杜。","光燄万丈长，江河千古注。","勿言人可欺，大言终自误。"]},{"t":"怀音篇寄张惟信学士","f":"古风","c":["昆池望汉沼，滇徼视梁岷。","音耗两迢遰，眺听一伤神。","他乡非故园，浊水限清尘。","悁脰徒伫想，送躯邈何因。","有客来天末，开缄慰饥渴。","殷勤访死生，绸缪申契阔。","光仪欻若亲，穷愁暂如拨。","万里向炎隅，五载困羁孤。","山川梦张敏，岐路泣杨朱。","烛龙屡迁舍，胎蚌几盈虚。","情随瘴岚结，魂与回飙俱。","忆昔承嘉会，弱植连英蒂。","明轮仰重离，丽泽资双兑。","取则斧晲柯，同声竿混籁。","曳佩步文昌，抽毫逼华盖。","凤液接鸡栖，退食竞招携。","黄山上林苑，玄灞曲江堤。","齐镳拾瑶草，对榻然青藜。","郢客传歌妙，周郎顾曲迷。","传歌还顾曲，欢移成别促。","宁知嘤鸣鸾，忽作徘徊鹄。","去去背荣宴，行行赴严督。","三陟阻且长，百罹纷交属。","考槃岂中阿，离索异西河。","螭头辍彩笔，鹤膝拥雕戈。","北道主人少，南方迁客多。","碧鸡冠曾岭，赤虺邻荒景。","阖荆坐刬迹，剪茅旋栖影。","樵爨分獠烟，桔槔通?井。","鼓腹畏含沙，延颈愁添瘿。","枭獍笑边陬，篁竹跳蛮酋。","挈家窜草莽，乘障杂兜鍪。","乞粮公山氏，贷粟监河侯。","蓬翘随树羽，桃梗泛苔沤。","风霜瘁筋力，蒲柳凋颜色。","居夷寡凤嬉，求仙拙鷮息。","衰白岁不与，昏黄日下稷。","新知讵相闻，久要难见君。","皎皎共明月，悠悠间白云。","弃置勿复道，伊谁竟此云。","天山苏子卿，辽海崔亭伯。","觖望洛阳城，销志长安陌。","跛鳖羞骥伍，委羽非鸿翮。","下噀饶薄田，东皋馀广泽。","还乡尚有期，从君访黄石。"]},{"t":"元谋县歌","f":"五言古诗","c":["遥望元谋县，冢墓何累累。","借问何人墓，官尸与吏骸。","山川多瘴疠，仕宦少生回。","三月春草青，元谋不可行。","九月草交头，元谋不可游。","嗟尔营营子，何为欻来此。","九州幸自宽，何为此游盘。"]},{"t":"书李前渠藩伯公便面","f":"五言古诗","c":["望尘斗以北，倾盖江之阳。","命驾慰迟暮，倚楼讯行藏。","下榻沉痾失，拥彗端忧忘。","玉藻敷温丽，金薤披玻琅。","沦诗缀四始，逸籀括三苍。","荒经询夏后，汲冢怀周王。","赓皋既旦旦，聆挚何洋洋。","维时首朱夏，迅晷改青阳。","款言移日稷，彦会属辰良。","蒲葵聊短咏，木桃愧申章。"]},{"t":"九月三日见新月","f":"五言古诗","c":["纤纤初生月，挂我高楼傍。","常时照欢影，今夕流悲光。","悲光正徘徊，怅望相思台。","凉沾露襟湿，爽透风帏开。","丝虫绕阶缉，火萤穿箔来。","更添漏水咽，膏减缸花催。","庄休歌不发，潘仁心巳摧。","商陵别鹄怨，梁树栖乌哀。","未抵此时恨，长啸独难裁。"]},{"t":"恩遣戍滇纪行","f":"古风","c":["商秋凉风发，吹我出京华。","赭衣裹病体，红尘蔽行车。","弱侄当门啼，怪我不过家。","行行日巳夕，扁舟歙潞沙。","扬舲天津口，回瞻见牛斗。","风吹紫荆树，月照青杨柳。","逆流溯漕河，相顾慎风波。","荒村聚豺虎，夹岸鸣蛟鼍。","仆夫困牵挽，防吏苦嗔呵。","徐沛洪流溢，沧溟浴白日。","聚落鸡犬空，衔舻羽毛疾。","暗滩持楫防，洄溜扬帆慄。","维缆依鹳巢，搴蓬迩鲛室。","乘月下吕梁，侵星过白杨。","漫岸憬失道，孤舟郁相忘。","喧豗见叠浪，极眺无连冈。","阴霞互兴没，湅雨倏淋浪。","湿薪戒传火，空囊愁绝粮。","信宿万籁平，邻舟动欢声。","闻鸡共起舞，买鱼贺兼程。","夕泊秦淮岸，朝逗维扬城。","愁听玉箫曲，懒问琼花名。","畏途险巳出，胜地心犹惊。","真州对瓜步，分岐当去住。","翘思铁瓮云，怅望金陵树。","江浮惧涛澜，陆走淹霜露。","移船鹭洲来，弭榜龙江隈。","故人同载酒，一醉雨花台。","高台多古今，百虑盈疏襟。","琴弹别鹤调，笛喝飞鸿吟。","临风惜南鹜，揆景恨西沉。","江程始挂席，江月照采石。","招摇西北明，水雾东南碧。","铜陵梦里过，赭圻望中隔。","浔阳见市廛，湓浦异潮夕。","马口歌独漉，鱼山侯风宿。","西塞渔父矶，东陵道士洑。","估客叹浮萍，放臣悲落木。","秋惊赤岸枫，霜谢黄州菊。","龟山汉阳县，鹄矶遥可见。","披襟倚山阁，开图对离宴。","鲜飙蘋末来，馀霞波外绚。","枕底鸣飞湍，舷际失江干。","仙子驻鹤峤，王孙斗鸭阑。","云开君山出，壑归洞庭宽。","乾鹊噪危樯，连连一何迅。","试叩巴峡船，果得家乡信。","时序感孤怀，风烟集双鬓。","江陵初解帆，苍皇理征衫。","家人从此别，客泪不可缄。","腾装首滇路，问愁程楚岩。","楚水萦沅澧，楚岸秀兰芷。","古墓识昭丘，遗坊号珠履。","珠坊青芜繁，昭丘白云屯。","伤心枫树林，回首桃花源。","天寒行旅少，岁晏霜霰烦。","界亭四十渡，羸马不成步。","幽篁讵见天，密箐才分路。","营窟半卉裳，人烟尽槃瓠。","戾虫啸落景，暴客当官戌。","驱车先发煦，投驿迟瞑雾。","溆浦涔阳连，龙摽夜郎天。","远游吊屈子，长流悲谪仙。","我行更迢递，千载同潸然。","一叶崇安渡，千波竹箭急。","鬼方昔云遐，罗甸今初入。","阴霾暄凝交，瘴岚昏晓集。","长亭此驿遥，只尺如棘涩。","石行蹶昆蹄，沙炊咽蒸粒。","断肠盘江河，销魂宠嵷坡。","军堡鸣笳近，蛮营荷戟多。","三辰晦光彩，七旬历滂沱。","罽衣行风舞，芦笙眺月歌。","可怜异方乐，令人玄鬒皤。","烟霜穷琐旅，茝若开芳序。","迎睫平原来，还顾残山去。","喜见青松林，却辞黄茅屿。","滔滔岁已周，望望且夷犹。","衣尘何暇拂，足茧不能休。","碧鸡俪金马，滇海昆池泻。","五尺常頞道，万里唐蒙野。","隋将仆碑川，汉相连营下。","我行更向西，绵力倦攀跻。","硪碌穿危磴，蜻蛉控绝溪。","点苍明霁雪，抱珥饮晴霓。","蒲塞重关峻，兰津毒草低。","枝寒鸩鸟下，花煖杜鹃迷。","淜环蜮射渚，畷入象囲畦。","瑩角髦牛斗，斑文笮马嘶。","缅书涂贝叶，?照燧松梯。","风景他乡别，天倪吾道拙。","云山巳乱心，风尘仍结舌。","出门各自媚，失路为谁悦。","桑落岂忘忧，芃觿讵申结。","龙吼雄剑鸣，骥歌唾壶缺。","苍苍七星关，几时却东还。","瀰瀰三峡水，奚啻隔中沚。","黄犬代书邮，青龙借归舟。","雁翼翔廖廓，猿声递阻修。","何由一缩地，暂作锦江游。"]},{"t":"出嘉陵江","f":"五言古诗","c":["嘉陵驶且长，千里如投梭。","洋洋者绿水，触石扬白波。","逶迤似有情，相送出褒斜。","云气接江脑，日色破浪花。","冥冥下无极，疑是神龙家。","垂藤饮猿狖，奫沦栖阳阿。","中有南行舟，遥遥通三巴。","惜哉不可往，巨石剧狼牙。","我欲镵安流，手中无莫邪。","长歌行路难，日莫犹天涯。"]},{"t":"崤关行","f":"五言古诗","c":["晨行崤关道，此道一何难。","曾陵高不极，脩坂回郁盘。","季冬十二月，时节正严寒。","马啼践霜雪，车辙带冈峦。","淩澌正坚冱，河水无汍澜。","通逵结冻溜，改径陟巑岏。","四望少烟火，鸟路俯鸿磐。","悲风号古水，响入玄云端。","居人尽塞向，行者为槃跚。","野狼啸昏侣，饥雁短晚翰。","迢迢村郭远，行行未解鞍。","凛凛岁方晏，去去程犹宽。","劳歌以咏志，释此越乡叹。"]},{"t":"集弘法寺后圃小山","f":"五言古诗","c":["黄鸟语春晚，青林生夏阴。","禅宫静钟梵，宁知车马音。","率尔成嘉遇，晤言良所钦。","对酒俯楼殿，步屣陟丘岑。","谋野既有获，在远亦会心。","怀哉幽寂地，兹游可重寻。","扰扰望城闉，欲去愧尘襟。"]},{"t":"于离会作","f":"五言古诗","c":["遥遥事行役，落落无安居。","奉义徂江汉，成旅候轺车。","密亲念暌隔，宾筵集华裾。","流声何肃穆，照夜交瑛玙。","率尔拜嘉贶，何以报相于。","烟霜易淹留，日月方向除。","曲湟浮绿藻，太液敷丹渠。","欲嗣北来音，托之西上鱼。"]},{"t":"荅程以道","f":"五言古诗","c":["驱马国西门，整驾城南端。","出宿指宾馆，饮饯临河干。","中道逢嘉友，谁云行路难。","四海皆兄弟，况是平生欢。","赠我锦绣段，佩之当衿鞶。","上缕胶与漆，下绘芝与兰。","芝兰芳不歇，胶漆情无殚。","愿为双飞凫，随君千里翰。"]},{"t":"西使将旋卧病移旬","f":"五言古诗","c":["江汉起秋色，池塘生夕阴。","萧条众芳敛，啁唽候虫吟。","清光徘徊映，圆景散空林。","采芝歌不发，鍊药行相寻。","隐囊废丹帙，对晃虚清琴。","怀哉北望瞩，怆矣西飞心。","端忧与云结，商声随风骎。","晏然山中暮，弱怀良难任。"]},{"t":"行旅","f":"五言古诗","c":["行旅苦日短，劳人知路遥。","忽忽岁云莫，客心中摇摇。","矌野饶寒气，四望但寂寥。","严霜下丰草，朔风鸣枯条。","浮云起为盖，坚冰结为桥。","白日隐馀照，玄阴晻层霄。","鸣毂无停轮，嘶马不解镳。","飞鸟夕知还，征途何迢迢。","无以慰苦辛，兴言自成谣。"]},{"t":"过河内作","f":"五言古诗","c":["晨行河内道，矌然清客心。","太行北麓近，丹流东逝深。","丛芳金碧岸，总翠瑛瑶林。","蒲梢递馀馥，柿叶垂繁阴。","在藻归乐泳，迁乔闻好音。","客行虽云苦，对此一开襟。","既怀击壤咏，复动沧浪吟。","古风美乐土，兹情验于今。"]},{"t":"感秋","f":"五言古诗","c":["江汉流无极，浮云去靡依。","类此远游子，乘障戍边圻。","故乡三千里，山川隔音徽。","日夕桀括栖，凉秋熠耀飞。","离索星霜改，端忧节序违。","处者怨不詹，行人叹式微。","焉得排云翼，遥随征鸿归。"]},{"t":"留别峨石李子杂用选句","f":"五言古诗","c":["美人仙李姿，相期拾瑶草。","讵意旋岚风，吹我千里道。","轻舟已迅迈，归信方浩渺。","所是同心者，不得殊怀抱。","隔江犹恨遥，何况滇云杪。","路远梦魂迷，思君令人老。","愿托上林鸿，好音及春早。"]},{"t":"晨发高峣柬丘月渚杨墨池","f":"五言古诗","c":["荒鸡嗥西邻，海霞射东壁。","又携孤剑征，去作点苍客。","高峣亦吾庐，安宁亦予宅。","屏居三十年，宛如故乡陌。","飞屐频登临，披衣数晨夕。","别离今几时，重到感畴昔。","儿童巳长成，宾从尽衰白。","联榻情绸缪，晤语慰衰瘠。","此行拟何为，筋力疲疆场。","少城云思纷，江阳春梦积。","一身四处家，浮生百龄迫。","请为劳者歌，歌罢转愁剧。"]},{"t":"五日汎湖","f":"五言古诗","c":["鸡鸣海色动，日出林霏开。","红霞晃金碧，赤帝骑龙来。","新晴宜理棹，㑂佛游仙台。","榜歌声流喝，丝管清且谐。","且须醉一斗，以缓肠九口。"]},{"t":"南窜始发京","f":"五言古诗","c":["秋风萧萧发，驱车出郭东。","问我今何适，窜身向南中。","南中万馀里，去去与谁同。","亲交满京国，只尺难相通。","且喜脱幽絷，未睱悲道穷。","矫目盼浮云，但羡高飞鸿。"]},{"t":"江陵别内","f":"五言古诗","c":["同泛洞庭波，独上西陵渡。","孤棹溯寒流，天涯岁将暮。","此际话离情，羁心忽自惊。","佳期在何许，别恨转难平。","萧条滇海曲，相思隔寒燠。","蕙风悲摇心，菵露愁沾足。","山高瘴疠多，鸿雁少经过。","故园千万里，夜夜梦烟萝。"]},{"t":"离思行 其一","f":"五言古诗","c":["飞蓬无根株，飘飖随风起。","游子辞家乡，流落在万里。","当歌有苦调，对酒无欣喜。","闭门愁绪集，出门多荆杞。","徬徨安所之，断肠分流水。","水流何潺湲，远游几时还。"]},{"t":"离思行 其二","f":"五言古诗","c":["南望蜻蛉道，西眺渠滥川。","石子何磊磊，水流何煎煎。","山川隔宇县，仰视空云烟。","鸿飞远不到，书迹何由传。","愁来坐自叹，气结不能言。","愿假黄鹄羽，轻举随风旋。"]},{"t":"采兰引","f":"五言古诗","c":["秋风众草歇，丛兰扬其香。","绿叶与紫茎，猗猗山之阳。","结根不当户，无人自芬芳。","密林交翳翳，鸣泉何汤汤。","欲采往无路，局步愁褰裳。","美人驰目成，要予以昏黄。","山谷岁复晚，脩佩为谁长。","采芳者何人，荪芷共升堂。","徒令楚老惜，坐使宣尼伤。","感此兴中怀，弦琴不成章。"]},{"t":"送陈德润还茂州 其一","f":"五言古诗","c":["钟鼓宁乐鴳，文绣讵饰豨。","近随扶摇翔，何似抢榆飞。","劳者恒思息，游者恒思归。","达生贵止足，君子当知几。","宦途类婴网，䅋驾真解徽。","阳阿可晞发，高岗堪振衣。","亹亹时过中，戚戚何歔欷。","相期保耋齿，逍遥敬良晖。"]},{"t":"送陈德润还茂州 其二","f":"五言古诗","c":["井络当坤维，岷山出其腹。","神禹生兹乡，石纽何葱郁。","采药遣古亭，读书留往谷。","灵峰隐秘文，名山藏仙箓。","薤尾翔飘鸾，穗书昂立鹄。","瑞恊宛委图，辉映岣嵝曲。","早慕子长游，晚滞周南躅。","烦君窈窕寻，寄余琳琅录。"]},{"t":"双节篇为参戎郭云屏二母","f":"五言古诗","c":["周南摽李兰，卫风咏柏舟。","淑闻播三族，苦节传千秋。","郭门有双节，今古与同俦。","千金护襁褓，九原安松楸。","保抱自黄口，相依到白头。","仍云继阀阅，将星绍箕裘。","天道岂无知，世泽楚水流。","丛桂既林森，慈竹还脩脩。","令伯陈情表，惓惓思报刘。","圣代倚长城，岂容归林丘。","不日丝与纶，封章下冕旒。","我歌双节篇，石室他年收。"]},{"t":"寄余懋昭","f":"五言古诗","c":["夙昔梦见君，揽衣颠倒裳。","系君骅骝马，要我野游翔。","贻我金仙文，合诵声琅琅。","方舟青衣水，共钓鲤与鲂。","晤言交款款，携手何洋洋。","觉来一何见，累然在南荒。","荒鸡嗥东邻，明月悬西方。","搴帷成起坐，长啸达晨光。","因之万里风，慰言企来章。"]},{"t":"拟行行重行行","f":"五言古诗","c":["遥遥涉长途，悠悠愁我心。","我心愁未央，暌离日以深。","山高水无梁，寄书多浮沉。","鱼乐在故渊，鹿鸣思长林。","觉时影与身，梦来裯与衾。","端居迟日月，旦暮如古今。","孤愿人讵知，沉忧自难任。","君子不遐弃，怀我以好音。"]},{"t":"庭中有奇树","f":"五言古诗","c":["奇树生南国，孤根来远方。","隹名谁不爱，植近君子堂。","春风一披拂，花叶何炜煌。","上有寄生枝，亦得沾恩光。","桂枝陵寒山，梧桐在高冈。","草木非自献，信美非所将。"]},{"t":"续百一诗 其一","f":"五言古诗","c":["齐庭陈大吕，荆国起巫音。","雪宫繁钟鼓，朝云进荒淫。","韶䪫既已远，凤鸟不复吟。","中和变贞则，哀怨荡人心。","师矌奏清角，晋壤飞祅祲。","曲工知烱戒，灿言成良箴。","乐象析理乱，谁言古犹今。"]},{"t":"续百一诗 其二","f":"五言古诗","c":["佽飞佩宝剑，涉江遇阳侯。","风涛起连山，双蛟夹行舟。","舟人甘朽骨，壮士故不忧。","解衣谢行侣，拔剑探灵湫。","剌蛟同剸蚓，怒浪成安流。","名垂千载誉，位取三圭酬。","嗤彼越王孙，榜歌戏中流。"]},{"t":"续百一诗 其三","f":"五言古诗","c":["豫让感知己，之死无二心。","青茾敦友义，捐躯酬断金。","煌煌彼二节，照曜古与今。","国士有馀誉，参乘无知音。","何当续良史，鸿笔兴幽沉。"]},{"t":"续百一诗 其四","f":"五言古诗","c":["无恤营襄国，诡遇树崇勋。","宝符吞中山，铜斗挥代君。","都邑曜错绣，戈鋋耿长云。","天道如环运，人事犹玦分。","平原生荿草，邯郸起烟氛。","一为房陵讴，凄恻谁能闻。"]},{"t":"续百一诗 其五","f":"五言古诗","c":["许由轻九州，归休娱颖颜。","共伯弃千乘，结隐巢首山。","渔钓性自适，轩冕忧相关。","泽雉苦樊笼，神龙乐潺湲。","何事子牟心，犹存魏阙间。"]},{"t":"续百一诗 其六","f":"五言古诗","c":["大禹入祵邦，累然解衣行。","墨子见荆王，锦衣吹玉笙。","岂不易性素，所重在全生。","栖栖非余志，皦皦非余情。","所愧先机者，飘然反柴荆。","被褐怀珠玉，何人知姓名。"]},{"t":"续百一诗 其七","f":"五言古诗","c":["墨子回车地，朝歌佳丽丛。","新台既清洒，淇水复春融。","锵如南子佩，锦车同卫公。","隋珠光照日，罗衣香从风。","招摇过柳市，繁华惊娈童。","垝垣望复关，桑中接上宫。","咄哉赞好德，后乘有蹲龙。"]},{"t":"续百一诗 其八","f":"五言古诗","c":["周鼎铸饕餮，有首不见身。","食人未下咽，灾害旋相因。","祸福互倚伏，龙蛇有屈伸。","何事悠悠子，狂冥若眯尘。","感彼塞翁言，宜用书君绅。"]},{"t":"续百一诗 其九","f":"五言古诗","c":["郑国有良贾，弦高与奚施。","西市黍离国，东遇虎狼师。","乌犍纳犒质，白壁通款辞。","乙丙已奋气，殽函成积尸。","小邦得干城，强敌亦何为。"]},{"t":"续百一诗 其十","f":"五言古诗","c":["楚女竞吴桑，两国遂交兵。","膏血润百里，宝玉弃连城。","蚁穴溃金堤，爝火熛山楹。","毫釐一为跌，寻丈忽已倾。","由蘖在彊场，捍禦非干旌。","安得起宋就，永息瓜亭争。"]},{"t":"续百一诗 其十一","f":"五言古诗","c":["尺木既有节，寸玉亦有瑕。","清螭游浊水，玄泽□金沙。","小夫工指摘，巧言多諠哗。","丘蚓嗤蛰龙，折杨笑皇华。","不遇明哲人，终然成叹嗟。"]},{"t":"续百一诗 其十二","f":"五言古诗","c":["隙阴审时运，瓶冰知天寒。","行人在万里，道路多险难。","放辙愁羊肠，方舟畏狂澜。","渺渺音问阔，迢迢岁月殚。","采绿动朝思，葛生劳夕叹。","愿言托宵梦，驰景随飞翰。"]},{"t":"续百一诗 其十三","f":"五言古诗","c":["齐后厌佛士，甘与鲋鲵居。","狐咺行哭谏，陈斧斮东闾。","囹圄系鸾凤，珩璜带猿狙。","燕兵一旦至，国象成剥庐。","达生走奔绥，触子驰亡车。","遂令爽鸠乐，鞠为草莽墟。","麋鹿游苏台，不独伤子胥。"]},{"t":"续百一诗 其十四","f":"五言古诗","c":["东方本彦士，和光在尘喧。","窃桃朱鸟窗，避世金马门。","狎俗犹鸥鸟，齐物若鴳鹍。","虚称羽人流，空拟岁星魂。","柱下自异曲，滑稽岂同源。","惟应夏泰初，千载契知言。"]},{"t":"续百一诗 其十五","f":"五言古诗","c":["葛藟萦樛木，兔丝附女萝。","夭夭二小草，洪荫仰巨柯。","酆邑美任姒，湘渚咏英娥。","彤管久尘翳，妒津生洛河。","青史伤人彘，黄云惊女讹。","骣牛信可乘，良法在金科。"]},{"t":"东望楼","f":"五言古诗","c":["男子志四方，焉能守一丘。","壮游轻万里，逸迹淩九州。","抚时厌迫隘，胡为此淹留。","越乡悲南冠，骋望登东楼。","遥树小如荠，连峰如波流。","穹谷无足音，远水无归舟。","跳听何所见，驰目空悠悠。","海曲歌五噫，天末咏四愁。","崇山自兴恻，旷野谁与俦。","焉得云螭驾，托乘从霄浮。"]},{"t":"碧对轩","f":"五言古诗","c":["仲尼从凤嬉，子云慕鸿飞。","兴托寥天廓，迹与名山依。","伊予事执鞭，夙龄脱絷鞿。","考室临苍莽，开轩面翠微。","碧鸡栖灵景，彩翚曜烟霏。","英岊耸升望，晴峦引高晞。","会心生远意，娱人留清辉。","玉露缀丹研，璧月流金徽。","息偃忘坐起，晤言无是非。","柱下有遗言，所贵知我希。"]},{"t":"学樊圃","f":"五言古诗","c":["夙尚丘园心，憬彼逍遥乐。","幸从黑衣行，得谢朱丝缚。","锄榛理荒畴，薙茸搴长薄。","抱瓮代桔槔，树枳当篱落。","春秋莳韭菘，阴阳分蔼藿。","寒瓜织女荐，云实仙人削。","紫苋春雨零，绿葵晨露泊。","下箸有常期，加餐无爽诺。","厌酌宾筵醴，宁羡屠门嚼。","聊为野人谋，毋诒君子噱。"]},{"t":"辩义井","f":"五言古诗","c":["息壤海脉通，幽壑泉华注。","浚发百尺灵，沛泽千人聚。","光烂九霞浆，美吸三危露。","朝绠环村氓，夕杓喧邻孺。","碧甃自葳蕤，银床谢雕铸。","南中饶炎燠，北陆无凝固。","漱盥冰齿寒，存想玄发驻。","蒙庄笑塪蛙，羲象占谷鲋。","甘芳本易竭，澄渫良难遇。","且从投辖饮，休伤轠瓽赋。"]},{"t":"悠然亭","f":"五言古诗","c":["萧萧者东篱，峨峨者南山。","山色无远近，如在咫尺间。","茅亭敞潇洒，荜门恒反关。","朝见归云驶，暮见飞鸟还。","飞鸟不可即，归云不可攀。","怅我穷荒谪，再见篱菊班。","列树何丰茸，流泉亦潺湲。","永日无氛翳，地隙景自閒。","时枉幽人侣，暂解游子颜。","清风巳千载，馀波及颓顽。"]},{"t":"拟古","f":"五言古诗","c":["上山采交藤，下山逢老翁。","发白颜转少，疑是古韩终。","此翁何所居，乃在深山中。","左右猿狖穴，前后虎豹丛。","风云径路绝，人迹那能通。","问年不肯荅，长啸气何雄。","翩然轻举去，策杖如飞鸿。"]},{"t":"大中丞百川张公招饮静居寺十四韵","f":"古风","c":["韶序届仲春，迟晷正骀荡。","好音流晛睆，时服改纤纩。","英衮枉嘉招，夙驾东闉仗。","祗园敞静居，香灯护龙象。","名言析秋毫，陆海披珍藏。","稔岁华黍礼，乐郊天丝飏。","曲水迹非陈，斜川图可仰。","披雾吟泬寥，谋野乘闲矌。","晏粲倚文翁，式遏怀葛亮。","下走本陈人，汎爱容衰恙。","芰制厕端旒，尘容醉清?。","信宿枉仙翰，何以酬台贶。","杲旭烛覆盆，灵籁鸣塞巷。","永言讵能殚，镂膺矢无忘。"]},{"t":"言将北上述志一首荅苏从仁恩王子衡","f":"五言古诗","c":["我辞承明直，矫志青云端。","销声绝车马，卧痾对林峦。","甘此皋壤怡，谢彼飙霭干。","晨夕咏凿井，春秋歌伐檀。","奔曦岂不疾，国火三改钻。","游子恋所生，不获常怀安。","微尚何足云，弱质良独难。","衡门坐成远，尘冠行复弹。","已负濩落性，更从樗散官。","进阻岩廊议，退抱江湖叹。","矌哉宇宙内，吾道何盘桓。"]},{"t":"送黄才伯册封藩府南渭","f":"五言古诗","c":["泛泛东行舟，迢迢南渭流。","沦波环楚壤，脉别引丹丘。","竹屿临湘烟，枫门映离日。","金节斗边来，青翰天上出。","分圭剪桐底，鸣珂衣锦乡。","江干旋露盖，海曲卸云装。","西岸搴芙蓉，东周折杨柳。","燕喜拜华堂，鸾讴献春酒。","握兰五夜直，采萧三秋期。","跂予饥渴想，迟尔琼树枝。"]},{"t":"登大慧寺逌然台是日杜鹃鸣于北都","f":"五言古诗","c":["驱马出城阙，置酒临高台。","高台见百里，坐望西山隈。","云气何飘飘，㑂佛接蒿莱。","前有芳树林，清阴郁徘徊。","飞鸟遗之音，宛转悽以哀。","杜鹃非北羽，谁遣从南来。","常恐商飙发，使我脩兰摧。","长歌行路难，感激伤中怀。"]},{"t":"和余懋忠青衣别后追寄之作","f":"五言古诗","c":["抽簪画江沙，写出肠断词。","遥寄百里人，见君昨夜思。","昨夜复今朝，百里又千里。","欢游坐成隔，乖离从此始。","乖离渺何许，异国犹乡土。","云从青衣来，月自峨眉吐。","云月两悠悠，光景为君留。","因之托宵梦，远到海西头。"]},{"t":"琼音篇寄康对山","f":"五言古诗","c":["晨逢南州牧，携手滇之阴。","言从太白来，贻我琼黄音。","题封五云烂，开缄双凤吟。","伊人先鸣者，夙龄晏清襟。","良史古班马，逸民今尚禽。","商泛悯宋玉，刍委嗟师金。","沜东青霞想，浒西紫芳心。","戎旅未云返，嵇驾何由寻。","因声万里风，调短情方深。"]},{"t":"赠张愈光诗 其一","f":"五言古诗","c":["孔雀生南涪，裴回紫蔚林。","文采既彪炳，与世亦殊音。","时哉固多觭，弶罗比见寻。","羽毛棽以俪，阿阁迥且深。","一弹哀鸾唱，再抚孤鹣吟。","荒涂不可践，为君愁我心。"]},{"t":"赠张愈光诗 其二","f":"五言古诗","c":["迢迢禺氏山，珠壁交晶英。","二六照梁乘，三五连赵城。","两美必相合，谁言容易并。","刖足伤卞盉，按剑嗟枚生。","子续艰征赋，余和从军行。","同心复同患，日暮天末情。"]},{"t":"赠张愈光诗 其三","f":"五言古诗","c":["大雅沦千载，正声代以微。","鹰隼乏翰采，雉晕无高飞。","有鸟来西极，羽群实所稀。","风穴吸沆瀣，天池濯毛衣。","翙翙千仞翔，郁郁九苞辉。","君才文苑凤，隼雉焉能希。","梧枯醴泉渴，日暮恒苦饥。","何时逢天老，驾言玄扈归。"]},{"t":"送终安人王氏葬恩波阡","f":"五言古诗","c":["石流何湔湔，湟潦增其波。","天阴日勿晚，旷野悲风多。","严霜下乔木，零雨泫柔柯。","萧条我行野，伤心悲如何。","中道失嘉耦，送此山之阿。","凛凛岁方宴，谁与同啸歌。","加看彼鸟雀，各自安其窠。"]},{"t":"效古","f":"五言古诗","c":["朝游巍峨宫，暮坠峥巆壑。","面笑皆成叹，春华秋已落。","耳馀互侵陵，田窦相倾夺。","富贵生不仁，荣华有销铄。","何如商山翁，茹芝咏莫莫。","冥鸿度逵陵，樊笼岂栖托。"]},{"t":"双鱼铺","f":"五言古诗","c":["岧岧山上亭，上有双鱼字。","回顾望新城，欲将双鱼寄。","泛泛东水流，蘋藻相蒙翳。","钓竿何袅袅，鱼尾何曾丽。","缄意付归风，日暮江之汜。"]},{"t":"送崇庆白判官","f":"五言古诗","c":["宦迹标南郡，贤劳赋北山。","分携千里外，留滞一年间。","梅阁春全隔，花宫月几弯。","水声随露冕，尘路损风颜。","别路遥岑合，离亭二水环。","永言君子赠，怀惠野人攀。","共道莺迁近，来瞻马首还。"]},{"t":"送曾东石","f":"五言古诗","c":["文鸟生岷山，来翔十二楼。","览德箫韶下，长鸣向南州。","翩翩慕俦者，㒽言不可留。","河梁一相送，飘风吹方舟。","山川隔光彩，嘉会期三秋。","清商易终曲，何以慰离愁。","常恐丽泽远，索居多愆尤。","驰心如日月，光彩随南流。","脱有归飞翼，因之问阻脩。"]},{"t":"秋日杂诗 其一","f":"五言古诗","c":["秋霖溢城阙，后土何时乾。","周行无轨辙，出入阻且艰。","长安有一士，荜门昼长关。","开径理蓬蒿，荒我蕙与兰。","蕙兰日将歇，蓬蒿不可删。","仰首向浮云，慨然增永叹。"]},{"t":"秋日杂诗 其二","f":"五言古诗","c":["羲和运天晷，候虫和岁阴。","昔为莎鸡羽，今为蟋蟀吟。","感彼萧条节，动此栖迟心。","旅人在异乡，相思梦同衾。","登临一以眺，但见丘与岑。","清泠含广泽，悲商印遥林。","结轸还归来，当轩抚鸣琴。","幽兰久不奏，谁哉知此音。"]},{"t":"赠钱少容佥事","f":"五言古诗","c":["之子体英彦，弱龄称国华。","先名出艺苑，发迹翼名家。","澄清揽飞辔，亨衢有高车。","仪凤自览德，神羊本触邪。","当今爽鸠墟，千载同其嘉。","翱翔属宇县，音尘非天涯。","离居欲有赠，持此代疏麻。","勿言吏道迫，坐令尔音遐。"]},{"t":"送徐用先归嘉州","f":"五言古诗","c":["客有归欤叹，言从隐者流。","高议在青琐，吾道付沧洲。","沧洲多故人，夙昔谐幽赏。","啸歌丹崖边，携手紫霞上。","壁津春水生，波浪动江城。","岷岭秋芳落，清音满兰若。","亦知江湖忧，不废登临乐。","迢迢结桂枝，望望阻相思。","殷勤三岁字，惆怅四愁诗。","伊予慕俦侣，暌离分晤语。","何时峨眉云，来作人问雨。"]},{"t":"送王舜典知成都","f":"五言古诗","c":["新解郎官绶，遥分太守符。","严程趋左蜀，归榜过东吴。","玉垒关云净，青城岭月孤。","乾坤回治象，江海接亭衢。","露冕仁风播，随车解泽濡。","滮流通暍壤，生色到寒芜。","筐篚穷方贡，兜鍪罄国须。","几年怀乐职，今日会昭苏。","廉范歌当继，王褒颂不谀。","循良千古事，肯负两轮朱。"]},{"t":"和方思道毛坞之什 其一","f":"五言古诗","c":["冉冉孤生竹，迟此方苞月。","玉节本璘珣，孚尹亦旁达。","丛棘纷纠缠，兴言谁剪伐。","诗人执斧柯，君子在林樾。","朝看清阴成，暮听商飙发。","一歌猗兰荣，再占泰茅拔。","不有栽培心，曲直竟何掘。"]},{"t":"和方思道毛坞之什 其二","f":"五言古诗","c":["袅袅杉上藤，翳此荒水滨。","蛇蚓一以结，虬龙何申申。","清风扇中壤，渥露漙高旻。","奇树既有华，散木亦有身。","岁寒异凋谢，发生何齐匀。","匏瓜徒自系，持此叹迷津。","谁当贡衢室，上与阶蓂伦。"]}]};